String _getPresidentCardRank(String card) => card.substring(0, card.length - 1);

int _getPresidentCardValue(String card, bool isRevolutionActive) {
  final rank = _getPresidentCardRank(card);
  if (isRevolutionActive) {
    return _presidentCardValuesRevolution[rank]!;
  }
  return _presidentCardValues[rank]!;
}

int _comparePresidentCards(String a, String b, bool isRevolutionActive) =>
    _getPresidentCardValue(
      a,
      isRevolutionActive,
    ).compareTo(_getPresidentCardValue(b, isRevolutionActive));

enum HandRank {
  highCard,
  onePair,
  twoPair,
  threeOfAKind,
  straight,
  flush,
  fullHouse,
  fourOfAKind,
  straightFlush,
  royalFlush,
}

class PokerCard implements Comparable<PokerCard> {
  final String suit;
  final String rank;
  final int value;

  PokerCard(String cardStr)
    : suit = cardStr.substring(1),
      rank = cardStr.substring(0, 1),
      value = _getRankValue(cardStr.substring(0, 1));

  static int _getRankValue(String rank) {
    const rankValues = {'T': 10, 'J': 11, 'Q': 12, 'K': 13, 'A': 14};
    return rankValues[rank] ?? int.tryParse(rank) ?? 0;
  }

  @override
  int compareTo(PokerCard other) => other.value.compareTo(value); // Descending order

  @override
  String toString() => '$rank$suit';
}

class PokerHand implements Comparable<PokerHand> {
  final HandRank rank;
  final List<int> kickerValues; // Values of the 5 cards making the hand

  PokerHand(this.rank, this.kickerValues);

  @override
  int compareTo(PokerHand other) {
    if (rank.index != other.rank.index) {
      return other.rank.index.compareTo(rank.index); // Higher rank wins
    }

    for (int i = 0; i < kickerValues.length; i++) {
      if (kickerValues[i] != other.kickerValues[i]) {
        return other.kickerValues[i].compareTo(kickerValues[i]);
      }
    }
    return 0; // It's a tie
  }

  @override
  String toString() => '${rank.name} with kickers: $kickerValues';
}

class PokerHandEvaluator {
  static PokerHand evaluateHand(List<String> sevenCardsStr) {
    final List<PokerCard> sevenCards =
        sevenCardsStr.map((c) => PokerCard(c)).toList();

    final combinations = _getCombinations(sevenCards, 5);

    PokerHand? bestHand;
    for (final combo in combinations) {
      final hand = _evaluateFiveCards(combo);
      if (bestHand == null || hand.compareTo(bestHand) > 0) {
        bestHand = hand;
      }
    }
    return bestHand!;
  }

  static List<List<T>> _getCombinations<T>(List<T> list, int length) {
    if (length == 0) return [[]];
    if (list.isEmpty) return [];

    final T head = list.first;
    final List<T> tail = list.sublist(1);

    final withoutHead = _getCombinations(tail, length);
    final withHead =
        _getCombinations(
          tail,
          length - 1,
        ).map((combo) => [head, ...combo]).toList();

    return [...withHead, ...withoutHead];
  }

  static PokerHand _evaluateFiveCards(List<PokerCard> fiveCards) {
    fiveCards.sort(); // Sort descending by value

    final values = fiveCards.map((c) => c.value).toList();
    final suits = fiveCards.map((c) => c.suit).toList();
    final isFlush = suits.toSet().length == 1;

    final isStraight = _isStraight(values);

    if (isStraight && isFlush) {
      if (values[0] == 14) return PokerHand(HandRank.royalFlush, values);
      return PokerHand(HandRank.straightFlush, values);
    }

    final rankCounts = _getRankCounts(values);
    final counts = rankCounts.values.toList()..sort((a, b) => b.compareTo(a));

    if (counts[0] == 4) {
      // Four of a kind
      final fourValue = rankCounts.entries.firstWhere((e) => e.value == 4).key;
      final kicker = values.firstWhere((v) => v != fourValue);
      return PokerHand(HandRank.fourOfAKind, [
        fourValue,
        fourValue,
        fourValue,
        fourValue,
        kicker,
      ]);
    }

    if (counts[0] == 3 && counts[1] == 2) {
      // Full House
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final twoValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      return PokerHand(HandRank.fullHouse, [
        threeValue,
        threeValue,
        threeValue,
        twoValue,
        twoValue,
      ]);
    }

    if (isFlush) return PokerHand(HandRank.flush, values);
    if (isStraight) return PokerHand(HandRank.straight, values);

    if (counts[0] == 3) {
      // Three of a kind
      final threeValue = rankCounts.entries.firstWhere((e) => e.value == 3).key;
      final kickers = values.where((v) => v != threeValue).toList();
      return PokerHand(HandRank.threeOfAKind, [
        threeValue,
        threeValue,
        threeValue,
        ...kickers,
      ]);
    }

    if (counts[0] == 2 && counts[1] == 2) {
      // Two Pair
      final pairs =
          rankCounts.entries
              .where((e) => e.value == 2)
              .map((e) => e.key)
              .toList()
            ..sort((a, b) => b.compareTo(a));
      final kicker = values.firstWhere((v) => v != pairs[0] && v != pairs[1]);
      return PokerHand(HandRank.twoPair, [
        pairs[0],
        pairs[0],
        pairs[1],
        pairs[1],
        kicker,
      ]);
    }

    if (counts[0] == 2) {
      // One Pair
      final pairValue = rankCounts.entries.firstWhere((e) => e.value == 2).key;
      final kickers = values.where((v) => v != pairValue).toList();
      return PokerHand(HandRank.onePair, [pairValue, pairValue, ...kickers]);
    }

    return PokerHand(HandRank.highCard, values);
  }

  static bool _isStraight(List<int> sortedValues) {
    if (sortedValues.toSet().containsAll({14, 2, 3, 4, 5})) return true;

    for (int i = 0; i < sortedValues.length - 1; i++) {
      if (sortedValues[i] != sortedValues[i + 1] + 1) return false;
    }
    return true;
  }

  static Map<int, int> _getRankCounts(List<int> values) {
    final counts = <int, int>{};
    for (final value in values) {
      counts[value] = (counts[value] ?? 0) + 1;
    }
    return counts;
  }
}

class MultiplayerTeamSelectionDialog extends StatefulWidget {
  final String gameCode;
  final Map<String, dynamic> players;
  final Map<int, List<String>>
  initialTeams; // Modifié pour accepter plusieurs équipes
  final String gameName;
  final int minTeams;

  const MultiplayerTeamSelectionDialog({
    Key? key,
    required this.gameCode,
    required this.players,
    required this.initialTeams,
    required this.gameName,
    this.minTeams = 2,
  }) : super(key: key);

  @override
  _MultiplayerTeamSelectionDialogState createState() =>
      _MultiplayerTeamSelectionDialogState();
}

class _MultiplayerTeamSelectionDialogState
    extends State<MultiplayerTeamSelectionDialog> {
  late List<String> unassignedPlayers;
  late Map<int, List<String>> teams;
  final FirebaseService _firebaseService = FirebaseService();

  final List<Color> teamColors = [
    Colors.redAccent,
    Colors.blueAccent,
    Colors.greenAccent,
    Colors.orangeAccent,
    Colors.purpleAccent,
    Colors.cyanAccent,
  ];

  @override
  void initState() {
    super.initState();
    teams = Map<int, List<String>>.from(widget.initialTeams);

    if (teams.isEmpty) {
      for (int i = 0; i < widget.minTeams; i++) {
        teams[i] = [];
      }
    }

    final allAssigned = teams.values.expand((playerList) => playerList).toSet();
    unassignedPlayers =
        widget.players.keys.where((pId) => !allAssigned.contains(pId)).toList();
  }

  void _addTeam() {
    setState(() {
      if (teams.length < 6) {
        // Limite à 6 équipes pour l'UI
        teams[teams.length] = [];
      }
    });
  }

  void _removeLastTeam() {
    setState(() {
      if (teams.length > widget.minTeams) {
        int lastTeamKey = teams.keys.last;
        List<String>? playersToUnassign = teams[lastTeamKey];
        if (playersToUnassign != null) {
          unassignedPlayers.addAll(playersToUnassign);
        }
        teams.remove(lastTeamKey);
      }
    });
  }

  void _assignPlayer(String playerId, int teamIndex) {
    setState(() {
      unassignedPlayers.remove(playerId);

      for (var team in teams.values) {
        team.remove(playerId);
      }
      teams[teamIndex]?.add(playerId);
    });
  }

  void _unassignPlayer(String playerId, int fromTeamIndex) {
    setState(() {
      teams[fromTeamIndex]?.remove(playerId);
      if (!unassignedPlayers.contains(playerId)) {
        unassignedPlayers.add(playerId);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = widget.players.keys.toList()..shuffle();
      unassignedPlayers.clear();
      teams.forEach((key, value) => value.clear()); // Vider toutes les équipes
      for (int i = 0; i < all.length; i++) {
        int teamIndex = i % teams.length;
        teams[teamIndex]?.add(all[i]);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm = unassignedPlayers.isEmpty;

    return AlertDialog(
      title: Text("Équipes pour ${widget.gameName}"),
      content: Container(
        width: double.maxFinite,
        height: 500, // Augmenté pour l'UI
        child: Column(
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton.icon(
                  icon: Icon(Icons.sync),
                  label: Text("Équilibrer"),
                  onPressed: _autoBalance,
                ),
                ElevatedButton.icon(
                  icon: Icon(Icons.add),
                  label: Text("Équipe"),
                  onPressed: _addTeam,
                ),
                if (teams.length > widget.minTeams)
                  ElevatedButton.icon(
                    icon: Icon(Icons.remove),
                    label: Text("Retirer"),
                    onPressed: _removeLastTeam,
                  ),
              ],
            ),
            SizedBox(height: 10),
            Expanded(
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children:
                      teams.entries.map((entry) {
                        int teamIndex = entry.key;
                        List<String> teamPlayers = entry.value;
                        return _buildTeamColumn(
                          "Équipe ${teamIndex + 1}",
                          teamPlayers,
                          teamIndex,
                          teamColors[teamIndex % teamColors.length],
                        );
                      }).toList(),
                ),
              ),
            ),
            Divider(),
            Text("Joueurs non assignés (${unassignedPlayers.length})"),
            Expanded(
              flex: 0, // Taille minimale pour le Wrap
              child: SingleChildScrollView(
                child: Wrap(
                  spacing: 6,
                  children:
                      unassignedPlayers
                          .map(
                            (pId) => ActionChip(
                              label: Text(
                                widget.players[pId]?['name'] ?? '...',
                              ),
                              onPressed: () {
                                var smallestTeam = teams.entries.reduce(
                                  (a, b) =>
                                      a.value.length < b.value.length ? a : b,
                                );
                                _assignPlayer(pId, smallestTeam.key);
                              },
                            ),
                          )
                          .toList(),
                ),
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text("Annuler"),
        ),
        ElevatedButton(
          onPressed:
              canConfirm
                  ? () {
                    _firebaseService.updateTeams(widget.gameCode, teams);
                    Navigator.of(context).pop();
                  }
                  : null,
          child: Text("Confirmer les équipes"),
        ),
      ],
    );
  }

  Widget _buildTeamColumn(
    String title,
    List<String> team,
    int teamIndex,
    Color color,
  ) {
    return Container(
      width: 200, // Largeur fixe pour chaque colonne
      margin: EdgeInsets.all(4),
      decoration: BoxDecoration(
        border: Border.all(color: color.withOpacity(0.5)),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              title,
              style: TextStyle(color: color, fontWeight: FontWeight.bold),
            ),
          ),
          Expanded(
            child: ListView(
              children:
                  team
                      .map(
                        (pId) => ListTile(
                          title: Text(
                            widget.players[pId]?['name'] ?? '...',
                            overflow: TextOverflow.ellipsis,
                          ),
                          trailing: IconButton(
                            icon: Icon(Icons.undo, size: 18),
                            onPressed: () => _unassignPlayer(pId, teamIndex),
                          ),
                        ),
                      )
                      .toList(),
            ),
          ),
        ],
      ),
    );
  }
}

class FirebaseService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  // ─── DeepInfra AI helper (premium soft mode) ───────────────────────────────
  static const String _deepInfraApiKey = 'HA2RvSG1u7aE7u78yXd1UqnBuMY6VV70';
  static const String _deepInfraApiUrl =
      'https://api.deepinfra.com/v1/openai/chat/completions';

  /// Calls the AI API to generate a list of thematic words.
  /// [instructions]: theme instructions like "funny words", "city theme", etc.
  /// [count]: number of words to generate.
  /// [gameType]: for context-aware prompts.
  static Future<List<String>> generateAiWords({
    required String instructions,
    int count = 20,
    String gameType = '',
  }) async {
    final prompt =
        'Génère exactement $count mots ou courtes expressions en français '
        '(pas de phrases longues, juste le mot ou l\'expression) adaptés pour un jeu de type "$gameType". '
        'Thème ou instructions : "$instructions". '
        'Réponds UNIQUEMENT avec une liste JSON d\'exactement $count chaînes, sans explication, '
        'sans numérotation, au format : ["mot1","mot2",...]. '
        'Les mots doivent être variés, amusants, et correspondre aux instructions.';

    try {
      final response = await http.post(
        Uri.parse(_deepInfraApiUrl),
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer $_deepInfraApiKey',
        },
        body: jsonEncode({
          'model': 'mistralai/Mistral-Nemo-Instruct-2407',
          'messages': [
            {'role': 'user', 'content': prompt},
          ],
          'max_tokens': 400,
        }),
      );

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body) as Map<String, dynamic>;
        final content =
            data['choices']?[0]?['message']?['content'] as String? ?? '';
        // Extract JSON array from response
        final match = RegExp(r'\[.*\]', dotAll: true).firstMatch(content);
        if (match != null) {
          final jsonStr = match.group(0)!;
          final List<dynamic> parsed = jsonDecode(jsonStr);
          return parsed
              .map((e) => e.toString().trim())
              .where((s) => s.isNotEmpty)
              .take(count)
              .toList();
        }
      }
    } catch (e) {
      print('AI word generation error: $e');
    }
    return []; // Return empty on failure; caller uses default words
  }

  /// Validates a Just One clue word via AI (checks if it's a single word and relevant).
  static Future<bool> validateJustOneClueAi({
    required String clue,
    required String targetWord,
  }) async {
    final prompt =
        'Dans le jeu "Just One", est-ce que l\'indice "$clue" est valide '
        'pour faire deviner le mot "$targetWord" ? '
        'Un indice valide est : un seul mot, pas le même mot que la cible, '
        'pas une variante du même mot, pas un chiffre, pertinent et utile. '
        'Réponds UNIQUEMENT par "OUI" ou "NON".';

    try {
      final response = await http.post(
        Uri.parse(_deepInfraApiUrl),
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer $_deepInfraApiKey',
        },
        body: jsonEncode({
          'model': 'mistralai/Mistral-Nemo-Instruct-2407',
          'messages': [
            {'role': 'user', 'content': prompt},
          ],
          'max_tokens': 10,
        }),
      );
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body) as Map<String, dynamic>;
        final content =
            (data['choices']?[0]?['message']?['content'] as String? ?? '')
                .toUpperCase();
        return content.contains('OUI');
      }
    } catch (e) {
      print('AI clue validation error: $e');
    }
    return true; // Fail open: if AI unavailable, allow the clue
  }

  // DANS class FirebaseService
  Future<void> submitRestartVote(String gameCode, String playerId) async {
    await _db.collection('games').doc(gameCode).update({
      'restartVotes.$playerId': true,
    });

    // Vérifier si tout le monde a voté
    DocumentSnapshot snap = await _db.collection('games').doc(gameCode).get();
    Map<String, dynamic> data = snap.data() as Map<String, dynamic>;
    Map<String, dynamic> players = data['players'];
    Map<String, dynamic> votes = data['restartVotes'] ?? {};

    if (votes.length == players.length) {
      // Tout le monde est prêt, on relance immédiatement
      await startGame(gameCode);
    }
  }

  // 2. Gérer la fin du temps de décision (ex: 15 secondes après la fin)
  // Cette fonction est appelée par le client (l'hôte ou n'importe qui restant)
  Future<void> handleRestartDecisionTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      DocumentReference gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot snap = await transaction.get(gameRef);
      if (!snap.exists) return;
      Map<String, dynamic> data = snap.data() as Map<String, dynamic>;

      // Si le jeu a déjà redémarré, on ne fait rien
      if (data['gameState'] == 'playing') return;

      Map<String, dynamic> players = Map.from(data['players']);
      Map<String, dynamic> votes = Map.from(data['restartVotes'] ?? {});
      List<String> playersToRemove = [];

      // Identifier ceux qui n'ont pas voté "Rejouer"
      players.keys.forEach((pid) {
        if (!votes.containsKey(pid)) {
          playersToRemove.add(pid);
        }
      });

      // Supprimer les inactifs
      for (String pid in playersToRemove) {
        players.remove(pid);
      }

      // Si plus personne, supprimer la partie (ou laisser tel quel pour cleanup auto)
      if (players.isEmpty) {
        transaction.update(gameRef, {'gameState': 'abandoned'});
        return;
      }

      // Mettre la partie en mode "refilling" pour le matchmaking
      transaction.update(gameRef, {
        'players': players,
        'gameState':
            'refilling', // État spécial pour le matchmaking prioritaire
        'restartVotes': {},
        'refillStartTime':
            FieldValue.serverTimestamp(), // Pour le chrono de 10s
        'gameLog': FieldValue.arrayUnion(["Recherche de nouveaux joueurs..."]),
      });

      // Gestion de l'hôte si celui-ci est parti
      String currentHost = data['hostId'];
      if (playersToRemove.contains(currentHost)) {
        // On assignera un nouvel hôte plus tard ou on laisse le premier de la liste
        String newHost = players.keys.first;
        transaction.update(gameRef, {'hostId': newHost});
      }
    });
  }

  // 3. Logique pour rejoindre une partie en cours de "refilling" (Remplacement)
  Future<bool> joinRefillingGame(
    String gameCode,
    String playerName,
    String playerId,
  ) async {
    return _db.runTransaction((transaction) async {
      DocumentReference gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot snap = await transaction.get(gameRef);

      if (!snap.exists || snap['gameState'] != 'refilling') return false;

      Map<String, dynamic> players = Map.from(snap['players']);
      int targetCount =
          snap['playerCount'] ?? 0; // Le nombre de joueurs visé à la création

      if (players.length >= targetCount) return false; // Déjà plein

      // Ajouter le joueur
      players[playerId] = {'name': playerName, 'score': 0};

      Map<String, dynamic> updates = {
        'players': players,
        'gameLog': FieldValue.arrayUnion(["$playerName a rejoint la partie !"]),
      };

      // Si l'ancien hôte n'est plus là, le nouveau prend le relais (selon ta règle)
      // Note : on a déjà géré le transfert basique dans handleRestartDecisionTimeout,
      // mais si on veut que le NOUVEAU soit hôte :
      // updates['hostId'] = playerId; // Décommenter si tu veux STRICTEMENT que le nouveau soit l'hôte

      transaction.update(gameRef, updates);
      return true;
    });
  }

  // 4. Forcer le démarrage après les 10s de recherche
  Future<void> forceStartAfterRefill(String gameCode) async {
    DocumentReference gameRef = _db.collection('games').doc(gameCode);
    DocumentSnapshot snap = await gameRef.get();
    if (snap.exists && snap['gameState'] == 'refilling') {
      // Choisir un hôte aléatoire
      Map<String, dynamic> players = snap['players'];
      List<String> ids = players.keys.toList();
      String randomHost = ids[new Random().nextInt(ids.length)];

      await gameRef.update({'hostId': randomHost});
      await startGame(gameCode);
    }
  }

  Future<void> handleJustOneTimeout(String gameCode) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;
      var gameData = gameSnap.data() as Map<String, dynamic>;

      String roundState = gameData['roundState'] ?? '';

      // CAS 1 : Le devineur n'a pas choisi de carte à temps
      if (roundState == 'guesser_chooses_word') {
        final List<String> words = List<String>.from(
          gameData['justOneWords'] ?? [],
        );
        if (words.isNotEmpty) {
          final String randomWord = words[Random().nextInt(words.length)];

          // On force le choix d'un mot aléatoire
          transaction.update(gameRef, {
            'justOneCurrentWord': randomWord,
            'roundState': 'clue_giving',
            'justOneClues': {},
            'justOneFilteredClues': [],
            'justOneGuesserAnswer': null,
            'justOneRevealIndex': 0,
            'turnStartTime':
                FieldValue.serverTimestamp(), // Lance le timer pour les indices
            'gameLog': FieldValue.arrayUnion([
              "Le devineur a été trop lent, un mot a été choisi au hasard.",
            ]),
          });
        }
      }
      // CAS 2 : La phase d'écriture des indices est terminée
      else if (roundState == 'clue_giving') {
        Map<String, dynamic> players = gameData['players'];
        Map<String, dynamic> clues = Map.from(gameData['justOneClues'] ?? {});
        String guesserId = gameData['justOneGuesserId'];

        bool updatesNeeded = false;

        // Pour tous les joueurs (sauf le devineur) qui n'ont pas écrit d'indice
        players.keys.forEach((pId) {
          if (pId != guesserId && !clues.containsKey(pId)) {
            // On met un indice invalide par défaut pour débloquer le jeu
            clues[pId] = "INACTIF_TIMEOUT_$pId";
            updatesNeeded = true;
          }
        });

        if (updatesNeeded || clues.length == players.length - 1) {
          // On sauvegarde les indices forcés et on déclenche le filtrage via une autre fonction ou directement ici
          // Pour simplifier, on update et on laisse le filtrage se faire
          transaction.update(gameRef, {'justOneClues': clues});

          // NOTE: Il faut appeler _filterJustOneClues juste après la transaction,
          // mais on ne peut pas awaiter une fonction non-transactionnelle ici facilement.
          // L'astuce est de faire l'update ici, et le `submitJustOneClue` classique ou un listener s'en occuperait.
          // MAIS pour garantir le passage, on va forcer le passage à l'étape suivante manuellement ici :

          Map<String, String> rawClues = Map<String, String>.from(clues);
          String currentWord =
              (gameData['justOneCurrentWord'] as String).toLowerCase();
          bool allowInvalidClues =
              gameData['justOneAllowInvalidClues'] ?? false;

          // Logique de filtrage simplifiée inline pour la transaction
          Map<String, int> clueCounts = {};
          for (var clue in rawClues.values)
            clueCounts[clue] = (clueCounts[clue] ?? 0) + 1;

          List<String> filteredClues = [];
          rawClues.values.forEach((clue) {
            if (clue.startsWith("INACTIF_TIMEOUT_"))
              return; // On ignore les indices inactifs

            bool isValid = true;
            if (!allowInvalidClues) {
              if (clueCounts[clue]! > 1) isValid = false;
              if (clue.contains(currentWord) || currentWord.contains(clue))
                isValid = false;
            }
            if (isValid) filteredClues.add(clue);
          });

          transaction.update(gameRef, {
            'justOneFilteredClues': filteredClues,
            'roundState': 'reveal_clues',
            'turnStartTime':
                FieldValue.serverTimestamp(), // Lance le timer pour la réponse du devineur
            'gameLog': FieldValue.arrayUnion([
              "Temps écoulé pour les indices !",
            ]),
          });
        }
      }
      // CAS 3 : Le devineur n'a pas répondu à temps
      else if (roundState == 'reveal_clues') {
        transaction.update(gameRef, {
          'justOneGuesserAnswer': "(Temps écoulé)",
          'roundState': 'result',
          'gameEndReason': 'Temps écoulé !',
          'turnStartTime': FieldValue.serverTimestamp(),
        });
      }
    });
  }

