  Future<void> submitGribouillisStep(
    String gameCode,
    String playerId,
    String type,
    String content,
  ) async {
    await _db.runTransaction((transaction) async {
      final gameRef = _db.collection('games').doc(gameCode);
      DocumentSnapshot gameSnap = await transaction.get(gameRef);
      if (!gameSnap.exists) return;

      var gameData = gameSnap.data() as Map<String, dynamic>;
      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'],
      );
      final Map<String, dynamic> players = Map.from(gameData['players']);
      final int playerCount = players.length;
      final Map<String, dynamic> albums = Map.from(gameData['albums']);
      final String gribouillisMode = gameData['gribouillisMode'] ?? 'Normal';
      final bool ajouter1 =
          gameData['gribouillisSettings']?['ajouter1'] ?? false;
      final int currentStep = gameData['currentStep'];
      final String myName = players[playerId]?['name'] ?? 'Inconnu';

      final newStep = {
        'type': type,
        'content': content,
        'authorId': playerId,
        'authorName': myName,
      };

      if (currentStep == 0) {
        // Guard: empêcher double soumission
        List<String> existingSubmitted = List<String>.from(
          gameData['submittedPlayers'] ?? [],
        );
        if (existingSubmitted.contains(playerId)) return;

        List<dynamic> albumSteps = List.from(albums[playerId] ?? []);
        albumSteps.add(newStep);
        albums[playerId] = albumSteps;

        List<String> submittedPlayers = List<String>.from(existingSubmitted)
          ..add(playerId);

        Map<String, dynamic> updates = {
          'albums': albums,
          'submittedPlayers': submittedPlayers,
        };

        if (submittedPlayers.length == playerCount) {
          updates['currentStep'] = 1;
          updates['submittedPlayers'] = [];
          updates['roundState'] = 'drawing';
          updates['turnStartTime'] = FieldValue.serverTimestamp();
        }
        transaction.update(gameRef, updates);
        return;
      }

      final int myIndex = playerOrder.indexOf(playerId);
      if (myIndex == -1) return;

      String albumToUpdateOwnerId;
      if (gribouillisMode == 'Brise-Glace' ||
          (gribouillisMode == 'Complément' && ajouter1)) {
        final int albumOwnerIndex = (myIndex + currentStep) % playerCount;
        albumToUpdateOwnerId = playerOrder[albumOwnerIndex];
      } else {
        final int albumOwnerIndex =
            (myIndex - currentStep + (playerCount * currentStep)) % playerCount;
        albumToUpdateOwnerId = playerOrder[albumOwnerIndex];
      }

      List<dynamic> albumSteps = List.from(albums[albumToUpdateOwnerId] ?? []);
      albumSteps.add(newStep);
      albums[albumToUpdateOwnerId] = albumSteps;

      // Guard: empêcher double soumission
      List<String> existingSubmitted2 = List<String>.from(
        gameData['submittedPlayers'] ?? [],
      );
      if (existingSubmitted2.contains(playerId)) return;

      List<String> submittedPlayers = List<String>.from(existingSubmitted2)
        ..add(playerId);

      Map<String, dynamic> updates = {
        'albums': albums,
        'submittedPlayers': submittedPlayers,
      };

      if (submittedPlayers.length == playerCount) {
        final int nextStep = currentStep + 1;
        updates['currentStep'] = nextStep;
        updates['submittedPlayers'] = [];
        updates['turnStartTime'] = FieldValue.serverTimestamp();

        final int totalSteps = playerCount;

        if (nextStep >= totalSteps) {
          updates['roundState'] = 'results';
        } else {
          if (gribouillisMode == 'Normal') {
            updates['roundState'] =
                (nextStep % 2 != 0) ? 'drawing' : 'guessing';
          } else {
            // Complément et Brise-Glace n'ont que du dessin après l'étape 0.
            updates['roundState'] = 'drawing';
          }
        }
      }
      transaction.update(gameRef, updates);
    });
  }

