      Map<String, dynamic> updates = {'storyTruths': storyTruths};

      if (storyTruths.length == players.length) {
        String voteMode = gameData['liarVoteMode'];
        updates['roundState'] =
            (voteMode == 'turn_by_turn') ? 'reveal_and_vote' : 'voting';
