  Future<void> _startPokerHand(
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
  ) async {
    final players = Map<String, dynamic>.from(gameData['players']);
    final playerIds =
        players.keys.toList(); // Ne pas mélanger pour garder l'ordre des blinds

    Map<String, dynamic> playerData = Map.from(gameData['playerData'] ?? {});
    bool isFirstHand = playerData.isEmpty;
    if (isFirstHand) {
      int startChips = gameData['startChips'] ?? 1000;
      for (String pId in playerIds) {
        playerData[pId] = {
          'name': players[pId]['name'],
          'chips': startChips,
          'hand': [],
          'currentBet': 0,
          'status': 'active', // 'active', 'folded', 'all-in'
        };
      }
    } else {
      playerData.forEach((pId, data) {
        playerData[pId]['hand'] = [];
        playerData[pId]['currentBet'] = 0;
        playerData[pId]['status'] = (data['chips'] ?? 0) > 0 ? 'active' : 'out';
      });
    }

    List<String> suits = ['H', 'D', 'C', 'S']; // Coeur, Carreau, Trèfle, Pique
    List<String> ranks = [
      '2',
      '3',
      '4',
      '5',
      '6',
      '7',
      '8',
      '9',
      'T',
      'J',
      'Q',
      'K',
      'A',
    ];
    List<String> deck = [
      for (var suit in suits)
        for (var rank in ranks) '$rank$suit',
    ]..shuffle();

    playerData.forEach((pId, data) {
      if (data['status'] == 'active') {
        playerData[pId]['hand'] = [deck.removeAt(0), deck.removeAt(0)];
      }
    });

    // Helper to find next non-out player index
    int nextActivePokerIndex(int fromIndex) {
      int idx = (fromIndex + 1) % playerIds.length;
      int safety = 0;
      while (playerData[playerIds[idx]]?['status'] == 'out' &&
          safety < playerIds.length) {
        idx = (idx + 1) % playerIds.length;
        safety++;
      }
      return idx;
    }

    int dealerIndex = nextActivePokerIndex(
      (gameData['dealerIndex'] as int?) ?? -1,
    );
    int smallBlindIndex = nextActivePokerIndex(dealerIndex);
    int bigBlindIndex = nextActivePokerIndex(smallBlindIndex);
    int firstToActIndex = nextActivePokerIndex(bigBlindIndex);

    String smallBlindId = playerIds[smallBlindIndex];
    String bigBlindId = playerIds[bigBlindIndex];

    int smallBlindAmount = gameData['smallBlind'] ?? 10;
    int bigBlindAmount = gameData['bigBlind'] ?? 20;

    int smallBlindActual =
        (playerData[smallBlindId]['chips'] as int) < smallBlindAmount
            ? (playerData[smallBlindId]['chips'] as int)
            : smallBlindAmount;
    int bigBlindActual =
        (playerData[bigBlindId]['chips'] as int) < bigBlindAmount
            ? (playerData[bigBlindId]['chips'] as int)
            : bigBlindAmount;

    playerData[smallBlindId]['chips'] -= smallBlindActual;
    playerData[smallBlindId]['currentBet'] = smallBlindActual;
    playerData[bigBlindId]['chips'] -= bigBlindActual;
    playerData[bigBlindId]['currentBet'] = bigBlindActual;
    int pot = smallBlindActual + bigBlindActual;

    await gameRef.update({
      'gameState': 'playing',
      'phase': 'pre-flop',
      'playerData': playerData,
      'deck': deck,
      'communityCards': [],
      'pot': pot,
      'dealerIndex': dealerIndex,
      'currentPlayerIndex': firstToActIndex,
      'playerOrder': playerIds, // Important pour l'ordre de jeu
      'currentBet': bigBlindActual,
      'lastRaiserId': bigBlindId,
      'smallBlindIndex': smallBlindIndex,
      'bigBlindIndex': bigBlindIndex,
      'handLog': [
        "Nouvelle main ! ${players[playerIds[dealerIndex]]['name']} est le donneur.",
        "${players[smallBlindId]['name']} pose la petite blind de $smallBlindActual.",
        "${players[bigBlindId]['name']} pose la grosse blind de $bigBlindActual.",
      ],
      'turnStartTime': FieldValue.serverTimestamp(),
    });
  }

  Future<void> pokerAction(
    String gameCode,
    String playerId,
    String action, {
    int? amount,
  }) async {
    print("--- [Poker Action Début] ---");
    print("Joueur: $playerId, Action: $action, Montant: $amount");

    try {
      await _db.runTransaction((transaction) async {
        print("[Transaction] Début de la transaction...");
        final gameRef = _db.collection('games').doc(gameCode);
        DocumentSnapshot gameSnap = await transaction.get(gameRef);

        if (!gameSnap.exists) {
          throw Exception("La partie n'existe pas.");
        }

        var gameData = gameSnap.data() as Map<String, dynamic>;
        print("[Transaction] Données du jeu récupérées.");

        List<String> playerOrder = List<String>.from(
          gameData['playerOrder'] ?? [],
        );
        final int currentPlayerIndex =
            (gameData['currentPlayerIndex'] as num? ?? 0).toInt();

        if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length) {
          throw Exception(
            "Données de jeu invalides (playerOrder/currentPlayerIndex).",
          );
        }
        if (playerOrder[currentPlayerIndex] != playerId) {
          throw Exception("Ce n'est pas le tour de $playerId.");
        }

        var playerData = Map<String, dynamic>.from(
          json.decode(json.encode(gameData['playerData'] ?? {})),
        );
        var myData = playerData[playerId];

        if (myData == null) {
          throw Exception("Données du joueur $playerId introuvables.");
        }

        int currentBet = (gameData['currentBet'] as num? ?? 0).toInt();
        int pot = (gameData['pot'] as num? ?? 0).toInt();
        List<String> handLog = List<String>.from(gameData['handLog'] ?? []);
        String? lastRaiserId = gameData['lastRaiserId'];

        Map<String, dynamic> allUpdates = {};

        switch (action) {
          case 'fold':
            myData['status'] = 'folded';
            handLog.add("${myData['name']} se couche.");
            break;
          case 'check':
            if ((myData['currentBet'] as num).toInt() < currentBet) {
              throw Exception("Vous ne pouvez pas checker, quelqu'un a misé.");
            }
            handLog.add("${myData['name']} check.");
            break;
          case 'call':
            int callAmount = currentBet - (myData['currentBet'] as num).toInt();
            if (callAmount >= (myData['chips'] as num).toInt()) {
              callAmount = (myData['chips'] as num).toInt();
              myData['status'] = 'all-in';
              handLog.add("${myData['name']} fait tapis (all-in) !");
            } else {
              handLog.add("${myData['name']} suit pour $callAmount.");
            }
            myData['chips'] -= callAmount;
            myData['currentBet'] += callAmount;
            pot += callAmount;
            break;
          case 'raise':
            int totalBetAmount = amount!;
            if (totalBetAmount <= currentBet)
              throw Exception(
                "La relance doit être supérieure à la mise actuelle.",
              );
            if (totalBetAmount >
                (myData['chips'] as num).toInt() +
                    (myData['currentBet'] as num).toInt())
              throw Exception("Vous n'avez pas assez de jetons.");

            int raiseAmount =
                totalBetAmount - (myData['currentBet'] as num).toInt();
            myData['chips'] -= raiseAmount;
            myData['currentBet'] = totalBetAmount;
            pot += raiseAmount;
            currentBet = totalBetAmount;
            lastRaiserId = playerId;

            if ((myData['chips'] as num).toInt() == 0) {
              myData['status'] = 'all-in';
              handLog.add(
                "${myData['name']} fait tapis (all-in) en relançant à $totalBetAmount !",
              );
            } else {
              handLog.add("${myData['name']} relance à $totalBetAmount.");
            }
            break;
        }
        playerData[playerId] = myData;

        var updatedGameData = Map<String, dynamic>.from(gameData);
        updatedGameData['playerData'] = playerData;
        updatedGameData['pot'] = pot;
        updatedGameData['currentBet'] = currentBet;
        updatedGameData['lastRaiserId'] = lastRaiserId;
        updatedGameData['handLog'] = handLog;

        final turnUpdates = _advancePokerTurn(updatedGameData);

        allUpdates.addAll({
          'playerData': playerData,
          'pot': pot,
          'currentBet': currentBet,
          'lastRaiserId': lastRaiserId,
          'handLog': handLog,
          'turnStartTime': FieldValue.serverTimestamp(),
        });
        allUpdates.addAll(turnUpdates);

        print(
          "[Transaction] Écriture finale avec toutes les modifications : $allUpdates",
        );
        transaction.update(gameRef, allUpdates);
      });
      print("--- [Poker Action Fin avec Succès] ---");
    } catch (e) {
      print("--- [Poker Action Fin avec Erreur] ---");
      print("Erreur capturée: $e");

      rethrow;
    }
  }

  Map<String, dynamic> _advancePokerTurn(Map<String, dynamic> gameData) {
    List<String> playerOrder = List<String>.from(gameData['playerOrder'] ?? []);
    var playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    int currentIndex = (gameData['currentPlayerIndex'] as num? ?? 0).toInt();
    String? lastRaiserId = gameData['lastRaiserId'];

    if (playerOrder.isEmpty || playerData.isEmpty) return {};

    List<String> activePlayers =
        playerOrder
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();
    if (activePlayers.length <= 1) {
      return _determinePokerWinner(gameData);
    }

    int nextIndex = currentIndex;
    int safetyCounter = 0;
    do {
      nextIndex = (nextIndex + 1) % playerOrder.length;
      safetyCounter++;
    } while ((playerData[playerOrder[nextIndex]]?['status'] == 'folded' ||
            playerData[playerOrder[nextIndex]]?['status'] == 'all-in') &&
        safetyCounter <= playerOrder.length);

    if (safetyCounter > playerOrder.length) {
      var updatedData = Map<String, dynamic>.from(gameData);
      Map<String, dynamic> allUpdates = {};
      while (updatedData['phase'] != 'river') {
        final phaseUpdates = _startNextPokerPhase(updatedData);
        allUpdates.addAll(phaseUpdates);
        updatedData.addAll(phaseUpdates);
      }
      allUpdates.addAll(_determinePokerWinner(updatedData));
      return allUpdates;
    }

    String nextPlayerId = playerOrder[nextIndex];

    if (nextPlayerId == lastRaiserId ||
        (lastRaiserId == null &&
            nextIndex == (gameData['bigBlindIndex'] ?? 0))) {
      Map<String, dynamic> currentData = Map.from(gameData);
      final phaseUpdates = _startNextPokerPhase(currentData);
      currentData.addAll(phaseUpdates);

      if (currentData['phase'] == 'showdown') {
        phaseUpdates.addAll(_determinePokerWinner(currentData));
      }
      return phaseUpdates;
    } else {
      return {'currentPlayerIndex': nextIndex};
    }
  }

  Map<String, dynamic> _startNextPokerPhase(Map<String, dynamic> gameData) {
    String currentPhase = gameData['phase'];
    String nextPhase = '';
    List<dynamic> communityCards = List.from(gameData['communityCards'] ?? []);
    List<dynamic> deck = List.from(gameData['deck'] ?? []);
    List<String> log = List.from(gameData['handLog'] ?? []);

    Map<String, dynamic> updates = {};

    switch (currentPhase) {
      case 'pre-flop':
        nextPhase = 'flop';
        if (deck.length >= 3)
          communityCards.addAll([
            deck.removeAt(0),
            deck.removeAt(0),
            deck.removeAt(0),
          ]);
        log.add("--- FLOP ---");
        break;
      case 'flop':
        nextPhase = 'turn';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add("--- TURN ---");
        break;
      case 'turn':
        nextPhase = 'river';
        if (deck.isNotEmpty) communityCards.add(deck.removeAt(0));
        log.add("--- RIVER ---");
        break;
      case 'river':
        nextPhase = 'showdown';
        log.add("--- ABATTAGE (SHOWDOWN) ---");
        break;
      default:
        return {}; // Ne rien faire si la phase est inconnue
    }

    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    List<String> playerOrder = List.from(gameData['playerOrder'] ?? []);
    int dealerIndex = (gameData['dealerIndex'] as num? ?? -1).toInt();

    playerData.forEach((pId, data) {
      if (data['status'] != 'folded') {
        data['currentBet'] = 0;
      }
    });

    int firstToActIndex = (dealerIndex + 1) % playerOrder.length;
    int count = 0;
    while (playerData[playerOrder[firstToActIndex]]?['status'] != 'active') {
      firstToActIndex = (firstToActIndex + 1) % playerOrder.length;
      count++;
      if (count > playerOrder.length) break;
    }

    updates.addAll({
      'phase': nextPhase,
      'communityCards': communityCards,
      'deck': deck,
      'handLog': log,
      'playerData': playerData,
      'currentBet': 0,
      'currentPlayerIndex': firstToActIndex,
      'lastRaiserId': playerOrder[firstToActIndex],
    });

    return updates;
  }

  Map<String, dynamic> _determinePokerWinner(Map<String, dynamic> gameData) {
    var playerData = Map<String, dynamic>.from(
      json.decode(json.encode(gameData['playerData'])),
    );
    final communityCards =
        (gameData['communityCards'] as List<dynamic>? ?? [])
            .cast<String>()
            .toList();
    List<String> playersInHand =
        playerData.keys
            .where((pId) => playerData[pId]?['status'] != 'folded')
            .toList();

    String winnerAnnouncement = "";
    List<String> winners = [];

    if (playersInHand.length == 1) {
      winners.add(playersInHand.first);
      winnerAnnouncement =
          "${playerData[winners.first]['name']} gagne le pot par forfait !";
    } else {
      Map<String, PokerHand> playerFinalHands = {};
      for (String pId in playersInHand) {
        final playerHand =
            (playerData[pId]['hand'] as List<dynamic>? ?? [])
                .cast<String>()
                .toList();
        final sevenCards = [...playerHand, ...communityCards];
        playerFinalHands[pId] = PokerHandEvaluator.evaluateHand(sevenCards);
      }

      PokerHand? bestHand;
      playerFinalHands.forEach((pId, hand) {
        if (bestHand == null || hand.compareTo(bestHand!) > 0) {
          bestHand = hand;
          winners = [pId];
        } else if (hand.compareTo(bestHand!) == 0) {
          winners.add(pId);
        }
      });

      final winnerNames = winners
          .map((id) => playerData[id]?['name'] ?? 'Inconnu')
          .join(' et ');
      winnerAnnouncement =
          "$winnerNames gagne(nt) le pot avec ${bestHand?.rank.name ?? 'une main'} !";
    }

    if (winners.isNotEmpty) {
      int pot = (gameData['pot'] as num? ?? 0).toInt();
      int potPerWinner = (pot / winners.length).floor();

      for (String winId in winners) {
        playerData[winId]['chips'] += potPerWinner;
      }
    }

    List<String> handLog = List.from(gameData['handLog'] ?? []);
    handLog.add(winnerAnnouncement);

    return {
      'phase': 'hand_over',
      'playerData': playerData,
      'handLog': handLog,
      'showdownHands': {
        for (var pId in playersInHand) pId: playerData[pId]['hand'],
      },
      'turnStartTime': FieldValue.serverTimestamp(),
    };
  }
}

void showGameRules(BuildContext context, String gameType) {
  showDialog(
    context: context,
    builder: (BuildContext context) {
      String gameTitle = gameType;
      String rules =
          GameData.gameRules[gameType] ?? "Aucune règle trouvée pour ce jeu.";
      if (gameType == 'Undercover Local') {
        gameTitle = 'Infiltré & Mr. White';
        rules = GameData.gameRules['Infiltré & Mr. White']!;
      }

      return AlertDialog(
        title: Text("Règles : $gameTitle"),
        content: SingleChildScrollView(child: Text(rules)),
        actions: <Widget>[
          TextButton(
            child: Text("Compris !"),
            onPressed: () {
              Navigator.of(context).pop();
            },
          ),
        ],
      );
    },
  );
}

