                        segments: const [
                          ButtonSegment(
                            value: 'pays',
                            label: Text('Mon Pays'),
                            icon: Icon(Icons.flag),
                          ),
                          ButtonSegment(
                            value: 'monde',
                            label: Text('Le Monde'),
                            icon: Icon(Icons.public),
                          ),
                        ],
                        selected: {_scope},
                        onSelectionChanged:
                            (newSelection) =>
                                setState(() => _scope = newSelection.first),
                      ),
                      SizedBox(height: 20),
                      Text(
                        'Nombre de joueurs : ${_playerCount.toInt()}',
                        style: Theme.of(context).textTheme.titleLarge,
                      ),
                      Slider(
                        value: _playerCount,
                        min: 2,
                        max: 20,
                        divisions: 18,
                        label: _playerCount.toInt().toString(),
                        onChanged:
                            (value) => setState(() => _playerCount = value),
                      ),
                      Divider(height: 30, thickness: 1, color: Colors.white24),
                      Text(
                        'Préférence Vidéo (Recherche) :',
                        style: Theme.of(context).textTheme.titleMedium,
                      ),
                      SizedBox(height: 10),
                      SegmentedButton<String>(
                        segments: const [
                          ButtonSegment(
                            value: 'any',
                            label: Text('Peu importe'),
                            icon: Icon(Icons.shuffle),
                          ),
                          ButtonSegment(
                            value: 'with',
                            label: Text('Avec'),
                            icon: Icon(Icons.videocam),
                          ),
                          ButtonSegment(
                            value: 'without',
                            label: Text('Sans'),
                            icon: Icon(Icons.videocam_off),
                          ),
                        ],
                        selected: {_videoPreference},
                        onSelectionChanged:
                            (newSelection) => setState(
                              () => _videoPreference = newSelection.first,
                            ),
                      ),
                      SizedBox(height: 10),
                    ],

                    Consumer<PlayerState>(
                      builder: (context, playerState, _) {
                        bool canEnableVideo =
                            playerState.isPremium ||
                            playerState.videoGamesLeftToday > 0;
                        return SwitchListTile.adaptive(
                          title: Text("Activer la Vidéo"),
                          subtitle: Text(
                            playerState.isPremium
                                ? "Communication audio et vidéo pour tous"
                                : (canEnableVideo
                                    ? "Il vous reste ${playerState.videoGamesLeftToday} partie(s) vidéo gratuite(s) aujourd'hui"
                                    : "Réservé aux membres Premium (limite gratuite atteinte)"),
                          ),
                          value: _videoEnabled,
                          onChanged:
                              canEnableVideo
                                  ? (val) => setState(() => _videoEnabled = val)
                                  : null,
                          secondary: Icon(
                            canEnableVideo ? Icons.videocam : Icons.lock,
                          ),
                          contentPadding: EdgeInsets.zero,
                        );
                      },
                    ),
                    Divider(height: 30, thickness: 1, color: Colors.white24),

                    AbsorbPointer(
