class JoinGameScreen extends StatefulWidget {
  final String playerName;
  final String playerId; // <--- AJOUTER

  JoinGameScreen({
    required this.playerName,
    required this.playerId, // <--- AJOUTER
  });

  @override
  _JoinGameScreenState createState() => _JoinGameScreenState();
}

class _JoinGameScreenState extends State<JoinGameScreen> {
  final FirebaseService _firebaseService = FirebaseService();
  final FirebaseFirestore _db =
      FirebaseFirestore.instance; // Ajouter une instance de Firestore

  final _codeController = TextEditingController();
  bool _isLoading = false;

  void _joinGame() async {
    if (_codeController.text.trim().length != 6) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Le code doit comporter 6 chiffres.")),
      );
      return;
    }
    setState(() => _isLoading = true);

    final playerState = Provider.of<PlayerState>(context, listen: false);

    final gameCode = _codeController.text.trim();

    if (!await playerState.canPlayMultiplayer()) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Vous avez atteint votre limite de 20 parties multijoueur pour aujourd'hui.",
          ),
        ),
      );
      if (mounted) setState(() => _isLoading = false);
      return;
    }

    try {
      DocumentSnapshot gameSnap =
          await _db.collection('games').doc(gameCode).get();
      if (!gameSnap.exists || gameSnap['gameState'] != 'lobby') {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Code de partie invalide ou partie déjà commencée."),
          ),
        );
        if (mounted) setState(() => _isLoading = false);
        return;
      }

      bool isPremiumLobby = gameSnap['isPremiumLobby'] ?? false;

      if (!isPremiumLobby) {
        bool success = await playerState.spendCoins(
          1,
        ); // Coût pour rejoindre: 1 pièce
        if (!success) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                "Pas assez de pièces pour rejoindre cette partie ! Coût : 1 pièce.",
              ),
            ),
          );
          if (mounted) setState(() => _isLoading = false);
          return;
        }
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text("Vous rejoignez une partie VIP, c'est gratuit !"),
          ),
        );
      }

      await playerState.recordMultiplayerGame();
      bool success = await _firebaseService.joinGame(
        gameCode,
        widget.playerName,
        widget.playerId,
      );

      if (success) {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder:
                (_) => GameLobbyScreen(
                  gameCode: gameCode,
                  playerId: widget.playerId,
                ),
          ),
        );
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text("Impossible de rejoindre la partie.")),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text("Erreur de connexion.")));
    } finally {
      if (mounted) {
        setState(() => _isLoading = false);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Rejoindre une Partie")),
      body:
          _isLoading
              ? Center(child: CircularProgressIndicator())
              : Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    TextField(
                      controller: _codeController,
                      decoration: InputDecoration(
                        labelText: "Code de la partie (6 chiffres)",
                      ),
                      keyboardType: TextInputType.number,
                      textAlign: TextAlign.center,
                      style: TextStyle(fontSize: 24, letterSpacing: 8),
                      inputFormatters: [
                        FilteringTextInputFormatter.digitsOnly,
                        LengthLimitingTextInputFormatter(6),
                      ],
                    ),
                    SizedBox(height: 30),
                    ElevatedButton(
                      onPressed: _joinGame,
                      child: Text("Rejoindre"),
                    ),
                  ],
                ),
              ),
    );
  }
}

class GameLobbyScreen extends StatelessWidget {
  final String gameCode;
  final String playerId; // 1. AJOUTER CE CHAMP
  final FirebaseService _firebaseService = FirebaseService();

  GameLobbyScreen({required this.gameCode, required this.playerId});

  @override
  Widget build(BuildContext context) {
    final String currentPlayerId = playerId;

    return Scaffold(
      appBar: AppBar(title: Text("Salon d'attente")),
      body: StreamBuilder<DocumentSnapshot>(
        stream: _firebaseService.getGameStream(gameCode),
        builder: (context, snapshot) {
          if (!snapshot.hasData)
            return Center(child: CircularProgressIndicator());
          if (snapshot.hasError)
            return Center(child: Text("Erreur de connexion à la partie."));
          if (!snapshot.data!.exists) {
            Future.microtask(
              () => Navigator.of(context).popUntil((route) => route.isFirst),
            );
            return Center(child: Text("La partie n'existe plus."));
          }

          var gameData = snapshot.data!.data() as Map<String, dynamic>;
          var players = (gameData['players'] as Map<String, dynamic>?) ?? {};

          print(
            "[DEBUG GameLobby] Données reçues par le Stream. Joueurs: $players",
          );

          String gameType = gameData['gameType'] ?? '';

          if (gameData['gameState'] == 'playing') {
            Future.microtask(
              () => Navigator.pushReplacement(
                context,
                MaterialPageRoute(
                  builder:
                      (_) => MultiplayerGameScreen(
                        gameCode: gameCode,
                        playerId: playerId,
                      ),
                ),
              ), // MODIFIÉ ICI
            );
            return Center(child: Text("Démarrage de la partie..."));
          }

          bool isHost = gameData['hostId'] == currentPlayerId;

          bool isTeamGame = ['Codenames', 'Time\'s Up'].contains(gameType);
          Map<int, List<String>> teams = {};
          if (gameData['teams'] != null) {
            (gameData['teams'] as Map<String, dynamic>).forEach((key, value) {
              teams[int.parse(key)] = List<String>.from(value);
            });
          }

          bool canStart = true;
          String playerRequirementMessage = "";

          if (isTeamGame) {
            final int totalAssignedPlayers = teams.values.fold(
              0,
              (sum, team) => sum + team.length,
            );
            if (players.length < 4) {
              canStart = false;
              playerRequirementMessage = "Il faut au moins 4 joueurs.";
            } else if (teams.length < 2) {
              canStart = false;
              playerRequirementMessage = "Veuillez créer au moins 2 équipes.";
            } else if (totalAssignedPlayers != players.length) {
              canStart = false;
              playerRequirementMessage =
                  "Tous les joueurs doivent être dans une équipe.";
            } else if (teams.values.any((team) => team.length < 2)) {
              canStart = false;
              playerRequirementMessage =
                  "Chaque équipe doit avoir au moins 2 joueurs.";
            }
          } else {
            switch (gameType) {
              case 'Synonyme ou Banni':
                if (players.length < 3) {
                  canStart = false;
                  playerRequirementMessage =
                      "Au moins 3 joueurs sont requis pour Synonyme ou Banni.";
                }
                break;
              case 'Gribouillis':
              case 'Poker':
              case 'Zéro Pointé':
                if (players.length < 2) {
                  canStart = false;
                  playerRequirementMessage =
                      "Au moins 2 joueurs sont requis pour ce mode.";
                }
                break;
              case 'Loup-Garou':
                Map<String, int> roleSettings = Map<String, int>.from(
                  gameData['roleSettings'] ?? {},
                );
                int totalRolesCount = roleSettings.values.fold(
                  0,
                  (sum, count) => sum + count,
                );

                if (totalRolesCount < 5) {
                  canStart = false;
                  playerRequirementMessage =
                      "Au moins 5 rôles doivent être sélectionnés par l'hôte.";
                } else if (players.length != totalRolesCount) {
                  canStart = false;
                  playerRequirementMessage =
                      "${players.length} joueurs connectés pour ${totalRolesCount} rôles. Le nombre doit correspondre.";
                }
                break;
              default:
                if (players.length < 2) {
                  canStart = false;
                  playerRequirementMessage = "Au moins 2 joueurs sont requis.";
                }
                break;
            }
          }

          return Padding(
            padding: const EdgeInsets.all(16.0),
            child: SingleChildScrollView(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(16.0),
                      child: Column(
                        children: [
                          Text(
                            "CODE DE LA PARTIE",
                            style: Theme.of(context).textTheme.bodyMedium,
                          ),
                          SizedBox(height: 8),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.center,
                            children: [
                              SelectableText(
                                gameCode,
                                style: Theme.of(context)
                                    .textTheme
                                    .headlineMedium
                                    ?.copyWith(fontSize: 40, letterSpacing: 6),
                              ),
                              IconButton(
                                icon: Icon(Icons.copy),
                                onPressed: () {
                                  Clipboard.setData(
                                    ClipboardData(text: gameCode),
                                  );
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    SnackBar(content: Text("Code copié !")),
                                  );
                                },
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                  SizedBox(height: 30),
                  if (gameType == 'Petit Bac') ...[
                    Text(
                      "Catégories choisies par l'hôte :",
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                    SizedBox(height: 10),
                    Wrap(
                      spacing: 8.0,
                      runSpacing: 4.0,
                      alignment: WrapAlignment.center,
                      children:
                          List<String>.from(
                                gameData['petitBacCategories'] ??
                                    GameData.petitBacDefaultCategories,
                              )
                              .map(
                                (category) => Chip(
                                  label: Text(category),
                                  backgroundColor: Colors.deepPurple[900],
                                ),
                              )
                              .toList(),
                    ),
                    SizedBox(height: 20),
                  ],
                  Text(
                    "Joueurs connectés (${players.length})",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  SizedBox(height: 10),
                  ListView(
                    shrinkWrap: true,
                    physics: NeverScrollableScrollPhysics(),
                    children:
                        players.entries.map((entry) {
                          var player = entry.value;
                          bool isPlayerHost = entry.key == gameData['hostId'];

                          Color? teamColor;
                          int? teamIndex;
                          for (var teamEntry in teams.entries) {
                            if (teamEntry.value.contains(entry.key)) {
                              teamIndex = teamEntry.key;
                              break;
                            }
                          }

                          if (teamIndex != null) {
                            const List<Color> teamColors = [
                              Colors.redAccent,
                              Colors.blueAccent,
                              Colors.greenAccent,
                              Colors.orangeAccent,
                              Colors.purpleAccent,
                              Colors.cyanAccent,
                            ];
                            teamColor = teamColors[teamIndex %
                                    teamColors.length]
                                .withOpacity(0.3);
                          }

                          return Card(
                            color: teamColor,
                            child: ListTile(
                              leading: Icon(
                                isPlayerHost
                                    ? Icons.verified_user
                                    : Icons.person,
                              ),
                              title: Text(
                                player['name'] ?? 'Nom inconnu',
                                style: TextStyle(fontWeight: FontWeight.bold),
                              ),
                              trailing: Text("${player['score'] ?? 0} pts"),
                            ),
                          );
                        }).toList(),
                  ),
                  SizedBox(height: 20),
                  if (isHost && isTeamGame)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 8.0),
                      child: OutlinedButton.icon(
                        icon: Icon(Icons.groups),
                        label: Text("Composer les équipes"),
                        onPressed: () {
                          showDialog(
                            context: context,
                            builder:
                                (dContext) => MultiplayerTeamSelectionDialog(
                                  gameCode: gameCode,
                                  players: players,
                                  initialTeams: teams, // C'était déjà correct
                                  gameName: gameType,
                                ),
                          );
                        },
                      ),
                    ),
                  if (isHost)
                    ElevatedButton(
                      onPressed:
                          canStart
                              ? () => _firebaseService.startGame(gameCode)
                              : null,
                      child: Text("Démarrer la partie"),
                    )
                  else
                    Text(
                      "En attente de l'hôte...",
                      style: TextStyle(
                        fontStyle: FontStyle.italic,
                        color: Colors.white70,
                      ),
                      textAlign: TextAlign.center,
                    ),
                  if (isHost && !canStart)
                    Padding(
                      padding: const EdgeInsets.only(top: 8.0),
                      child: Text(
                        playerRequirementMessage,
                        textAlign: TextAlign.center,
                        style: TextStyle(color: Colors.amber),
                      ),
                    ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

