  Future<void> _connectToAgora() async {
    if (_agoraInitialized) return;
    
    // Check if video is enabled; for now we initialize it as long as the widget requests it
    // Wait, the original code had:
    // if (gameData['videoEnabled'] == true) ...
    // Since we don't have gameData yet, let's fetch it, or just initialize.
    // The user's code:
    final bool videoEnabled = true; // ou widget.videoEnabled
    
    if (videoEnabled) {
      _agoraInitialized = true;
      try {
        await _agoraService.initialize();
        await _agoraService.joinChannel(widget.gameCode);
      } catch (e) {
        print("Erreur init Agora: $e");
      }
    }
  }

  @override
  void initState() {
    super.initState();
    _agoraService = Provider.of<AgoraService>(context, listen: false);
    
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _connectToAgora();
    });

    _gribouillisPageController = PageController();

    // Écouter les changements de AgoraService pour mettre à jour Firestore
    _agoraService.addListener(() {
      if (_agoraService.localUserJoined && _agoraService.localUid != 0) {
        FirebaseFirestore.instance
            .collection('games')
            .doc(widget.gameCode)
            .update({
              'players.${widget.playerId}.agoraUid': _agoraService.localUid,
            });
      }
    });

    _answerController.addListener(() {
      setState(() {});
    });

    // Listener pour le bouton + de Times Up (rebuild quand le texte change)
    _timesUpWordController.addListener(() {
      if (mounted) setState(() {});
    });

    WidgetsBinding.instance.addObserver(this);
    _pictionaryDrawingController.addListener(_onPictionaryDrawingChanged);
    _startHeartbeat();
    _startStalePlayerCheck();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused) {
      // L'app est en arrière-plan — si pas de retour dans 60s, retirer le joueur
      _pauseRemovalTimer?.cancel();
      _pauseRemovalTimer = Timer(const Duration(seconds: 60), () {
        _firebaseService.removePlayerFromGame(widget.gameCode, widget.playerId);
      });
    } else if (state == AppLifecycleState.resumed) {
      _pauseRemovalTimer?.cancel();
      _pauseRemovalTimer = null;
      // Mettre à jour le heartbeat immédiatement au retour
      _sendHeartbeat();
    } else if (state == AppLifecycleState.detached) {
      _firebaseService.removePlayerFromGame(widget.gameCode, widget.playerId);
    }
  }

  void _startHeartbeat() {
    _sendHeartbeat();
    _heartbeatTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      _sendHeartbeat();
    });
  }

  void _sendHeartbeat() {
    _firebaseService.updatePlayerHeartbeat(widget.gameCode, widget.playerId);
  }

  void _startStalePlayerCheck() {
    _stalePlayerCheckTimer = Timer.periodic(const Duration(seconds: 30), (
      _,
    ) async {
      // Seul l'hôte vérifie les joueurs inactifs
      final gameSnap =
          await FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .get();
      if (!gameSnap.exists) return;
      final gameData = gameSnap.data() as Map<String, dynamic>;
      if (gameData['hostId'] != widget.playerId) return;
      if (gameData['gameState'] != 'playing') return;

      final presencesSnap =
          await FirebaseFirestore.instance
              .collection('games')
              .doc(widget.gameCode)
              .collection('presences')
              .get();
      final now = DateTime.now();
      for (final doc in presencesSnap.docs) {
        if (doc.id == widget.playerId) continue;
        final lastHeartbeat =
            (doc.data()['lastHeartbeat'] as Timestamp?)?.toDate();
        if (lastHeartbeat != null &&
            now.difference(lastHeartbeat).inSeconds > 90) {
          await _firebaseService.removePlayerFromGame(widget.gameCode, doc.id);
        }
      }
    });
  }

  void _onPictionaryDrawingChanged() {
    _pictionaryDebounceTimer?.cancel();
    _pictionaryDebounceTimer = Timer(
      const Duration(milliseconds: 300),
      () async {
        if (!mounted || _pictionaryDrawingController.isEmpty) return;
        final pngBytes = await _pictionaryDrawingController.toPngBytes();
        if (pngBytes != null && mounted) {
          _firebaseService.updatePictionaryDrawing(
            widget.gameCode,
            base64Encode(pngBytes),
            _pictionaryStrokeCount,
          );
        }
      },
    );
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _heartbeatTimer?.cancel();
    _pauseRemovalTimer?.cancel();
    _stalePlayerCheckTimer?.cancel();
    _pictionaryDebounceTimer?.cancel();
    _pictionaryDrawingController.removeListener(_onPictionaryDrawingChanged);
    _timerSubscription?.cancel();
    _playerTurnTimer?.cancel();
    _postGameTimer?.cancel();
    _dobblePenaltyTimer?.cancel();
    _answerController.removeListener(() {
      setState(() {});
    });
    _answerController.dispose();
    _timesUpWordController.dispose();
    _pictionaryGuessController.dispose();
    _pictionaryDrawingController.dispose();
    _justOneClueController.dispose();
    _justOneGuessController.dispose();
    _answerControllers.values.forEach((controller) => controller.dispose());
    _chatController.dispose();
    _hotPotatoPlayer?.dispose();
    _gribouillisPageController?.dispose();
    try {
      if (_agoraInitialized) {
        _agoraService.leaveChannel();
      }
    } catch (e) {
      print("Erreur dispose AgoraService: $e");
    }
    super.dispose();
  }

