  void _startPlayerTurnTimer(Map<String, dynamic> gameData) {
    _playerTurnTimer?.cancel();

    // --- DÉBUT MODIFICATION ---
    // Vérifier si le timer est activé dans la config de la partie
    bool useTimer = gameData['useTimer'] ?? true;

    // Si le timer est désactivé, on arrête tout ici (sauf si c'est une logique critique interne)
    // Note : Certains jeux comme 'La Patate Chaude' dépendent intrinsèquement du temps,
    // vous pouvez ajouter des exceptions ici si nécessaire.
    if (!useTimer) {
      return;
    }
    // --- FIN MODIFICATION ---

    if (gameData['hostId'] != widget.playerId ||
        gameData['gameState'] != 'playing') {
      return;
    }

    final turnStartTimeStamp = gameData['turnStartTime'] as Timestamp?;
    if (turnStartTimeStamp == null) return;

    final turnStartTime = turnStartTimeStamp.toDate();
    const defaultTurnDuration = Duration(seconds: 30);
    const hostActionDuration = Duration(seconds: 15);
    final int turnSecs = (gameData['turnTimerSeconds'] as num?)?.toInt() ?? 30;
    final int resultSecs =
        (gameData['resultTimerSeconds'] as num?)?.toInt() ?? 15;
    final Duration turnTimerDuration = Duration(seconds: turnSecs);
    final Duration resultTimerDuration = Duration(seconds: resultSecs);

    Duration turnDuration;
    Function()? timeoutAction;

    final gameType = gameData['gameType'];
    final roundState = gameData['roundState'];
    final currentPhase = gameData['currentPhase'];

    // --- LOGIQUE DE DÉTECTION DU TIMEOUT ---

    // 1. Phases de Résultat
    if (roundState == 'result' ||
        currentPhase == 'turn_result' ||
        roundState == 'round_end') {
      turnDuration = resultTimerDuration;
      if (gameType == 'Infiltré & Mr. White') {
        timeoutAction =
            () => _firebaseService.processEliminationsAndCheckWin(
              widget.gameCode,
            );
      } else {
        timeoutAction =
            () => _firebaseService.handleHostActionTimeout(widget.gameCode);
      }
    }
    // 2. Phases de Vote (Vote classique ou vote Infiltré)
    else if (roundState == 'voting' || currentPhase == 'voting') {
      turnDuration = turnTimerDuration;
      timeoutAction =
          () => _firebaseService.handleVotingTimeout(widget.gameCode);
    }
    // 3. Cas Spécifique : Synonyme ou Banni (Phase de réponse)
    else if ((roundState == 'answering' || roundState == 'playing') &&
        (gameType == 'Le Juge' ||
            gameType == 'Le Roi des Mèmes' ||
            gameType == 'Synonyme ou Banni')) {
      turnDuration = turnTimerDuration;
      timeoutAction =
          () => _firebaseService.handleSynonymeInputTimeout(widget.gameCode);
    }
    // 4. Autres Phases de Jeu (Tour par tour)
    else {
      turnDuration = turnTimerDuration;
      switch (gameType) {
        case 'Photo Roulette':
          timeoutAction =
              () =>
                  _firebaseService.handlePhotoRouletteTimeout(widget.gameCode);
          break;
        case 'Uno':
          timeoutAction =
              () => _firebaseService.handleUnoTimeout(widget.gameCode);
          break;
        case 'Zéro Pointé':
          timeoutAction =
              () => _firebaseService.handleZeroPointeTimeout(widget.gameCode);
          break;
        case 'Poker':
          timeoutAction =
              () => _firebaseService.handlePokerTimeout(widget.gameCode);
          break;
        case 'Gribouillis':
          // Gribouillis is simultaneous - no individual turn timeout needed
          // The timer is for the step duration; no action on timeout
          timeoutAction = null;
          break;
        case 'Loup-Garou':
          // Ajout des actions de timeout pour débloquer le jeu si le temps est écoulé
          if (gameData['phase'] == 'nuit') {
            timeoutAction =
                () => _firebaseService.startNextNightPhase(widget.gameCode);
          } else if (gameData['phase'] == 'jour_discussion') {
            timeoutAction =
                () => _firebaseService.startDayVotePhase(widget.gameCode);
          } else if (gameData['phase'] == 'jour_vote') {
            timeoutAction =
                () => _firebaseService.processDayVote(widget.gameCode);
          }
          break;
        case 'Le Menteur':
          timeoutAction =
              () => _firebaseService.handleTurnTimeout(widget.gameCode);
          break;
        case 'Infiltré & Mr. White':
          if (currentPhase == 'clue_giving') {
            turnDuration = Duration(
              seconds: (gameData['turnTimerSeconds'] as int?) ?? 30,
            );
            timeoutAction =
                () => _firebaseService.handleTurnTimeout(widget.gameCode);
          }
          break;
        case 'Just One':
          // On gère le timeout pour TOUTES les phases actives de Just One
          if ([
            'guesser_chooses_word',
            'clue_giving',
            'reveal_clues',
          ].contains(roundState)) {
            timeoutAction =
                () => _firebaseService.handleJustOneTimeout(widget.gameCode);
          }
          break;
        case 'Skull':
          if (roundState == 'placing' || roundState == 'bidding') {
            timeoutAction =
                () => _firebaseService.handleSkullTimeout(widget.gameCode);
          }
          break;
        // FIN DE L'AJOUT

        default:
          timeoutAction =
              () => _firebaseService.handleTurnTimeout(widget.gameCode);
          break;
      }
    }

    if (timeoutAction == null) return;

    final timeRemaining =
        turnDuration - DateTime.now().difference(turnStartTime);

    _playerTurnTimer = Timer(
      timeRemaining.isNegative ? Duration.zero : timeRemaining, 
      () {
        _firebaseService.getGameStream(widget.gameCode).first.then((snapshot) {
          if (!snapshot.exists) return;
          final latestGameData = snapshot.data() as Map<String, dynamic>;
          final latestTimestamp = latestGameData['turnStartTime'] as Timestamp?;
          
          // Sécurité : on n'exécute l'action que si le tour n'a pas déjà changé
          if (latestTimestamp?.millisecondsSinceEpoch == turnStartTimeStamp.millisecondsSinceEpoch) {
            timeoutAction?.call();
          }
        });
      }
    );
  }

  Widget _buildUndercoverGameUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String currentPhase = gameData['currentPhase'];
    final String gameState = gameData['gameState'];
    final playerData = Map<String, dynamic>.from(gameData['playerData'] ?? {});
    final myData = playerData[playerId] ?? {};
    final myRole = myData['role'];
    final mySecretWord = myData['secretWord'];
    final List<dynamic> mySpecialAbilities =
        myData['specialAbilities'] as List<dynamic>? ?? [];

    final Widget playerIdentityWidget = Card(
      color: Colors.black.withOpacity(0.85),
      margin: const EdgeInsets.only(top: 8.0),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12.0, vertical: 8.0),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              "VOTRE IDENTITÉ",
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                color: Colors.white70,
                fontWeight: FontWeight.bold,
              ),
            ),
            Divider(color: Colors.white30),
            RichText(
              textAlign: TextAlign.center,
              text: TextSpan(
                style: TextStyle(fontSize: 14, color: Colors.white),
                children: [
                  TextSpan(
                    text: "Rôle: ",
                    style: TextStyle(color: Colors.white70),
                  ),
                  TextSpan(
                    text: "$myRole",
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.amberAccent,
                    ),
                  ),
                ],
              ),
            ),
            RichText(
              textAlign: TextAlign.center,
              text: TextSpan(
                style: TextStyle(fontSize: 14, color: Colors.white),
                children: [
                  TextSpan(
                    text: "Mot: ",
                    style: TextStyle(color: Colors.white70),
                  ),
                  TextSpan(
                    text: "$mySecretWord",
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.cyanAccent,
                      fontSize: 16,
                    ),
                  ),
                ],
              ),
            ),
            if (mySpecialAbilities.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(top: 4.0),
                child: Column(
                  children: [
                    Text(
                      "Capacités:",
                      style: TextStyle(color: Colors.white70, fontSize: 14),
                    ),
                    Wrap(
                      spacing: 8.0,
                      runSpacing: 4.0,
                      alignment: WrapAlignment.center,
                      children:
                          mySpecialAbilities
                              .map(
                                (ability) => ActionChip(
                                  label: Text(ability.toString()),
                                  onPressed:
                                      () => _showRoleDescriptionDialog(
                                        context,
                                        ability.toString(),
                                      ),
                                  backgroundColor: Colors.deepPurple[800],
                                  labelStyle: TextStyle(color: Colors.white),
                                ),
                              )
                              .toList(),
                    ),
                  ],
                ),
              ),
          ],
        ),
      ),
    );

    if (gameState == 'gameOver') {
      return _buildUndercoverGameOverUI(context, gameData, playerId);
    }

    Widget mainContent;
    switch (currentPhase) {
      case 'clue_giving':
        mainContent = _buildUndercoverClueGivingUI(context, gameData, playerId);
        break;
      case 'voting':
        mainContent = _buildUndercoverDiscussionVotingUI(
          context,
          gameData,
          playerId,
        );
        break;
      case 'turn_result':
        mainContent = _buildUndercoverTurnResultUI(context, gameData, playerId);
        break;
      case 'tie_breaker':
        mainContent = _buildUndercoverTieBreakerUI(context, gameData, playerId);
        break;
      case 'avenger_revenge':
        mainContent = _buildUndercoverAvengerUI(context, gameData, playerId);
        break;
      default:
        mainContent = Center(
          child: Text("Phase de jeu inconnue : $currentPhase"),
        );
    }

    return Column(
      children: [Expanded(child: mainContent), playerIdentityWidget],
    );
  }

