  Widget _buildUndercoverTurnResultUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = gameData['playerData'];
    final eliminatedIds = List<String>.from(
      gameData['eliminatedThisTurn'] ?? [],
    );
    final bool isHost = gameData['hostId'] == playerId;

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          "Résultat du vote",
          style: Theme.of(context).textTheme.headlineMedium,
        ),
        SizedBox(height: 20),
        if (eliminatedIds.isEmpty)
          Text(
            "Personne n'a été éliminé (égalité).",
            style: TextStyle(fontSize: 18, color: Colors.amber),
          )
        else
          ...eliminatedIds.map((pId) {
            final pName = playerData[pId]['name'];
            final pRole = playerData[pId]['role'];
            final List<dynamic> specialAbilities = List<dynamic>.from(
              playerData[pId]['specialAbilities'] ?? [],
            );
            final String roleDisplay =
                specialAbilities.isNotEmpty
                    ? "$pRole (${specialAbilities.join(', ')})"
                    : pRole;
            return Text(
              "$pName a été éliminé ! Son rôle était : $roleDisplay",
              style: TextStyle(fontSize: 18, color: Colors.amber),
              textAlign: TextAlign.center,
            );
          }),
        SizedBox(height: 30),
        if (isHost)
          ElevatedButton(
            onPressed:
                () => _firebaseService.processEliminationsAndCheckWin(
                  widget.gameCode,
                ),
            child: Text("Continuer"),
          )
        else
          Center(child: Text("En attente de l'hôte...")),
      ],
    );
  }

  Widget _buildUndercoverTieBreakerUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String? goddessId = gameData['specialRoles']?['justiceGoddess'];
    final bool amIGoddess = playerId == goddessId;
    final List<String> tiedPlayers = List<String>.from(
      gameData['tiedPlayers'] ?? [],
    );
    final playerData = gameData['playerData'];

    if (!amIGoddess) {
      return Center(
        child: Text(
          "Égalité ! En attente de la décision de la Déesse...",
          textAlign: TextAlign.center,
        ),
      );
    }

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text("Égalité !", style: Theme.of(context).textTheme.headlineMedium),
        Text(
          "En tant que Déesse, tu dois trancher :",
          style: Theme.of(context).textTheme.titleLarge,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        ...tiedPlayers.map(
          (pId) => ElevatedButton(
            onPressed:
                () => _firebaseService.undercoverGoddessDecision(
                  widget.gameCode,
                  pId,
                ),
            child: Text("Éliminer ${playerData[pId]['name']}"),
          ),
        ),
      ],
    );
  }

  Widget _buildUndercoverAvengerUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = gameData['playerData'];
    String? avengerId;
    playerData.forEach((pId, data) {
      if ((data['specialAbilities'] as List?)?.contains('Vengeuse') ?? false)
        avengerId = pId;
    });

    if (playerId != avengerId) {
      return Center(
        child: Text(
          "La Vengeuse choisit sa cible...",
          textAlign: TextAlign.center,
        ),
      );
    }

    List<String> activePlayers =
        playerData.entries
            .where((e) => e.value['status'] == 'active')
            .map((e) => e.key)
            .toList();

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text("Vengeance !", style: Theme.of(context).textTheme.headlineMedium),
        Text(
          "Tu as été éliminée. Emporte quelqu'un avec toi !",
          style: Theme.of(context).textTheme.titleLarge,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        ...activePlayers.map(
          (pId) => ElevatedButton(
            onPressed:
                () => _firebaseService.undercoverAvengerDecision(
                  widget.gameCode,
                  avengerId!,
                  pId,
                ),
            child: Text("Éliminer ${playerData[pId]['name']}"),
          ),
        ),
      ],
    );
  }

