  Widget _buildUndercoverClueGivingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final playerOrder = List<String>.from(gameData['playerOrder']);
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    if (playerOrder.isEmpty || currentPlayerIndex >= playerOrder.length) {
      return Center(child: CircularProgressIndicator());
    }

    final String currentPlayerId = playerOrder[currentPlayerIndex];
    final String currentPlayerName =
        playerData[currentPlayerId]?['name'] ?? '...';
    final bool isMyTurn = playerId == currentPlayerId;
    final bool hasAlreadySubmitted =
        (gameData['playerClues'] as Map?)?.containsKey(playerId) ?? false;

    return Column(
      children: [
        SizedBox(height: 10),
        Text(
          isMyTurn
              ? "🎯 C'est à toi de donner un indice !"
              : "Au tour de $currentPlayerName...",
          style: Theme.of(context).textTheme.headlineSmall,
          textAlign: TextAlign.center,
        ),
        if (!isMyTurn) ...[SizedBox(height: 10), CircularProgressIndicator()],
        SizedBox(height: 12),
        _buildUndercoverPlayerLine(context, gameData, playerId),
        SizedBox(height: 12),
        if (isMyTurn && !hasAlreadySubmitted) ...[
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16.0),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _answerController,
                    autofocus: true,
                    decoration: InputDecoration(
                      labelText: 'Ton indice (un mot)',
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                      filled: true,
                      fillColor: Colors.grey[850],
                    ),
                    onSubmitted: (v) {
                      final clue = v.trim();
                      if (clue.isNotEmpty && !_isActionPending) {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .submitUndercoverClue(
                              widget.gameCode,
                              playerId,
                              clue,
                            )
                            .whenComplete(() {
                              if (mounted) {
                                _answerController.clear();
                                setState(() => _isActionPending = false);
                              }
                            });
                      }
                    },
                  ),
                ),
                SizedBox(width: 8),
                ElevatedButton(
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            final clue = _answerController.text.trim();
                            if (clue.isNotEmpty) {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .submitUndercoverClue(
                                    widget.gameCode,
                                    playerId,
                                    clue,
                                  )
                                  .whenComplete(() {
                                    if (mounted) {
                                      _answerController.clear();
                                      setState(() => _isActionPending = false);
                                    }
                                  });
                            }
                          },
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.deepPurpleAccent,
                  ),
                  child:
                      _isActionPending
                          ? SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              color: Colors.white,
                            ),
                          )
                          : Text('Valider'),
                ),
              ],
            ),
          ),
          SizedBox(height: 8),
        ] else if (isMyTurn && hasAlreadySubmitted) ...[
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              '✅ Indice envoyé ! En attente des autres joueurs...',
              style: TextStyle(
                color: Colors.greenAccent,
                fontStyle: FontStyle.italic,
              ),
              textAlign: TextAlign.center,
            ),
          ),
        ],
        Expanded(child: _buildChatInterface(gameData, playerId)),
      ],
    );
  }

  Widget _buildUndercoverDiscussionVotingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final myData = playerData[playerId];
    final bool canIVote = myData['canVote'] ?? false;
    final bool hasVoted = gameData['votes']?[playerId] != null;
    final String currentPhase = gameData['currentPhase'];
    final bool isHost = gameData['hostId'] == playerId;

    return Column(
      children: [
        if (currentPhase == 'discussion') ...[
          Text(
            "Phase de discussion",
            style: Theme.of(context).textTheme.headlineSmall,
          ),
          SizedBox(height: 10),
          if (isHost)
            ElevatedButton(
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .startUndercoverVoting(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
              child: Text("Lancer le vote"),
            )
          else
            Text("Débattez ! L'hôte lancera le vote."),
        ] else if (currentPhase == 'voting') ...[
          Text(
            "À qui la sentence ?",
            style: Theme.of(context).textTheme.headlineSmall,
          ),
          if (hasVoted)
            Text(
              "Vote enregistré. En attente...",
              style: TextStyle(color: Colors.greenAccent),
            )
          else if (!canIVote)
            Text(
              "Vous ne pouvez pas voter.",
              style: TextStyle(color: Colors.redAccent),
            )
          else
            Text(
              "Appuie sur la bulle d'un joueur pour voter.",
              style: TextStyle(color: Colors.amberAccent),
            ),
        ],
        SizedBox(height: 20),
        _buildUndercoverPlayerLine(
          context,
          gameData,
          playerId,
        ), // La ligne des joueurs
        SizedBox(height: 20),
        Expanded(child: _buildChatInterface(gameData, playerId)), // Le chat
      ],
    );
  }

  Widget _buildUndercoverPlayerLine(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final playerData = Map<String, dynamic>.from(gameData['playerData']);
    final playerOrder = List<String>.from(gameData['playerOrder']);
    final clues = Map<String, dynamic>.from(gameData['playerClues'] ?? {});
    final currentPhase = gameData['currentPhase'];
    final isVotingPhase =
        currentPhase == 'voting' || currentPhase == 'resolving_votes';
    final myData = playerData[playerId];
    final canIVote = myData['canVote'] ?? false;
    final votes = Map<String, dynamic>.from(gameData['votes'] ?? {});

    Map<String, List<String>> votesReceived = {};
    votes.forEach((voterId, targetId) {
      if (!votesReceived.containsKey(targetId)) {
        votesReceived[targetId] = [];
      }
      votesReceived[targetId]!.add(playerData[voterId]?['name'] ?? 'Anonyme');
    });

    final Map<String, IconData> roleIcons = {
      'Boomerang': Icons.autorenew,
      'Vengeuse': Icons.whatshot,
      'Déesse de la Justice': Icons.gavel,
      'Fantôme': Icons.visibility,
      'Amoureux': Icons.favorite,
      'Mr. Meme': Icons.gesture,
      'Vendeur de Falafels': Icons.fastfood,
      'Duellistes': Icons.compare_arrows,
    };

    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      padding: const EdgeInsets.symmetric(horizontal: 16.0),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children:
            playerOrder.map((pId) {
              final pData = playerData[pId];
              final isDead = pData['status'] == 'eliminated';
              final clue = clues[pId];
              final bool canBeVotedFor =
                  isVotingPhase && canIVote && pId != playerId && !isDead;
              final List<String> voters = votesReceived[pId] ?? [];

              return Padding(
                padding: const EdgeInsets.symmetric(horizontal: 12.0),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    GestureDetector(
                      onTap:
                          canBeVotedFor && !_isActionPending
                              ? () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitUndercoverVote(
                                      widget.gameCode,
                                      playerId,
                                      pId,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              }
                              : null,
                      child: Opacity(
                        opacity: clue != null ? 1.0 : 0.0,
                        child: Container(
                          constraints: BoxConstraints(
                            minHeight: 40,
                            maxWidth: 100,
                          ),
                          padding: EdgeInsets.all(8),
                          decoration: BoxDecoration(
                            color:
                                canBeVotedFor
                                    ? Colors.deepPurple
                                    : Colors.grey[800],
                            borderRadius: BorderRadius.circular(10),
                          ),
                          child: Text(
                            clue ?? "",
                            textAlign: TextAlign.center,
                            style: TextStyle(color: Colors.white),
                          ),
                        ),
                      ),
                    ),
                    SizedBox(height: 8),

                    Stack(
                      alignment: Alignment.center,
                      clipBehavior: Clip.none,
                      children: [
                        CircleAvatar(
                          radius: 30,
                          child: Text(
                            (pData['name'] as String?)?.substring(0, 1) ?? "?",
                            style: TextStyle(fontSize: 24),
                          ),
                        ),
                        if (isDead)
                          Positioned.fill(
                            child: Icon(
                              Icons.close,
                              color: Colors.red.withOpacity(0.8),
                              size: 70,
                            ),
                          ),
                      ],
                    ),
                    SizedBox(height: 4),

                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          pData['name'],
                          style: TextStyle(
                            color: isDead ? Colors.grey : Colors.white,
                          ),
                        ),
                        ...(pData['revealedAbilities'] as List<dynamic>? ?? [])
                            .map((ability) {
                              if (roleIcons.containsKey(ability)) {
                                return Padding(
                                  padding: const EdgeInsets.only(left: 4.0),
                                  child: Icon(
                                    roleIcons[ability],
                                    size: 16,
                                    color: Colors.cyanAccent,
                                  ),
                                );
                              }
                              return SizedBox.shrink();
                            })
                            .toList(),
                      ],
                    ),

                    if (isVotingPhase && voters.isNotEmpty)
                      Padding(
                        padding: const EdgeInsets.only(top: 4.0),
                        child: Column(
                          children: [
                            Chip(
                              label: Text(
                                "${voters.length} vote(s)",
                                style: TextStyle(fontSize: 10),
                              ),
                              padding: EdgeInsets.zero,
                              visualDensity: VisualDensity.compact,
                            ),
                            Text(
                              voters.join(', '),
                              style: TextStyle(
                                fontSize: 9,
                                color: Colors.grey[400],
                              ),
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ],
                        ),
                      ),
                  ],
                ),
              );
            }).toList(),
      ),
    );
  }

  Future<void> _pickAndUploadPhotos(
    String playerId,
    Map<String, dynamic> gameData,
  ) async {
    setState(() => _isUploading = true);
    try {
      final PermissionState ps = await PhotoManager.requestPermissionExtend();
      if (ps != PermissionState.authorized && ps != PermissionState.limited) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              "Permission refusée. Impossible d'accéder à la galerie.",
            ),
          ),
        );
        setState(() => _isUploading = false);
        return;
      }

      int photosToPick =
          gameData['photoRouletteSettings']?['photosPerPlayer'] ?? 20;

      List<AssetPathEntity> albums = await PhotoManager.getAssetPathList(
        type: RequestType.image,
      );
      if (albums.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Aucun album photo trouvé.")),
        );
        setState(() => _isUploading = false);
        return;
      }

      List<AssetEntity> allPhotos = await albums[0].getAssetListRange(
        start: 0,
        end: 500,
      );
      if (allPhotos.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Votre galerie est vide.")),
        );
        setState(() => _isUploading = false);
        return;
      }

      allPhotos.shuffle();
      List<AssetEntity> selectedAssets = allPhotos.take(photosToPick).toList();
      List<String> uploadedUrls = [];

      for (final asset in selectedAssets) {
        final File? file = await asset.file;
        if (file != null) {
          final Uint8List bytes = await file.readAsBytes();
          final url = await _supabaseService.uploadImageBytes(
            bytes,
            widget.gameCode,
          );
          if (url != null) uploadedUrls.add(url);
        }
      }

      if (uploadedUrls.isNotEmpty) {
        await _firebaseService.playerReadyForPhotoRoulette(
          widget.gameCode,
          playerId,
          uploadedUrls,
        );
      } else {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text("Aucune photo n'a pu être uploadée.")),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Erreur lors de la sélection automatique : $e")),
      );
    } finally {
      if (mounted) setState(() => _isUploading = false);
    }
  }

  void _startPhotoRouletteTimer(
    DateTime startTime,
    int durationSeconds,
    String gameCode,
    String currentRoundState,
  ) {
    _timerSubscription?.cancel();
    _timerSubscription = Stream.periodic(
      Duration(seconds: 1),
      (count) => count,
    ).listen((_) {
      if (!mounted) {
        _timerSubscription?.cancel();
        return;
      }
      final now = DateTime.now();
      final elapsed = now.difference(startTime).inSeconds;
      final remaining = durationSeconds - elapsed;

      if (remaining <= 0) {
        _timerSubscription?.cancel();

        // --- CORRECTION ---
        // ANCIEN : final String playerId = Provider.of<String>(context, listen: false);
        // NOUVEAU :
        final String playerId = widget.playerId;
        // ------------------

        final gameData =
            Provider.of<DocumentSnapshot>(context, listen: false).data()
                as Map<String, dynamic>;
        if (gameData['hostId'] == playerId &&
            currentRoundState == 'showing_photo') {
          _firebaseService.handlePhotoRouletteTimeout(gameCode);
        }
      }
    });
  }

  Widget _buildPhotoRouletteUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'];
    final Map<String, dynamic> players = Map.from(gameData['players']);
    final bool isHost = gameData['hostId'] == playerId;

    switch (roundState) {
      case 'photo_selection':
        final Map<String, dynamic> readyPlayers = Map.from(
          gameData['readyPlayers'] ?? {},
        );
        final bool amIReady = readyPlayers[playerId] ?? false;

        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(
              "Préparation de la partie",
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 20),
            Text(
              "L'application va sélectionner ${gameData['photoRouletteSettings']?['photosPerPlayer'] ?? 20} photos aléatoires dans votre galerie.",
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 20),
            if (amIReady)
              Padding(
                padding: const EdgeInsets.all(16.0),
                child: Column(
                  children: [
                    Icon(Icons.check_circle, color: Colors.green, size: 50),
                    Text(
                      "Vous êtes prêt !",
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                    Text("En attente des autres joueurs..."),
                  ],
                ),
              )
            else if (_isUploading)
              CircularProgressIndicator()
            else
              ElevatedButton.icon(
                icon: Icon(Icons.sync),
                label: Text("Autoriser et Lancer la sélection"),
                onPressed: () => _pickAndUploadPhotos(playerId, gameData),
              ),
            SizedBox(height: 30),
            Text(
              "Joueurs prêts: ${readyPlayers.length} / ${players.length}",
              style: Theme.of(context).textTheme.bodyLarge,
            ),
            ...players.keys.map((pId) {
              return ListTile(
                title: Text(players[pId]['name'] ?? '...'),
                trailing: Icon(
                  (readyPlayers[pId] ?? false)
                      ? Icons.check_circle
                      : Icons.hourglass_empty,
                  color:
                      (readyPlayers[pId] ?? false) ? Colors.green : Colors.grey,
                ),
              );
            }).toList(),
          ],
        );

      case 'showing_photo':
        final photoUrl = gameData['currentPhoto']?['url'];
        final startTime = (gameData['roundStartTime'] as Timestamp?)?.toDate();
        final duration = gameData['turnTimerSeconds'] ?? 5;
        final Map<String, dynamic> votes = Map.from(gameData['votes'] ?? {});
        final bool hasVoted = votes.containsKey(playerId);

        if (photoUrl == null || startTime == null)
          return Center(child: Text("Chargement de la photo..."));

        if (isHost) {
          _startPhotoRouletteTimer(
            startTime,
            duration,
            widget.gameCode,
            roundState,
          );
        }

        return Column(
          children: [
            Text(
              "À qui est cette photo ?",
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 10),
            StreamBuilder(
              stream: Stream.periodic(Duration(milliseconds: 100)),
              builder: (context, snapshot) {
                int elapsed = DateTime.now().difference(startTime).inSeconds;
                int remaining = duration - elapsed;
                return LinearProgressIndicator(
                  value: (remaining > 0 ? remaining : 0) / duration,
                );
              },
            ),
            Expanded(
              flex: 3,
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 8.0),
                child: Image.network(
                  photoUrl,
                  fit: BoxFit.contain,
                  loadingBuilder: (context, child, progress) {
                    return progress == null
                        ? child
                        : Center(child: CircularProgressIndicator());
                  },
                ),
              ),
            ),
            SizedBox(height: 10),
            Expanded(
              flex: 2,
              child:
                  hasVoted
                      ? _buildWaitingWidget("Vous avez voté !", players, 0, 0)
                      : GridView.builder(
                        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                          crossAxisCount: 2,
                          childAspectRatio: 3.5,
                          mainAxisSpacing: 8,
                          crossAxisSpacing: 8,
                        ),
                        itemCount: players.length,
                        itemBuilder: (context, index) {
                          String pId = players.keys.elementAt(index);
                          String pName = players[pId]?['name'] ?? '...';
                          return ElevatedButton(
                            onPressed:
                                _isActionPending
                                    ? null
                                    : () {
                                      setState(() => _isActionPending = true);
                                      _firebaseService
                                          .submitPhotoRouletteVote(
                                            widget.gameCode,
                                            playerId,
                                            pId,
                                          )
                                          .whenComplete(() {
                                            if (mounted)
                                              setState(
                                                () => _isActionPending = false,
                                              );
                                          });
                                    },
                            child: Text(pName, textAlign: TextAlign.center),
                          );
                        },
                      ),
            ),
          ],
        );

      case 'results':
        final Map<String, dynamic> roundResults = Map.from(
          gameData['roundResults'] ?? {},
        );
        final String correctOwnerId = gameData['currentPhoto']['ownerId'];
        final String correctOwnerName =
            players[correctOwnerId]?['name'] ?? 'Inconnu';
        final String photoUrl = gameData['currentPhoto']['url'];
        final startTime =
            (gameData['roundResultsTimestamp'] as Timestamp?)?.toDate();

        if (startTime == null)
          return Center(child: Text("Calcul des résultats..."));

        if (isHost) {
          _startPhotoRouletteTimer(
            startTime,
            5,
            widget.gameCode,
            roundState,
          ); // 5s pour voir les résultats
        }

        return Column(
          children: [
            Text(
              "La photo était à... $correctOwnerName !",
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            StreamBuilder(
              stream: Stream.periodic(const Duration(milliseconds: 100)),
              builder: (context, snapshot) {
                int elapsed = DateTime.now().difference(startTime).inSeconds;
                int remaining = 5 - elapsed;
                if (remaining <= 0 && isHost) {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _firebaseService.startNextPhotoRouletteRound(
                      widget.gameCode,
                    );
                  });
                }
                return LinearProgressIndicator(
                  value: (remaining > 0 ? remaining : 0) / 5.0,
                );
              },
            ),
            Expanded(
              flex: 2,
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 8.0),
                child: Image.network(photoUrl, fit: BoxFit.contain),
              ),
            ),
            Expanded(
              flex: 3,
              child: ListView(
                children:
                    players.keys.map((pId) {
                      final pName = players[pId]?['name'] ?? '...';
                      final resultData =
                          roundResults[pId] as Map<String, dynamic>?;
                      final bool wasCorrect = resultData?['correct'] ?? false;
                      final int scoreGained = resultData?['score'] ?? 0;

                      return ListTile(
                        title: Text(pName),
                        trailing: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            if (wasCorrect)
                              Text(
                                "+${scoreGained} pts",
                                style: TextStyle(
                                  color: Colors.greenAccent,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                            SizedBox(width: 8),
                            Icon(
                              wasCorrect ? Icons.check : Icons.close,
                              color: wasCorrect ? Colors.green : Colors.red,
                            ),
                          ],
                        ),
                      );
                    }).toList(),
              ),
            ),
          ],
        );

      case 'gameOver':
        List<MapEntry<String, dynamic>> sortedPlayers =
            players.entries.toList()..sort(
              (a, b) =>
                  (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
            );
        String winnerName =
            sortedPlayers.isNotEmpty
                ? sortedPlayers.first.value['name']
                : "Personne";

        return Center(
          child: Card(
            child: Padding(
              padding: const EdgeInsets.all(24.0),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    "Partie Terminée !",
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  SizedBox(height: 10),
                  Text(
                    "Le gagnant est $winnerName !",
                    style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                      color: Colors.amberAccent,
                    ),
                  ),
                  SizedBox(height: 20),
                  Text(
                    "Classement Final :",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  ...sortedPlayers.asMap().entries.map((entry) {
                    int rank = entry.key + 1;
                    String name = entry.value.value['name'];
                    int score = entry.value.value['score'];
                    return Text("$rank. $name: $score points");
                  }),
                  SizedBox(height: 20),
                  ElevatedButton(
                    onPressed:
                        () => Navigator.of(
                          context,
                        ).popUntil((route) => route.isFirst),
                    child: Text("Retour à l'accueil"),
                  ),
                ],
              ),
            ),
          ),
        );

      default:
        return _buildWaitingWidget("Chargement de la partie...", players, 0, 0);
    }
  }

  void _startTimer(
    DateTime startTime,
    int durationSeconds,
    String gameCode,
    String currentRoundState,
    Map<String, dynamic> gameData,
  ) {
    _timerSubscription?.cancel();
    _timerSubscription = Stream.periodic(
      Duration(seconds: 1),
      (count) => count,
    ).listen((_) {
      if (!mounted) {
        _timerSubscription?.cancel();
        return;
      }

      // --- AJOUT IMPORTANT : Forcer le rafraîchissement de l'écran ---
      setState(() {});
      // ---------------------------------------------------------------

      final now = DateTime.now();
      final elapsed = now.difference(startTime).inSeconds;
      final remaining = durationSeconds - elapsed;

      if (remaining <= 0) {
        _timerSubscription?.cancel();

        String gameType = gameData['gameType'];
        // Vérification pour éviter les appels multiples si l'hôte a déjà déclenché
        final String playerId = widget.playerId;
        final bool isHost = gameData['hostId'] == playerId;

        if (isHost) {
          if (gameType == 'Petit Bac' &&
              !(gameData['petitBacRoundEnded'] ?? false)) {
            _firebaseService.evaluatePetitBacAnswers(gameCode);
          } else if (gameType == 'Pictionary') {
            _firebaseService.handlePictionaryTimeout(
              gameCode,
              currentRoundState,
            );
          } else if (gameType == 'La Patate Chaude' ||
              gameType == 'Le Jeu des Catégories') {
            _firebaseService.handleHotPotatoTimeout(gameCode);
          }
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final String playerId = widget.playerId;

    return WillPopScope(
      onWillPop: () async {
        final shouldPop = await showDialog<bool>(
          context: context,
          builder:
              (context) => AlertDialog(
                title: const Text('Quitter la partie ?'),
                content: const Text(
                  'Si vous quittez, vous ne pourrez pas revenir. Êtes-vous sûr ?',
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(context, false),
                    child: const Text('Annuler'),
                  ),
                  TextButton(
                    onPressed: () async {
                      if (_agoraInitialized) {
                        await _agoraService.leaveChannel();
                        await Future.delayed(const Duration(milliseconds: 300));
                      }
                      _firebaseService.removePlayerFromGame(
                        widget.gameCode,
                        playerId,
                      );
                      Navigator.pop(context, true);
                    },
                    child: const Text('Quitter'),
                  ),
                ],
              ),
        );
        return shouldPop ?? false;
      },
      child: StreamBuilder<DocumentSnapshot>(
        stream: _firebaseService.getGameStream(widget.gameCode),
        builder: (context, snapshot) {
          if (!snapshot.hasData) {
            return Scaffold(body: Center(child: CircularProgressIndicator()));
          }
          if (snapshot.hasError) {
            return Scaffold(
              body: Center(child: Text("Erreur: ${snapshot.error}")),
            );
          }
          if (!snapshot.data!.exists) {
            Future.microtask(
              () => Navigator.of(context).popUntil((route) => route.isFirst),
            );
            return Scaffold(
              body: Center(
                child: Text("La partie a été terminée ou n'existe plus."),
              ),
            );
          }
          final gameData = snapshot.data!.data() as Map<String, dynamic>;

          _startPlayerTurnTimer(gameData);

          return Provider<DocumentSnapshot>.value(
            value: snapshot.data!,
            child: Builder(
              builder: (context) {
                final gameData = snapshot.data!.data() as Map<String, dynamic>;
                final players =
                    (gameData['players'] as Map<String, dynamic>?) ?? {};
                final int currentRound = gameData['currentRound'] ?? 0;

                final int currentPlayerIndex =
                    gameData['currentPlayerIndex'] ?? -1;

                if (currentRound > _lastProcessedRound) {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    _answerController.clear();
                    if (mounted)
                      setState(() {
                        _pictionaryStrokeCount = 0;
                        _straightLinePoints = [];
                        _straightLineStart = null;
                        _straightLineCurrentEnd = null;
                      });
                  });
                  _lastProcessedRound = currentRound;
                }

                // Gestion des timers spécifiques (inchangé)
                if (gameData['petitBacRoundStartTime'] != null &&
                    !(gameData['petitBacRoundEnded'] ?? false)) {
                  final Timestamp roundStartTimeStamp =
                      gameData['petitBacRoundStartTime'];
                  final String timerKey =
                      '${roundStartTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      roundStartTimeStamp.toDate(),
                      gameData['turnTimerSeconds'] ?? 120,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else if (gameData['pictionaryStartTime'] != null &&
                    gameData['roundState'] != 'result') {
                  final Timestamp startTimeStamp =
                      gameData['pictionaryStartTime'];
                  final int duration =
                      (gameData['roundState'] == 'drawing')
                          ? (gameData['turnTimerSeconds'] ?? 90)
                          : (gameData['resultTimerSeconds'] ?? 30);
                  final String timerKey =
                      '${startTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      startTimeStamp.toDate(),
                      duration,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else if (gameData['hotPotatoRoundStartedAt'] != null &&
                    gameData['roundState'] == 'playing') {
                  final Timestamp startTimeStamp =
                      gameData['hotPotatoRoundStartedAt'];
                  int duration = gameData['turnTimerSeconds'] ?? 30;
                  final String timerKey =
                      '${startTimeStamp.millisecondsSinceEpoch}_${gameData['roundState']}';
                  if (timerKey != _lastTimerKey) {
                    _lastTimerKey = timerKey;
                    _startTimer(
                      startTimeStamp.toDate(),
                      duration,
                      widget.gameCode,
                      gameData['roundState'],
                      gameData,
                    );
                  }
                } else {
                  if (_lastTimerKey != null) {
                    _lastTimerKey = null;
                    _timerSubscription?.cancel();
                  }
                }

                _unoDrawActionDone = gameData['unoDrawActionDone'] ?? false;

                // Récupérer les UIDs Agora de tous les joueurs
                _playerAgoraUids = {};
                players.forEach((pId, pData) {
                  if (pData['agoraUid'] != null) {
                    _playerAgoraUids[pId] = pData['agoraUid'];
                  }
                });

                // Déterminer les paramètres spécifiques pour Time's Up
                bool isTimeUpMime = false;
                String? timeUpActiveTeam;
                String? activePlayerId;

                if (gameData['gameType'] == "Time's Up") {
                  int currentRoundNumber = gameData['currentRoundNumber'] ?? 1;
                  isTimeUpMime = currentRoundNumber == 3; // Mode Mime
                  
                  // Trouver l'équipe active
                  String currentGuesserId = gameData['currentGuesserId'] ?? '';
                  List<String> redTeam = List<String>.from(gameData['redTeam'] ?? []);
                  List<String> blueTeam = List<String>.from(gameData['blueTeam'] ?? []);
                  
                  if (redTeam.contains(currentGuesserId)) {
                    timeUpActiveTeam = 'red';
                  } else if (blueTeam.contains(currentGuesserId)) {
                    timeUpActiveTeam = 'blue';
                  }
                  activePlayerId = currentGuesserId;
                }

                // Connexion Agora si vidéo activée
                // _initAgora() a déjà été appelé dans initState()

                Widget scaffold = Scaffold(
                  appBar: AppBar(
                    title: Text(gameData['gameType'] ?? "Jeu en cours"),
                    actions: [
                      IconButton(
                        icon: Icon(Icons.info_outline),
                        onPressed:
                            () => showGameRules(context, gameData['gameType']),
                      ),
                    ],
                    automaticallyImplyLeading: false,
                    bottom: _buildTurnTimerIndicator(gameData),
                  ),
                  body: Column(
                    children: [
                      // OVERLAY VIDÉO EN HAUT
                      if (gameData['videoEnabled'] == true)
                        GameVideoOverlay(
                          players: gameData, // On passe tout le gameData pour avoir accès aux équipes
                          playerAgoraUids: _playerAgoraUids,
                          currentPlayerId: widget.playerId,
                          gameCode: widget.gameCode,
                          isTimeUpMime: isTimeUpMime,
                          timeUpActiveTeam: timeUpActiveTeam,
                          activePlayerId: activePlayerId,
                        ),
                      
                      // LE JEU EN BAS
                      Expanded(
                        child: Padding(
                          padding: const EdgeInsets.all(16.0),
                          child: Column(
                            children: [
                              // MODIFICATION : Affichage des scores interactifs
                              _buildScoreHeader(context, players, gameData),

                              // MODIFICATION : Zone d'affichage de la main adverse intégrée ici
                              AnimatedSwitcher(
                                duration: const Duration(milliseconds: 300),
                                transitionBuilder:
                                    (child, animation) => SizeTransition(
                                      sizeFactor: animation,
                                      child: child,
                                    ),
                                child:
                                    _viewedOpponentId != null
                                        ? Container(
                                          key: ValueKey(_viewedOpponentId),
                                          width: double.infinity,
                                          padding: const EdgeInsets.all(12.0),
                                          margin: const EdgeInsets.only(
                                            top: 8.0,
                                            bottom: 8.0,
                                          ),
                                          decoration: BoxDecoration(
                                            color: Colors.black.withOpacity(0.4),
                                            borderRadius: BorderRadius.circular(12),
                                            border: Border.all(
                                              color: Colors.deepPurpleAccent
                                                  .withOpacity(0.5),
                                            ),
                                          ),
                                          child: Column(
                                            children: [
                                              Row(
                                                mainAxisAlignment:
                                                    MainAxisAlignment.spaceBetween,
                                                children: [
                                                  Text(
                                                    "Jeu de ${players[_viewedOpponentId]?['name']}",
                                                    style: TextStyle(
                                                      color: Colors.white70,
                                                      fontWeight: FontWeight.bold,
                                                    ),
                                                  ),
                                                  IconButton(
                                                    icon: Icon(
                                                      Icons.close,
                                                      size: 18,
                                                      color: Colors.white54,
                                                    ),
                                                    padding: EdgeInsets.zero,
                                                    constraints: BoxConstraints(),
                                                    onPressed:
                                                        () => setState(
                                                          () =>
                                                              _viewedOpponentId =
                                                                  null,
                                                        ),
                                                  ),
                                                ],
                                              ),
                                              Divider(color: Colors.white24),
                                              _buildOpponentHandView(
                                                gameData,
                                                _viewedOpponentId!,
                                              ),
                                            ],
                                          ),
                                        )
                                        : SizedBox.shrink(),
                              ),

                              SizedBox(height: 10),
                              Expanded(
                                child: _buildGameContent(context, gameData, playerId),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ],
                  ),
                );

                return scaffold;
              },
            ),
          );
        },
      ),
    );
  }

  PreferredSizeWidget? _buildTurnTimerIndicator(Map<String, dynamic> gameData) {
    bool useTimer = gameData['useTimer'] ?? true;
    if (!useTimer) return null;

    final turnStartTimeStamp = gameData['turnStartTime'] as Timestamp?;
    final roundState = gameData['roundState'];
    final currentPhase = gameData['currentPhase'];
    final loupGarouPhase = gameData['phase']; // Loup-Garou uses 'phase' field

    // Liste des états où le timer doit s'afficher
    final statesWithTimer = [
      'playing_turn', 'player_turn', 'voting', 'result', 'round_end',
      'pre-flop', 'flop', 'turn', 'river', 'hand_over',
      'clue_giving', 'turn_result',
      'answering', // Synonyme ou Banni
      'guesser_chooses_word',
      'reveal_clues',
      // Gribouillis
      'initial_writing', 'drawing', 'guessing',
      // Loup-Garou
      'nuit', 'jour_discussion', 'jour_vote',
      // Photo Roulette
      'showing_photo',
    ];

    bool shouldShow =
        statesWithTimer.contains(roundState) ||
        statesWithTimer.contains(currentPhase) ||
        (loupGarouPhase != null && statesWithTimer.contains(loupGarouPhase));

    if (turnStartTimeStamp == null ||
        gameData['gameState'] != 'playing' ||
        !shouldShow) {
      return null;
    }

    final turnStartTime = turnStartTimeStamp.toDate();

    double turnDurationSeconds =
        (gameData['turnTimerSeconds'] as num?)?.toDouble() ?? 30.0;

    if (roundState == 'result' ||
        roundState == 'round_end' ||
        roundState == 'hand_over' ||
        currentPhase == 'turn_result') {
      turnDurationSeconds =
          (gameData['resultTimerSeconds'] as num?)?.toDouble() ?? 15.0;
    }

    return PreferredSize(
      preferredSize: Size.fromHeight(20.0),
      child: StreamBuilder(
        stream: Stream.periodic(const Duration(milliseconds: 100)),
        builder: (context, snapshot) {
          final elapsedSeconds =
              DateTime.now().difference(turnStartTime).inMilliseconds / 1000.0;
          final progress =
              (turnDurationSeconds - elapsedSeconds) / turnDurationSeconds;
          final remainingSeconds =
              (turnDurationSeconds - elapsedSeconds).ceil();

          if (progress < 0) return const SizedBox.shrink();

          return Stack(
            alignment: Alignment.center,
            children: [
              LinearProgressIndicator(
                value: progress.clamp(0.0, 1.0),
                backgroundColor: Colors.grey[700],
                valueColor: AlwaysStoppedAnimation<Color>(
                  progress > 0.5
                      ? Colors.greenAccent
                      : (progress > 0.2
                          ? Colors.orangeAccent
                          : Colors.redAccent),
                ),
                minHeight: 20,
              ),
              Text(
                "$remainingSeconds",
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  shadows: [
                    Shadow(blurRadius: 2, color: Colors.black.withOpacity(0.8)),
                  ],
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildScoreHeader(
    BuildContext context,
    Map<String, dynamic> players,
    Map<String, dynamic> gameData,
  ) {
    String gameType = gameData['gameType'] ?? '';

    // Liste des jeux où voir la main adverse est pertinent
    bool canViewHands = [
      'Président',
      'Uno',
      'Zéro Pointé',
      'Poker',
    ].contains(gameType);

    // Trie les joueurs par score
    List<MapEntry<String, dynamic>> sortedPlayers =
        players.entries.toList()..sort(
          (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
        );

    // Pour Zéro Pointé, on trie par score total croissant (le plus bas gagne)
    if (gameType == 'Zéro Pointé') {
      sortedPlayers.sort((a, b) {
        int scoreA = (gameData['totalScores']?[a.key] ?? 0);
        int scoreB = (gameData['totalScores']?[b.key] ?? 0);
        return scoreA.compareTo(scoreB);
      });
    }

    return Card(
      elevation: 4,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: Padding(
        padding: const EdgeInsets.all(8.0),
        child: Container(
          width: double.infinity,
          child: Wrap(
            spacing: 8,
            runSpacing: 8,
            alignment: WrapAlignment.center,
            children:
                sortedPlayers.map((entry) {
                  String pId = entry.key;
                  String pName = entry.value['name'] ?? 'Inconnu';
                  int pScore = entry.value['score'] ?? 0;
                  bool isMe = pId == widget.playerId;
                  bool isSelected = _viewedOpponentId == pId;

                  // Info supplémentaire (ex: nombre de cartes)
                  String extraInfo = "";
                  if (gameType == 'Uno') {
                    int count =
                        (gameData['unoPlayerHands']?[pId] as List?)?.length ??
                        0;
                    extraInfo = " ($count 🎴)";
                  } else if (gameType == 'Président') {
                    int count =
                        (gameData['playerHands']?[pId] as List?)?.length ?? 0;
                    extraInfo = " ($count 🎴)";
                  } else if (gameType == 'Zéro Pointé') {
                    int totalScore = (gameData['totalScores']?[pId] ?? 0);
                    pScore = totalScore;
                    extraInfo = "";
                  }

                  return ActionChip(
                    avatar: CircleAvatar(
                      backgroundColor:
                          isMe ? Colors.deepPurpleAccent : Colors.grey[700],
                      child: Text(
                        pName.isNotEmpty ? pName[0].toUpperCase() : "?",
                        style: TextStyle(color: Colors.white, fontSize: 12),
                      ),
                    ),
                    label: Text("$pName: $pScore$extraInfo"),
                    backgroundColor:
                        isSelected ? Colors.deepPurple.withOpacity(0.5) : null,
                    side:
                        isSelected
                            ? BorderSide(
                              color: Colors.deepPurpleAccent,
                              width: 2,
                            )
                            : null,
                    onPressed:
                        (canViewHands && !isMe)
                            ? () {
                              setState(() {
                                if (_viewedOpponentId == pId) {
                                  _viewedOpponentId = null;
                                } else {
                                  _viewedOpponentId = pId;
                                }
                              });
                            }
                            : null,
                  );
                }).toList(),
          ),
        ),
      ),
    );
  }

  Widget _buildOpponentHandView(
    Map<String, dynamic> gameData,
    String opponentId,
  ) {
    final String gameType = gameData['gameType'];

    Widget buildFaceDownCard() => Container(
      width: 40,
      height: 60,
      margin: EdgeInsets.symmetric(horizontal: 2),
      decoration: BoxDecoration(
        color: Colors.indigo,
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: Colors.white24),
      ),
    );

    Widget buildZeroPointeOpponentGrid() {
      final gridData = List<Map<String, dynamic>>.from(
        gameData['playerGrids']?[opponentId] ?? [],
      );
      if (gridData.isEmpty)
        return Text("Aucune carte", style: TextStyle(color: Colors.white70));

      return Container(
        width: 200,
        child: GridView.builder(
          shrinkWrap: true,
          physics: NeverScrollableScrollPhysics(),
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 4,
            childAspectRatio: 0.7,
            mainAxisSpacing: 4,
            crossAxisSpacing: 4,
          ),
          itemCount: gridData.length,
          itemBuilder: (context, index) {
            final card = gridData[index];
            if (card['value'] == -100) {
              // Colonne éliminée : afficher une case vide transparente
              return Container(
                decoration: BoxDecoration(
                  color: Colors.black.withOpacity(0.2),
                  borderRadius: BorderRadius.circular(4),
                  border: Border.all(color: Colors.white12),
                ),
              );
            } else if (card['revealed'] == true) {
              return Card(
                color: Colors.grey[700],
                child: Center(
                  child: Text(
                    "${card['value']}",
                    style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                  ),
                ),
              );
            } else {
              return buildFaceDownCard();
            }
          },
        ),
      );
    }

    switch (gameType) {
      case 'Président':
        final hand = List<String>.from(
          gameData['playerHands']?[opponentId] ?? [],
        );
        if (hand.isEmpty)
          return Text(
            "N'a plus de cartes",
            style: TextStyle(color: Colors.white70),
          );
        return Wrap(
          spacing: 4,
          children: hand.map((_) => buildFaceDownCard()).toList(),
        );

      case 'Uno':
        final hand = List<String>.from(
          gameData['unoPlayerHands']?[opponentId] ?? [],
        );
        if (hand.isEmpty)
          return Text(
            "N'a plus de cartes",
            style: TextStyle(color: Colors.white70),
          );
        return Wrap(
          spacing: 4,
          children: hand.map((_) => buildFaceDownCard()).toList(),
        );

      case 'Poker':
        final hand = List<String>.from(
          gameData['playerData']?[opponentId]?['hand'] ?? [],
        );
        final status = gameData['playerData']?[opponentId]?['status'];
        if (gameData['phase'] == 'showdown' || status == 'all-in') {
          return Wrap(
            spacing: -15,
            children:
                hand
                    .map(
                      (card) => _buildCard(
                        card: card,
                        isSelected: false,
                        onTap: null,
                      ),
                    )
                    .toList(),
          );
        }
        return Wrap(
          spacing: 4,
          children: hand.map((_) => buildFaceDownCard()).toList(),
        );

      case 'Zéro Pointé':
        return buildZeroPointeOpponentGrid();

      default:
        return SizedBox.shrink();
    }
  }

  Widget buildFaceDownCard() => Container(
    width: 40,
    height: 60,
    margin: EdgeInsets.symmetric(horizontal: 2),
    decoration: BoxDecoration(
      color: Colors.indigo,
      borderRadius: BorderRadius.circular(4),
      border: Border.all(color: Colors.white24),
    ),
  );
  Widget _buildZeroPointeUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final gameState = gameData['gameState'];
    final players = gameData['players'] as Map<String, dynamic>;
    final isHost = gameData['hostId'] == playerId;

    // --- ÉCRAN DE FIN DE MANCHE ---
    if (roundState == 'round_end') {
      final totalScores = Map<String, dynamic>.from(
        gameData['totalScores'] ?? {},
      );
      final roundScores = Map<String, dynamic>.from(
        gameData['roundScores'] ?? {},
      );
      final roundEnderId = gameData['roundEnderId'];
      final roundEnderName = players[roundEnderId]?['name'] ?? 'Inconnu';

      List<MapEntry<String, dynamic>> sortedPlayersByTotal =
          totalScores.entries.toList()
            ..sort((a, b) => a.value.compareTo(b.value));

      if (gameState == 'gameOver') {
        final winnerName =
            players[gameData['gameWinner']]?['name'] ?? 'Inconnu';
        return Center(
          child: Card(
            child: Padding(
              padding: const EdgeInsets.all(24.0),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    "Partie Terminée !",
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  SizedBox(height: 10),
                  Text(
                    "Le gagnant est $winnerName !",
                    style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                      color: Colors.amberAccent,
                    ),
                  ),
                  SizedBox(height: 20),
                  Text(
                    "Classement Final :",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  ...sortedPlayersByTotal.map((entry) {
                    return Text(
                      "${players[entry.key]?['name']}: ${entry.value} points",
                    );
                  }),
                  SizedBox(height: 20),
                  ElevatedButton(
                    onPressed:
                        () => Navigator.of(
                          context,
                        ).popUntil((route) => route.isFirst),
                    child: Text("Retour à l'accueil"),
                  ),
                ],
              ),
            ),
          ),
        );
      }

      return Column(
        children: [
          Text(
            "Fin de la Manche !",
            style: Theme.of(context).textTheme.headlineMedium,
          ),
          Text(
            "$roundEnderName a terminé le premier.",
            style: Theme.of(context).textTheme.bodyMedium,
          ),
          SizedBox(height: 20),
          Expanded(
            child: SingleChildScrollView(
              child: Column(
                children: [
                  Text(
                    "Scores de la manche :",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  ...roundScores.entries.map((entry) {
                    return Text(
                      "${players[entry.key]?['name']}: ${entry.value} points",
                    );
                  }),
                  SizedBox(height: 20),
                  Text(
                    "Scores Totaux :",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  ...sortedPlayersByTotal.map((entry) {
                    return Text(
                      "${players[entry.key]?['name']}: ${entry.value} points",
                    );
                  }),
                ],
              ),
            ),
          ),
          SizedBox(height: 20),
          if (isHost)
            ElevatedButton(
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .startGame(
                              widget.gameCode,
                            ) // Relance une nouvelle manche
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
              child:
                  _isActionPending
                      ? CircularProgressIndicator(color: Colors.white)
                      : Text("Manche Suivante"),
            )
          else
            Text(
              "En attente de l'hôte pour la prochaine manche...",
              style: TextStyle(fontStyle: FontStyle.italic),
            ),
        ],
      );
    }

    // --- JEU ACTIF ---
    final myGrid = List<Map<String, dynamic>>.from(
      gameData['playerGrids'][playerId] ?? [],
    );
    final discardPile = List<int>.from(gameData['discardPile'] ?? []);
    final int? drawnCard = gameData['drawnCard'];
    final bool isMyTurn = gameData['currentPlayerId'] == playerId;

    // --- Phase Initiale : Révéler 2 cartes ---
    if (roundState == 'revealing_initial') {
      int revealedCount = gameData['revealedInitialCardsCount'][playerId] ?? 0;
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
            "Révélez vos 2 premières cartes",
            style: Theme.of(context).textTheme.headlineSmall,
          ),
          Text(
            "$revealedCount / 2 cartes révélées",
            style: Theme.of(context).textTheme.bodyMedium,
          ),
          SizedBox(height: 20),
          Expanded(
            child: _buildZeroPointeGrid(myGrid, (index) {
              if (revealedCount < 2) {
                _firebaseService.revealInitialZeroPointeCard(
                  widget.gameCode,
                  playerId,
                  index,
                );
              }
            }),
          ),
        ],
      );
    }

    // --- Logique d'Instructions et Sélection ---
    String instructions =
        isMyTurn
            ? "C'est votre tour !"
            : "Au tour de ${players[gameData['currentPlayerId']]['name']}";
    Color instructionColor = Colors.white;

    if (isMyTurn) {
      if (drawnCard != null) {
        // Le joueur a pioché une carte face cachée
        if (_zeroPointeAction == 'use_drawn') {
          instructions =
              "Touchez une carte de votre grille pour la REMPLACER par le $drawnCard.";
          instructionColor = Colors.greenAccent;
        } else if (_zeroPointeAction == 'discard_drawn') {
          instructions =
              "Touchez une carte CACHÉE de votre grille pour la RÉVÉLER.";
          instructionColor = Colors.orangeAccent;
        } else {
          instructions = "Que voulez-vous faire avec le $drawnCard ?";
        }
      } else {
        // Le joueur n'a pas encore agi
        if (_zeroPointeAction == 'take_discard') {
          instructions =
              "Touchez une carte de votre grille pour la REMPLACER par la défausse (${discardPile.isNotEmpty ? discardPile.last : 0}).";
          instructionColor = Colors.amberAccent;
        } else {
          instructions = "Prenez la défausse ou piochez une carte.";
        }
      }
    }

    return Column(
      children: [
        // Zone d'instruction
        Container(
          width: double.infinity,
          padding: EdgeInsets.all(12),
          margin: EdgeInsets.only(bottom: 10),
          decoration: BoxDecoration(
            color: Colors.grey[900],
            borderRadius: BorderRadius.circular(8),
            border: Border.all(color: instructionColor.withOpacity(0.5)),
          ),
          child: Column(
            children: [
              Text(
                instructions,
                style: Theme.of(context).textTheme.titleMedium?.copyWith(
                  color: instructionColor,
                  fontWeight: FontWeight.bold,
                ),
                textAlign: TextAlign.center,
              ),
              if (_zeroPointeAction != null && isMyTurn)
                TextButton.icon(
                  icon: Icon(Icons.cancel, size: 16, color: Colors.redAccent),
                  label: Text(
                    "Annuler la sélection",
                    style: TextStyle(color: Colors.redAccent),
                  ),
                  onPressed: () => setState(() => _zeroPointeAction = null),
                ),
            ],
          ),
        ),

        // --- Zone des Piles (Défausse / Pioche) ---
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // PILE DÉFAUSSE
            Column(
              children: [
                GestureDetector(
                  onTap:
                      (isMyTurn &&
                              roundState == 'player_turn' &&
                              drawnCard == null)
                          ? () =>
                              setState(() => _zeroPointeAction = 'take_discard')
                          : null,
                  child: Container(
                    decoration: BoxDecoration(
                      boxShadow:
                          _zeroPointeAction == 'take_discard'
                              ? [BoxShadow(color: Colors.amber, blurRadius: 10)]
                              : [],
                    ),
                    child: Card(
                      color: Colors.white,
                      child: Container(
                        width: 60,
                        height: 90,
                        child: Center(
                          child: Text(
                            "${discardPile.isNotEmpty ? discardPile.last : ' '}",
                            style: TextStyle(
                              fontSize: 24,
                              color: Colors.black,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
                Text("Défausse", style: Theme.of(context).textTheme.bodySmall),
              ],
            ),

            // PILE PIOCHE
            Column(
              children: [
                GestureDetector(
                  onTap:
                      (isMyTurn &&
                              roundState == 'player_turn' &&
                              drawnCard == null)
                          ? () => _firebaseService.drawFromDeckZeroPointe(
                            widget.gameCode,
                            playerId,
                          )
                          : null,
                  child: Card(
                    color: Colors.deepPurple,
                    child: Container(
                      width: 60,
                      height: 90,
                      child: Center(
                        child: Icon(Icons.style, color: Colors.white70),
                      ),
                    ),
                  ),
                ),
                Text("Pioche", style: Theme.of(context).textTheme.bodySmall),
              ],
            ),

            // CARTE PIOCHÉE (Visible uniquement si action faite)
            if (drawnCard != null)
              Column(
                children: [
                  Card(
                    color: Colors.white,
                    child: Container(
                      width: 60,
                      height: 90,
                      child: Center(
                        child: Text(
                          "$drawnCard",
                          style: TextStyle(
                            fontSize: 24,
                            color: Colors.green[800],
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),
                    ),
                  ),
                  Text(
                    "Piochée",
                    style: Theme.of(
                      context,
                    ).textTheme.bodySmall?.copyWith(color: Colors.greenAccent),
                  ),
                ],
              ),
          ],
        ),

        // --- Boutons d'action si carte piochée ---
        if (drawnCard != null && isMyTurn)
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 10.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _zeroPointeAction == 'use_drawn'
                            ? Colors.green
                            : Colors.grey[800],
                    foregroundColor: Colors.white,
                  ),
                  onPressed:
                      () => setState(() => _zeroPointeAction = 'use_drawn'),
                  child: Text("Garder & Remplacer"),
                ),
                SizedBox(width: 10),
                ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor:
                        _zeroPointeAction == 'discard_drawn'
                            ? Colors.orange
                            : Colors.grey[800],
                    foregroundColor: Colors.white,
                  ),
                  onPressed:
                      () => setState(() => _zeroPointeAction = 'discard_drawn'),
                  child: Text("Jeter & Révéler"),
                ),
              ],
            ),
          ),

        SizedBox(height: 10),

        // --- Grille du Joueur ---
        Expanded(
          child: _buildZeroPointeGrid(myGrid, (index) async {
            if (!isMyTurn || _isActionPending) return;

            // LOGIQUE DE CLICK SUR LA GRILLE
            if (_zeroPointeAction == 'take_discard') {
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .takeDiscardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            } else if (_zeroPointeAction == 'use_drawn') {
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .useDrawnCardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            } else if (_zeroPointeAction == 'discard_drawn') {
              // Vérification : on ne peut révéler qu'une carte cachée
              if (myGrid[index]['revealed'] == true) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(
                    content: Text(
                      "Cette carte est déjà révélée ! Choisissez une carte face cachée.",
                    ),
                  ),
                );
                return;
              }
              setState(() {
                _isActionPending = true;
                _zeroPointeAction = null;
              });
              await _firebaseService
                  .discardDrawnCardZeroPointe(widget.gameCode, playerId, index)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            }
          }),
        ),
      ],
    );
  }

  Widget _buildGribouillisUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'];
    final List<String> submittedPlayers = List<String>.from(
      gameData['submittedPlayers'] ?? [],
    );
    final Map<String, dynamic> players = Map.from(gameData['players'] ?? {});
    final int playerCount = players.length;
    final isHost = gameData['hostId'] == playerId;
    final String gribouillisMode = gameData['gribouillisMode'] ?? 'Normal';
    final bool ajouter1 = gameData['gribouillisSettings']?['ajouter1'] ?? false;
    final int currentStep = gameData['currentStep'];
    final Map<String, dynamic> albums = Map.from(gameData['albums'] ?? {});

    if (roundState == 'results') {
      final List<String> playerOrder = List<String>.from(
        gameData['playerOrder'] ?? [],
      );
      if (playerOrder.isEmpty)
        return Center(child: Text("Aucun album à afficher."));

      final int serverPageIndex = gameData['gribouillisResultPageIndex'] ?? 0;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_gribouillisPageController!.hasClients &&
            _gribouillisPageController!.page?.round() != serverPageIndex) {
          _gribouillisPageController!.animateToPage(
            serverPageIndex,
            duration: Duration(milliseconds: 400),
            curve: Curves.easeInOut,
          );
        }
      });

      return Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              "Vernissage !",
              style: Theme.of(context).textTheme.headlineMedium,
            ),
          ),
          Expanded(
            child: PageView.builder(
              controller: _gribouillisPageController,
              itemCount: playerOrder.length,
              physics: BouncingScrollPhysics(),
              onPageChanged: (page) {
                if (isHost) {
                  _firebaseService.setGribouillisResultPage(
                    widget.gameCode,
                    page,
                  );
                }
              },
              itemBuilder: (context, pageIndex) {
                final ownerId = playerOrder[pageIndex];
                final ownerName = players[ownerId]?['name'] ?? 'Inconnu';
                final albumSteps = List<Map<String, dynamic>>.from(
                  albums[ownerId] ?? [],
                );

                return Container(
                  margin: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                  decoration: BoxDecoration(
                    color: Colors.white, // Fond papier
                    borderRadius: BorderRadius.circular(16),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black54,
                        blurRadius: 15,
                        offset: Offset(0, 10),
                      ),
                    ],
                  ),
                  child: Column(
                    children: [
                      // En-tête Album
                      Container(
                        width: double.infinity,
                        padding: EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: Colors.amber[100],
                          borderRadius: BorderRadius.vertical(
                            top: Radius.circular(16),
                          ),
                        ),
                        child: Text(
                          "Album de $ownerName",
                          style: TextStyle(
                            color: Colors.brown[800],
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                            fontFamily: 'Cursive',
                          ),
                          textAlign: TextAlign.center,
                        ),
                      ),
                      Expanded(
                        child: ListView.builder(
                          itemCount: albumSteps.length,
                          padding: EdgeInsets.zero,
                          itemBuilder: (context, index) {
                            final step = albumSteps[index];
                            final authorName = step['authorName'] ?? '...';
                            final isDrawing = step['type'] == 'drawing';

                            return Container(
                              padding: EdgeInsets.all(16),
                              decoration: BoxDecoration(
                                border: Border(
                                  bottom: BorderSide(color: Colors.grey[300]!),
                                ),
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      Icon(
                                        isDrawing ? Icons.brush : Icons.edit,
                                        size: 16,
                                        color: Colors.grey,
                                      ),
                                      SizedBox(width: 5),
                                      Text(
                                        index == 0
                                            ? "Départ par $authorName"
                                            : (isDrawing
                                                ? "Dessiné par $authorName"
                                                : "Deviné par $authorName"),
                                        style: TextStyle(
                                          color: Colors.grey[600],
                                          fontSize: 12,
                                          fontStyle: FontStyle.italic,
                                        ),
                                      ),
                                    ],
                                  ),
                                  SizedBox(height: 8),
                                  if (isDrawing)
                                    Center(
                                      child: Container(
                                        height: 180,
                                        decoration: BoxDecoration(
                                          border: Border.all(
                                            color: Colors.grey[200]!,
                                          ),
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                        ),
                                        child: ClipRRect(
                                          borderRadius: BorderRadius.circular(
                                            8,
                                          ),
                                          child:
                                              step['content'] != null
                                                  ? Image.memory(
                                                    base64Decode(
                                                      step['content'],
                                                    ),
                                                    fit: BoxFit.contain,
                                                  )
                                                  : Center(
                                                    child: Icon(
                                                      Icons.broken_image,
                                                      color: Colors.grey,
                                                    ),
                                                  ),
                                        ),
                                      ),
                                    )
                                  else
                                    Center(
                                      child: Text(
                                        '“ ${step['content']} ”',
                                        style: TextStyle(
                                          fontSize: 20,
                                          color: Colors.black87,
                                          fontWeight: FontWeight.w500,
                                          fontFamily: 'Courier',
                                        ),
                                        textAlign: TextAlign.center,
                                      ),
                                    ),
                                ],
                              ),
                            );
                          },
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),

          if (isHost)
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ElevatedButton.icon(
                  onPressed: () {
                    final int newIndex =
                        (serverPageIndex - 1 + playerOrder.length) %
                        playerOrder.length;
                    _firebaseService.setGribouillisResultPage(
                      widget.gameCode,
                      newIndex,
                    );
                  },
                  icon: Icon(Icons.navigate_before),
                  label: Text("Préc."),
                ),
                Text(
                  "Album ${serverPageIndex + 1} / ${playerOrder.length}",
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
                ElevatedButton.icon(
                  onPressed: () {
                    final int newIndex =
                        (serverPageIndex + 1) % playerOrder.length;
                    _firebaseService.setGribouillisResultPage(
                      widget.gameCode,
                      newIndex,
                    );
                  },
                  icon: Icon(Icons.navigate_next),
                  label: Text("Suiv."),
                ),
              ],
            ),
          SizedBox(height: 8),
          if (isHost)
            ElevatedButton(
              onPressed: () => _firebaseService.startGame(widget.gameCode),
              child: Text("Rejouer"),
            ),
        ],
      );
    }

    if (submittedPlayers.contains(playerId)) {
      return _buildWaitingWidget(
        "En attente des autres joueurs...",
        players,
        submittedPlayers.length,
        playerCount,
      );
    }

    final List<String> playerOrder = List<String>.from(gameData['playerOrder']);
    final int myIndex = playerOrder.indexOf(playerId);
    if (myIndex == -1) return Center(child: CircularProgressIndicator());

    Map<String, dynamic>? stepToProcess;
    if (currentStep > 0) {
      String sourceAlbumOwnerId;

      if ((gribouillisMode == 'Complément' && ajouter1) ||
          gribouillisMode == 'Brise-Glace') {
        sourceAlbumOwnerId = playerOrder[(myIndex + currentStep) % playerCount];
      } else {
        sourceAlbumOwnerId =
            playerOrder[(myIndex - currentStep + (playerCount * currentStep)) %
                playerCount];
      }
      List<dynamic> sourceAlbum = List.from(
        gameData['albums'][sourceAlbumOwnerId] ?? [],
      );
      if (sourceAlbum.isNotEmpty) {
        if ((gribouillisMode == 'Complément' && ajouter1) ||
            gribouillisMode == 'Brise-Glace') {
          stepToProcess = Map<String, dynamic>.from(sourceAlbum[0]);
        } else {
          stepToProcess = Map<String, dynamic>.from(sourceAlbum.last);
        }
      }
    }

    if (roundState == 'initial_writing' || roundState == 'guessing') {
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          if (stepToProcess != null && stepToProcess['type'] == 'drawing')
            Expanded(
              child: Column(
                children: [
                  Text(
                    "Devine ce que représente ce dessin :",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                  Expanded(
                    child: Container(
                      margin: EdgeInsets.symmetric(vertical: 10),
                      decoration: BoxDecoration(
                        color: Colors.white,
                        borderRadius: BorderRadius.circular(12),
                      ),
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(11),
                        child:
                            stepToProcess['content'] != null
                                ? Image.memory(
                                  base64Decode(stepToProcess['content']),
                                  fit: BoxFit.contain,
                                )
                                : Center(
                                  child: Icon(
                                    Icons.broken_image,
                                    color: Colors.grey,
                                  ),
                                ),
                      ),
                    ),
                  ),
                ],
              ),
            )
          else
            Text(
              gribouillisMode == 'Brise-Glace'
                  ? "Écris un thème ou une phrase !"
                  : "Imagine une phrase !",
              style: Theme.of(context).textTheme.headlineSmall,
              textAlign: TextAlign.center,
            ),
          SizedBox(height: 20),
          TextField(
            controller: _answerController,
            decoration: InputDecoration(labelText: "Écris ta phrase..."),
            maxLines: 2,
          ),
          SizedBox(height: 20),
          ElevatedButton(
            onPressed: () {
              if (_answerController.text.trim().isNotEmpty) {
                _firebaseService.submitGribouillisStep(
                  widget.gameCode,
                  playerId,
                  'text',
                  _answerController.text.trim(),
                );
                _answerController.clear();
              }
            },
            child: Text("Valider"),
          ),
        ],
      );
    }

    if (roundState == 'initial_drawing' || roundState == 'drawing') {
      String promptText;
      if (stepToProcess != null && stepToProcess['type'] == 'text') {
        promptText = 'Dessine cette phrase :\n"${stepToProcess['content']}"';
      } else if (gribouillisMode == 'Complément') {
        promptText = "Complète ce dessin !";
      } else {
        promptText = "Commence par un dessin !";
      }

      final String? backgroundDrawingData =
          (gribouillisMode == 'Complément' &&
                  stepToProcess != null &&
                  stepToProcess['type'] == 'drawing')
              ? stepToProcess['content'] as String?
              : null;

      return Column(
        children: [
          Expanded(
            child: Center(
              child: Text(
                promptText,
                style: Theme.of(context).textTheme.headlineSmall,
                textAlign: TextAlign.center,
              ),
            ),
          ),
          ElevatedButton(
            onPressed: () async {
              final drawingResult = await Navigator.push<Map<String, dynamic>>(
                context,
                MaterialPageRoute(
                  builder:
                      (_) => DrawingScreen(
                        prompt: promptText,
                        backgroundDrawingData: backgroundDrawingData,
                      ),
                ),
              );
              if (drawingResult != null && mounted) {
                _firebaseService.submitGribouillisStep(
                  widget.gameCode,
                  playerId,
                  'drawing',
                  drawingResult['drawing'] as String,
                );
              }
            },
            child: Text("Ouvrir la zone de dessin"),
          ),
        ],
      );
    }

    return Center(child: Text("État Gribouillis inconnu : $roundState"));
  }

  Widget _buildGameContent(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final gameType = gameData['gameType'];

    if (gameType == 'Infiltré & Mr. White') {
      return _buildUndercoverGameUI(context, gameData, playerId);
    }

    if (gameType == 'Photo Roulette') {
      return _buildPhotoRouletteUI(context, gameData, playerId);
    }
    if (gameType == 'Gribouillis') {
      return _buildGribouillisUI(context, gameData, playerId);
    }
    if (gameType == 'Zéro Pointé') {
      return _buildZeroPointeUI(context, gameData, playerId);
    }
    if (gameType == 'Poker') {
      return _buildPokerUI(context, gameData, playerId);
    }
    if (gameType == 'Dobble') {
      return _buildDobbleUI(context, gameData, playerId);
    }
    if (gameType == 'Skull' &&
        (gameData['roundState'] == 'placing' ||
            gameData['roundState'] == 'bidding')) {
      return _buildSkullUI(context, gameData, playerId);
    }
    if (gameType == 'Loup-Garou') {
      return _buildLoupGarouUI(context, gameData, playerId);
    }
    if (gameType == 'Uno') {
      return _buildUnoUI(context, gameData, playerId);
    }
    if (gameType == 'Codenames') {
      return _buildCodenamesUI(context, gameData, playerId);
    } else if (gameType == 'Time\'s Up') {
      return _buildTimesUpUI(context, gameData, playerId);
    } else if (gameType == 'Petit Bac') {
      return _buildPetitBacUI(context, gameData, playerId);
    } else if (gameType == 'Président') {
      return _buildPresidentUI(context, gameData, playerId);
    } else if (gameType == 'Pictionary') {
      return _buildPictionaryUI(context, gameData, playerId);
    } else if (gameType == 'Just One') {
      return _buildJustOneUI(context, gameData, playerId);
    } else if (gameType == 'Le Jeu des Catégories' ||
        gameType == 'La Patate Chaude') {
      return _buildHotPotatoUI(context, gameData, playerId);
    }

    final roundState = gameData['roundState'];
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 500),
      transitionBuilder: (Widget child, Animation<double> animation) {
        return FadeTransition(opacity: animation, child: child);
      },
      child: Container(
        key: ValueKey<String>(roundState ?? 'initial'),
        child: _getWidgetForRoundState(context, gameData, playerId),
      ),
    );
  }

  Future<void> _processZeroPointeTurnEnd(
    Transaction transaction,
    DocumentReference gameRef,
    Map<String, dynamic> gameData,
    String playerId,
  ) async {
    var grids = Map<String, dynamic>.from(gameData['playerGrids']);
    var playerGrid = List<Map<String, dynamic>>.from(grids[playerId]);
    final players = gameData['players'] as Map<String, dynamic>;

    for (int col = 0; col < 4; col++) {
      int card1Index = col;
      int card2Index = col + 4;
      int card3Index = col + 8;
      if (playerGrid[card1Index]['value'] != -100 &&
          playerGrid[card1Index]['revealed'] &&
          playerGrid[card2Index]['revealed'] &&
          playerGrid[card3Index]['revealed'] &&
          playerGrid[card1Index]['value'] == playerGrid[card2Index]['value'] &&
          playerGrid[card1Index]['value'] == playerGrid[card3Index]['value']) {
        playerGrid[card1Index]['value'] = -100;
        playerGrid[card2Index]['value'] = -100;
        playerGrid[card3Index]['value'] = -100;
      }
    }
    grids[playerId] = playerGrid;

    bool allCardsRevealed = playerGrid.every(
      (card) => card['revealed'] == true || card['value'] == -100,
    );
    if (allCardsRevealed) {
      Map<String, int> roundScores = {};
      int lowestScoreInRound = 999;

      players.keys.forEach((pId) {
        List<Map<String, dynamic>> currentGrid =
            (grids[pId] as List)
                .map((card) => Map<String, dynamic>.from(card as Map))
                .toList();
        for (var card in currentGrid) {
          card['revealed'] = true;
        }
        grids[pId] = currentGrid;
      });

      players.keys.forEach((pId) {
        int score = 0;
        (grids[pId] as List).forEach((card) {
          if ((card as Map)['value'] != -100) {
            score += card['value'] as int;
          }
        });
        roundScores[pId] = score;
        if (score < lowestScoreInRound) {
          lowestScoreInRound = score;
        }
      });

      final roundEnderId = playerId;
      if ((roundScores[roundEnderId] ?? 0) > lowestScoreInRound) {
        roundScores[roundEnderId] = (roundScores[roundEnderId]! + 10);
      }

      var totalScores = Map<String, dynamic>.from(
        gameData['totalScores'] ?? {},
      );
      roundScores.forEach((pId, score) {
        totalScores[pId] = (totalScores[pId] ?? 0) + score;
      });

      Map<String, dynamic> updates = {
        'roundState': 'round_end',
        'roundEnderId': roundEnderId,
        'playerGrids': grids,
        'roundScores': roundScores,
        'totalScores': totalScores,
        'gameLog': FieldValue.arrayUnion([
          "${players[playerId]['name']} a retourné toutes ses cartes ! Fin de la manche.",
        ]),
        'turnStartTime': FieldValue.serverTimestamp(),
      };

      bool isGameOver = totalScores.values.any(
        (score) => score >= (gameData['targetScore'] ?? 100),
      );

      if (isGameOver) {
        String? gameWinnerId;
        int finalLowestScore = 9999;
        totalScores.forEach((pId, score) {
          if (score < finalLowestScore) {
            finalLowestScore = score;
            gameWinnerId = pId;
          }
        });
        updates.addAll({
          'gameState': 'gameOver',
          'gameWinner': gameWinnerId,
          'gameEndReason':
              gameWinnerId != null
                  ? "${players[gameWinnerId]?['name'] ?? 'Joueur'} gagne avec le score le plus bas !"
                  : "Fin de la partie !",
        });
      }

      transaction.update(gameRef, updates);
    } else {
      var playerOrder = List<String>.from(gameData['playerOrder']);
      int currentIndex = playerOrder.indexOf(playerId);
      int nextIndex = (currentIndex + 1) % playerOrder.length;
      transaction.update(gameRef, {
        'currentPlayerId': playerOrder[nextIndex],
        'roundState': 'player_turn',
        'playerGrids': grids,
        'turnStartTime': FieldValue.serverTimestamp(),
      });
    }
  }

  Widget _buildZeroPointeGrid(
    List<Map<String, dynamic>> gridData,
    Function(int)? onCardTap,
  ) {
    return GridView.builder(
      padding: EdgeInsets.all(16),
      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 4,
        mainAxisSpacing: 8,
        crossAxisSpacing: 8,
        childAspectRatio: 0.7,
      ),
      itemCount: gridData.length,
      itemBuilder: (context, index) {
        final card = gridData[index];
        bool isRevealed = card['revealed'];
        int value = card['value'];

        if (value == -100) {
          // Carte défaussée
          return Container(color: Colors.black.withOpacity(0.2));
        }

        return GestureDetector(
          onTap: onCardTap != null ? () => onCardTap(index) : null,
          child: Card(
            color: isRevealed ? Colors.grey[700] : Colors.indigo,
            child: Center(
              child: Text(
                isRevealed ? "$value" : "?",
                style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold),
              ),
            ),
          ),
        );
      },
    );
  }

  void _showGridSelectionDialog(
    BuildContext context, // Il est bon de passer le context pour le showDialog
    String title,
    List<Map<String, dynamic>> gridData, // <-- NOUVEAU PARAMÈTRE
    Function(int) onConfirm,
  ) {
    final String playerId = widget.playerId;
    showDialog(
      context: context,
      builder:
          (dContext) => AlertDialog(
            title: Text(title),
            content: Container(
              width: double.maxFinite,
              height: 300,

              child: _buildZeroPointeGrid(gridData, (index) {
                onConfirm(index);
                Navigator.of(dContext).pop();
              }),
            ),
          ),
    );
  }

