  Widget _buildPokerActionButtons(
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    var myData = gameData['playerData'][playerId];
    int currentBet = gameData['currentBet'];
    bool canCheck = myData['currentBet'] == currentBet;

    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: [
        ElevatedButton(
          onPressed:
              () => _firebaseService.pokerAction(
                widget.gameCode,
                playerId,
                'fold',
              ),
          child: Text("Se Coucher"),
        ),
        if (canCheck)
          ElevatedButton(
            onPressed:
                () => _firebaseService.pokerAction(
                  widget.gameCode,
                  playerId,
                  'check',
                ),
            child: Text("Checker"),
          ),
        if (!canCheck)
          ElevatedButton(
            onPressed:
                () => _firebaseService.pokerAction(
                  widget.gameCode,
                  playerId,
                  'call',
                ),
            child: Text("Suivre ($currentBet)"),
          ),
        ElevatedButton(
          onPressed: () {
            _showRaiseDialog(gameData, playerId);
          },
          child: Text("Relancer"),
        ),
      ],
    );
  }

  void _showRaiseDialog(Map<String, dynamic> gameData, String playerId) {
    final playerData = gameData['playerData'][playerId];
    final int myChips = playerData['chips'];
    final int myCurrentBet = playerData['currentBet'];
    final int currentBet = gameData['currentBet'];
    final int bigBlind = gameData['bigBlind'] ?? 20;
    final int pot = gameData['pot'] ?? 0;

    int minRaise = currentBet + bigBlind;
    if (minRaise < currentBet * 2 && myChips + myCurrentBet > currentBet * 2) {
      minRaise = currentBet * 2;
    }

    final int maxRaise = myChips + myCurrentBet;

    if (minRaise >= maxRaise) {
      _firebaseService.pokerAction(
        widget.gameCode,
        playerId,
        'raise',
        amount: maxRaise,
      );
      return;
    }

    double raiseAmount = minRaise.toDouble();

    showDialog(
      context: context,
      builder: (context) {
        return StatefulBuilder(
          builder: (context, setStateDialog) {
            return AlertDialog(
              title: Text("Choisir le montant de la relance"),
              content: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    raiseAmount.toInt().toString(),
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                  Slider(
                    value: raiseAmount,
                    min: minRaise.toDouble(),
                    max: maxRaise.toDouble(),
                    label: raiseAmount.toInt().toString(),
                    onChanged: (value) {
                      setStateDialog(() {
                        raiseAmount = value.roundToDouble();
                      });
                    },
                  ),
                  SizedBox(height: 10),
                  Wrap(
                    spacing: 8,
                    alignment: WrapAlignment.center,
                    children: [
                      if (currentBet * 2 <= maxRaise)
                        ActionChip(
                          label: Text("x2"),
                          onPressed:
                              () => setStateDialog(
                                () => raiseAmount = (currentBet * 2).toDouble(),
                              ),
                        ),
                      if (pot <= maxRaise)
                        ActionChip(
                          label: Text("Pot"),
                          onPressed:
                              () => setStateDialog(
                                () => raiseAmount = pot.toDouble(),
                              ),
                        ),
                      ActionChip(
                        label: Text("All-in"),
                        onPressed:
                            () => setStateDialog(
                              () => raiseAmount = maxRaise.toDouble(),
                            ),
                      ),
                    ],
                  ),
                ],
              ),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(context).pop(),
                  child: Text("Annuler"),
                ),
                ElevatedButton(
                  onPressed: () {
                    Navigator.of(context).pop();
                    _firebaseService.pokerAction(
                      widget.gameCode,
                      playerId,
                      'raise',
                      amount: raiseAmount.toInt(),
                    );
                  },
                  child: Text("Relancer ${raiseAmount.toInt()}"),
                ),
              ],
            );
          },
        );
      },
    );
  }

  Widget _buildUnoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // --- Récupération des données (Identique à votre logique) ---
    final String gameState = gameData['gameState'];
    final List<String> playerOrder = List<String>.from(
      gameData['unoPlayerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['unoCurrentPlayerIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentPlayerIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final List<String> myHand = List<String>.from(
      gameData['unoPlayerHands']?[playerId] ?? [],
    );
    final List<String> discardPile = List<String>.from(
      gameData['unoDiscardPile'] ?? [],
    );
    final String topCard = discardPile.isNotEmpty ? discardPile.last : 'red-0';
    final int pendingDraw = gameData['unoPendingDraw'] ?? 0;
    final String? wildColorChosen = gameData['unoWildColorChosen'];
    final bool isHost = gameData['hostId'] == playerId;
    final Map<String, dynamic> players = gameData['players'] ?? {};
    _unoDrawActionDone = gameData['unoDrawActionDone'] ?? false;

    // --- Gestion Game Over ---
    if (gameState == 'gameOver') {
      String winnerName =
          players[gameData['gameWinner']]?['name'] ?? 'Quelqu\'un';
      String reason = gameData['gameEndReason'] ?? 'La partie est terminée.';
      return Center(
        child: Card(
          elevation: 10,
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(Icons.emoji_events, size: 60, color: Colors.amber),
                SizedBox(height: 10),
                Text(
                  "Victoire !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(reason, textAlign: TextAlign.center),
                SizedBox(height: 20),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () async {
                              setState(() => _isActionPending = true);
                              await _firebaseService
                                  .nextRound(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child: Text("Manche Suivante"),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    Color currentColor = _mapUnoColorToFlutterColor(
      wildColorChosen ?? GameData.getUnoCardColor(topCard),
    );

    // --- CONSTRUCTION DE L'INTERFACE ---
    return Column(
      children: [
        // 1. STATUS BAR (Qui joue ?)
        _buildUnoTurnStatus(
          context,
          gameData,
          isMyTurn,
          currentPlayerId,
          pendingDraw,
          wildColorChosen,
          currentColor,
        ),

        Spacer(), // Espace flexible
        // 2. TABLE DE JEU (Pioche & Défausse)
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // PIOCHE (Deck)
            GestureDetector(
              onTap:
                  isMyTurn &&
                          pendingDraw == 0 &&
                          !_unoDrawActionDone &&
                          !_isActionPending
                      ? () => _onUnoDrawTapped()
                      : null,
              child: Container(
                width: 80,
                height: 120,
                decoration: BoxDecoration(
                  color: Colors.black87, // Dos de carte
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(color: Colors.white24, width: 2),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black54,
                      blurRadius: 8,
                      offset: Offset(4, 4),
                    ),
                  ],
                ),
                child: Center(
                  child: Icon(Icons.style, color: Colors.redAccent, size: 40),
                ),
              ),
            ),

            SizedBox(width: 40), // Espace entre les tas
            // DÉFAUSSE (Tas en désordre)
            Container(
              width: 100,
              height: 130,
              child: Stack(
                alignment: Alignment.center,
                children: [
                  // Fausses cartes en dessous pour l'effet de pile
                  if (discardPile.length > 2)
                    Transform.rotate(
                      angle: -0.1,
                      child: _buildCard(
                        card: discardPile[discardPile.length - 3],
                        isSelected: false,
                      ),
                    ),
                  if (discardPile.length > 1)
                    Transform.rotate(
                      angle: 0.15,
                      child: _buildCard(
                        card: discardPile[discardPile.length - 2],
                        isSelected: false,
                      ),
                    ),

                  // Carte du dessus (Active)
                  _buildCard(
                    card: topCard,
                    isSelected: false,
                    scale: 1.2, // La carte active est plus grosse
                    // Si c'est un joker, on peut visuellement montrer la couleur choisie via un glow
                  ),

                  // Indicateur de couleur choisie pour Joker
                  if (wildColorChosen != null)
                    Positioned(
                      top: 0,
                      right: 0,
                      child: Container(
                        padding: EdgeInsets.all(4),
                        decoration: BoxDecoration(
                          color: currentColor,
                          shape: BoxShape.circle,
                          border: Border.all(color: Colors.white),
                        ),
                        child: Icon(
                          Icons.color_lens,
                          size: 16,
                          color: Colors.white,
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ],
        ),

        Spacer(),

        // 3. MAIN DU JOUEUR (ÉVENTAIL)
        if (myHand.isEmpty)
          Text(
            "Gagné !",
            style: TextStyle(
              fontSize: 30,
              fontWeight: FontWeight.bold,
              color: Colors.greenAccent,
            ),
          )
        else
          _buildHandFan(
            cards: myHand,
            isSelectedPredicate:
                (c) => false, // Au Uno, on joue direct, pas de présélection
            onCardTap: (card) => _onUnoCardTapped(card),
          ),

        SizedBox(height: 20),

        // 4. BOUTONS D'ACTION
        _buildUnoActionButtons(
          context,
          gameData,
          playerId,
          isMyTurn,
          myHand,
          pendingDraw,
        ),
      ],
    );
  }

