  Widget _buildDobbleResultUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    String? winnerId,
    String? commonSymbol,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'],
    );
    final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
    final isHost = gameData['hostId'] == playerId;
    final bool iAmWinner = winnerId == playerId;

    return Column(
      key: ValueKey('result_dobble_$winnerId'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(
          iAmWinner ? Icons.check_circle : Icons.info,
          color: iAmWinner ? Colors.greenAccent : Colors.amber,
          size: 60,
        ),
        SizedBox(height: 10),
        Text(
          "$winnerName a trouvé le symbole !",
          style: Theme.of(context).textTheme.headlineSmall?.copyWith(
            color: iAmWinner ? Colors.greenAccent : Colors.amberAccent,
          ),
        ),
        Text(
          "Le symbole était :",
          style: Theme.of(context).textTheme.bodyMedium,
        ),
        Text(commonSymbol ?? "?", style: TextStyle(fontSize: 40)),
        SizedBox(height: 30),
        if (isHost)
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () {
                      setState(() => _isActionPending = true);
                      _firebaseService
                          .nextDobbleRound(widget.gameCode)
                          .whenComplete(() {
                            if (mounted)
                              setState(() => _isActionPending = false);
                          });
                    },
            child:
                _isActionPending
                    ? CircularProgressIndicator(color: Colors.white)
                    : Text("Tour Suivant"),
          )
        else
          Text(
            "En attente de l'hôte...",
            style: TextStyle(fontStyle: FontStyle.italic),
          ),
      ],
    );
  }

  void _onSymbolTap(String symbol) {
    // 1. Si l'interface est bloquée, on ne fait rien (ou on affiche un rappel)
    if (_isDobbleBlocked) {
      ScaffoldMessenger.of(context).clearSnackBars();
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "PÉNALITÉ ! Attendez $_dobbleBlockCountdown secondes.",
            textAlign: TextAlign.center,
          ),
          backgroundColor: Colors.red[900],
          duration: Duration(milliseconds: 500),
        ),
      );
      return;
    }

    if (_isActionPending) return;
    setState(() => _isActionPending = true);

    final String playerId = widget.playerId;

    _firebaseService
        .submitDobbleGuess(widget.gameCode, playerId, symbol)
        .then((_) {
          // Succès : On réinitialise le compteur d'erreur si on trouve le bon symbole
          _lastDobbleErrorTime = null;
        })
        .catchError((e) {
          // --- LOGIQUE DE PÉNALITÉ ---
          final now = DateTime.now();

          // Si on a déjà fait une erreur il y a moins de 3 secondes
          if (_lastDobbleErrorTime != null &&
              now.difference(_lastDobbleErrorTime!).inSeconds < 3) {
            _triggerDobblePenalty(); // DÉCLENCHER LE BLOCAGE
          } else {
            // Sinon, on enregistre l'heure de cette première erreur
            _lastDobbleErrorTime = now;
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  "Mauvais symbole ! Attention, une 2ème erreur bloque le jeu !",
                ),
                backgroundColor: Colors.orange,
                duration: Duration(seconds: 1),
              ),
            );
          }
        })
        .whenComplete(() {
          if (mounted) setState(() => _isActionPending = false);
        });
  }

  // Nouvelle fonction pour activer le blocage
  void _triggerDobblePenalty() {
    setState(() {
      _isDobbleBlocked = true;
      _dobbleBlockCountdown = 10; // 10 secondes de punition
      _lastDobbleErrorTime = null; // Reset pour la prochaine fois
    });

    // Lancer le timer de déblocage
    _dobblePenaltyTimer?.cancel();
    _dobblePenaltyTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      setState(() {
        if (_dobbleBlockCountdown > 0) {
          _dobbleBlockCountdown--;
        } else {
          _isDobbleBlocked = false;
          timer.cancel();
        }
      });
    });
  }

  // DANS _MultiplayerGameScreenState
  Widget _buildDobbleCardWidget(
    List<String> symbols,
    Function(String) onSymbolTap, {
    bool isLarge = false,
    bool isInteractable = true,
  }) {
    final double cardSize = isLarge ? 260 : 130;

    // --- AJUSTEMENT TAILLE ---
    // Taille réduite pour éviter le dépassement, mais reste assez grand
    final double baseSymbolSize = isLarge ? 42 : 21;

    // On rapproche un tout petit peu les symboles du centre
    final double layoutRadius = cardSize * 0.36;

    int seed = 0;
    for (var s in symbols) seed += s.hashCode;
    final Random random = Random(seed);

    List<String> displaySymbols = List.from(symbols)..shuffle(random);

    return Container(
      width: cardSize,
      height: cardSize,
      decoration: BoxDecoration(
        color: Colors.white,
        shape: BoxShape.circle,
        border: Border.all(color: Colors.grey[300]!, width: isLarge ? 6 : 3),
        boxShadow: [
          BoxShadow(
            color: Colors.black45,
            blurRadius: 15,
            spreadRadius: 2,
            offset: Offset(0, 8),
          ),
          BoxShadow(
            color: Colors.black12,
            blurRadius: 5,
            spreadRadius: -2,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Stack(
        alignment: Alignment.center,
        children: List.generate(displaySymbols.length, (index) {
          final symbol = displaySymbols[index];

          double x, y, size;

          if (index == 0) {
            // --- CENTRE ---
            x = 0;
            y = 0;
            // Max 1.3x la taille de base (max ~55px sur grande carte)
            size = baseSymbolSize * (1.0 + random.nextDouble() * 0.3);
          } else {
            // --- CERCLE ---
            final int ringCount = displaySymbols.length - 1;
            final double angle = (2 * pi * (index - 1) / ringCount);

            x = layoutRadius * cos(angle);
            y = layoutRadius * sin(angle);

            // Variation plus douce : 0.8x à 1.2x
            size = baseSymbolSize * (0.8 + random.nextDouble() * 0.4);
          }

          final double rotation = random.nextDouble() * 2 * pi;

          return _buildAnimatedSymbolPositioned(
            symbol,
            x,
            y,
            size,
            onSymbolTap,
            isInteractable,
            rotation: rotation,
          );
        }),
      ),
    );
  }

  // Helper pour placer et animer le symbole
  Widget _buildAnimatedSymbolPositioned(
    String symbol,
    double x,
    double y,
    double size,
    Function(String) onTap,
    bool isInteractable, {
    double rotation = 0,
  }) {
    return Positioned(
      left: 0,
      right: 0,
      top: 0,
      bottom: 0, // Astuce pour centrer absolu dans le Stack
      child: Center(
        child: Transform.translate(
          offset: Offset(x, y),
          child: Transform.rotate(
            angle: rotation,
            child: _DobbleSymbolButton(
              symbol: symbol,
              size: size,
              onTap: isInteractable ? () => onTap(symbol) : null,
            ),
          ),
        ),
      ),
    );
  }

  // Nouveau Widget helper pour animer le symbole au clic
  Widget _buildAnimatedSymbol(
    String symbol,
    double x,
    double y,
    double size,
    Function(String) onTap,
    bool isInteractable, {
    double rotation = 0,
  }) {
    return Positioned(
      left: 0,
      right: 0,
      top: 0,
      bottom: 0, // Astuce pour centrer dans le Stack
      child: Center(
        child: Transform.translate(
          offset: Offset(x, y),
          child: Transform.rotate(
            angle: rotation,
            child: _DobbleSymbolButton(
              symbol: symbol,
              size: size,
              onTap: isInteractable ? () => onTap(symbol) : null,
            ),
          ),
        ),
      ),
    );
  }

