  Widget _getWidgetForRoundState(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final roundState = gameData['roundState'];
    final gameType = gameData['gameType'];
    final players = (gameData['players'] as Map<String, dynamic>?) ?? {};
    final answers = (gameData['answers'] as Map<String, dynamic>?) ?? {};
    final votes = (gameData['votes'] as Map<String, dynamic>?) ?? {};
    final isSimplifiedLiar = gameData['isSimplifiedLiar'] ?? false;

    if (gameType == 'Qui Pourrait le Plus ?') {
      if (roundState == 'voting') {
        if (votes.containsKey(playerId)) {
          return _buildWaitingWidget(
            "Vote enregistré. En attente des autres joueurs...",
            players,
            votes.length,
            players.length,
          );
        }
        return _buildQuiPourraitLePlusVotingUI(context, gameData, playerId);
      }
    }

    if (gameType == 'Skull' &&
        (roundState == 'placing' || roundState == 'bidding')) {
      return _buildSkullUI(context, gameData, playerId);
    }

    switch (roundState) {
      case 'playing':
        if (gameType == 'La Patate Chaude') {
          return _buildHotPotatoUI(context, gameData, playerId);
        }
        if (answers.containsKey(playerId)) {
          return _buildWaitingWidget(
            "En attente des autres...",
            players,
            answers.length,
            players.length,
          );
        }
        if (gameType == 'Le Juge' &&
            gameData['currentTargetPlayerId'] == playerId) {
          return _buildWaitingWidget(
            "Les autres joueurs répondent...",
            players,
            answers.length,
            players.length - 1,
          );
        }
        return _buildAnsweringUI(context, gameData, playerId);

      case 'answering':
        if (answers.containsKey(playerId)) {
          return _buildWaitingWidget(
            "En attente des autres...",
            players,
            answers.length,
            players.length,
          );
        }
        if (gameType == 'Le Juge' &&
            gameData['currentTargetPlayerId'] == playerId) {
          return _buildWaitingWidget(
            "Les autres joueurs répondent...",
            players,
            answers.length,
            players.length - 1,
          );
        }
        return _buildAnsweringUI(context, gameData, playerId);

      case 'declaring_truth':
        final storyTruths = Map.from(
          gameData['storyTruths'] as Map<String, dynamic>? ?? {},
        );
        if (storyTruths.containsKey(playerId)) {
          return _buildWaitingWidget(
            "En attente des déclarations...",
            players,
            storyTruths.length,
            players.length,
          );
        }
        return _buildDeclaringTruthUI(context, gameData, playerId);

      case 'reveal_and_vote':
        return _buildSimplifiedLiarVotingUI(context, gameData, playerId);

      case 'voting':
        if (votes.containsKey(playerId) && !isSimplifiedLiar) {
          if (gameType == 'Le Juge' &&
              gameData['currentTargetPlayerId'] == playerId) {
            return _buildJudgeVotingUI(context, gameData, true);
          }
          return _buildWaitingWidget(
            "En attente des votes...",
            players,
            votes.length,
            players.length,
          );
        }
        if (isSimplifiedLiar) {
          return _buildSimplifiedLiarVotingUI(context, gameData, playerId);
        }
        if (gameType == 'Le Juge') {
          return _buildJudgeVotingUI(
            context,
            gameData,
            gameData['currentTargetPlayerId'] == playerId,
          );
        }
        return _buildVotingUI(context, gameData, playerId);

      case 'exploded':
        if (gameType == 'La Patate Chaude') {
          return _buildHotPotatoExplodedUI(context, gameData, playerId);
        }
        return _buildResultUI(context, gameData, playerId);

      case 'result':
        return _buildResultUI(context, gameData, playerId);

      case 'placing':
      case 'bidding':
        if (gameType == 'Skull') {
          return _buildSkullUI(context, gameData, playerId);
        }
        return _buildWaitingWidget("La partie continue...", players, 0, 0);

      default:
        return _buildWaitingWidget(
          "La partie va bientôt commencer...",
          players,
          0,
          0,
        );
    }
  }

  Widget _buildAnsweringUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final gameType = gameData['gameType'];
    final String? memeUrl = gameData['memeUrl']; // 1. Récupérer l'URL

    Widget? secretInfoWidget;

    // 2. Si c'est le jeu des mèmes, on prépare l'image
    if (gameType == 'Le Roi des Mèmes' && memeUrl != null) {
      secretInfoWidget = Container(
        constraints: BoxConstraints(maxHeight: 300), // Limiter la hauteur
        margin: EdgeInsets.only(bottom: 10),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Image.network(
            memeUrl,
            fit: BoxFit.contain,
            loadingBuilder: (context, child, loadingProgress) {
              if (loadingProgress == null) return child;
              return Center(child: CircularProgressIndicator());
            },
            errorBuilder: (context, error, stackTrace) {
              return Text(
                "Impossible de charger l'image",
                style: TextStyle(color: Colors.red),
              );
            },
          ),
        ),
      );
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: EdgeInsets.only(
            bottom: MediaQuery.of(context).viewInsets.bottom + 16,
          ),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16.0),
                    child: Text(
                      gameData['currentQuestion'] ?? "Question...",
                      textAlign: TextAlign.center,
                      style: Theme.of(context).textTheme.headlineSmall,
                    ),
                  ),
                ),
                SizedBox(height: 20),

                // 3. Afficher le widget secret (l'image du mème)
                if (secretInfoWidget != null) secretInfoWidget,

                SizedBox(height: 20),
                TextField(
                  controller: _answerController,
                  decoration: InputDecoration(labelText: "Votre réponse..."),
                  maxLines: 1,
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      _isActionPending || _answerController.text.trim().isEmpty
                          ? null
                          : () {
                            setState(() => _isActionPending = true);

                            _firebaseService
                                .submitAnswer(
                                  widget.gameCode,
                                  playerId,
                                  _answerController.text.trim(),
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                  child:
                      _isActionPending
                          ? SizedBox(
                            height: 20,
                            width: 20,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                          : Text("Soumettre"),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

