  Widget _buildSimplifiedLiarVotingUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String voterId,
  ) {
    final players = gameData['players'] as Map<String, dynamic>;
    final answers = gameData['answers'] as Map<String, dynamic>;
    final allVotes = Map.from(gameData['votes'] as Map<String, dynamic>? ?? {});
    final voteMode = gameData['liarVoteMode'];

    if (voteMode == 'turn_by_turn') {
      // ... (Gardez la logique 'turn_by_turn' existante, elle est fonctionnelle. On peut juste styliser la carte principale)
      // Pour ne pas tout recopier, je focus sur la liste complète qui est plus utilisée.
      // Vous pouvez appliquer le même style de Card que ci-dessous.
      final playerOrder = List<String>.from(gameData['playerOrder']);
      final revealIndex = gameData['revealIndex'] as int;
      final storyOwnerId = playerOrder[revealIndex];
      final storyOwnerName = players[storyOwnerId]?['name'] ?? 'Inconnu';
      final story = answers[storyOwnerId];
      final storyVotes = Map.from(
        allVotes[storyOwnerId] as Map<String, dynamic>? ?? {},
      );

      if (storyVotes.containsKey(voterId)) {
        return _buildWaitingWidget(
          "Vote enregistré...",
          players,
          storyVotes.length,
          players.length - 1,
        );
      }
      if (storyOwnerId == voterId) {
        return _buildWaitingWidget(
          "Les autres jugent ton histoire...",
          players,
          storyVotes.length,
          players.length - 1,
        );
      }

      return Center(
        child: Card(
          elevation: 10,
          margin: EdgeInsets.all(16),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircleAvatar(child: Text(storyOwnerName[0]), radius: 30),
                SizedBox(height: 10),
                Text(
                  "L'histoire de $storyOwnerName",
                  style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                ),
                Divider(),
                SizedBox(height: 20),
                Text(
                  '"$story"',
                  style: TextStyle(fontSize: 18, fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 40),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    _buildAnimatedTruthButton(
                      label: "VRAI",
                      color: Colors.green,
                      icon: Icons.thumb_up,
                      onTap:
                          _isActionPending
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitSimplifiedLiarVote(
                                      widget.gameCode,
                                      voterId,
                                      storyOwnerId,
                                      'Vrai',
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                    ),
                    _buildAnimatedTruthButton(
                      label: "FAUX",
                      color: Colors.red,
                      icon: Icons.thumb_down,
                      onTap:
                          _isActionPending
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitSimplifiedLiarVote(
                                      widget.gameCode,
                                      voterId,
                                      storyOwnerId,
                                      'Faux',
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      );
    } else {
      // Mode Simultané : Liste
      return Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              "Détecteur de Mensonges",
              style: Theme.of(
                context,
              ).textTheme.headlineSmall?.copyWith(fontWeight: FontWeight.bold),
            ),
          ),
          Expanded(
            child: ListView.builder(
              itemCount: answers.length,
              padding: EdgeInsets.symmetric(horizontal: 16),
              itemBuilder: (context, index) {
                final entry = answers.entries.elementAt(index);
                if (entry.key == voterId)
                  return SizedBox.shrink(); // Pas ma propre histoire

                final storyOwnerId = entry.key;
                final storyOwnerName =
                    players[storyOwnerId]?['name'] ?? 'Inconnu';
                final story = entry.value;
                final myVote =
                    (allVotes[storyOwnerId] as Map<String, dynamic>?)?[voterId];
                bool isVoted = myVote != null;

                return AnimatedContainer(
                  duration: Duration(milliseconds: 300),
                  margin: EdgeInsets.only(bottom: 12),
                  decoration: BoxDecoration(
                    color: isVoted ? Colors.grey[900] : Colors.deepPurple[800],
                    borderRadius: BorderRadius.circular(15),
                    border:
                        isVoted
                            ? Border.all(
                              color:
                                  myVote == 'Vrai' ? Colors.green : Colors.red,
                              width: 2,
                            )
                            : null,
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black45,
                        blurRadius: 5,
                        offset: Offset(0, 3),
                      ),
                    ],
                  ),
                  child: Padding(
                    padding: const EdgeInsets.all(16.0),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            CircleAvatar(
                              radius: 15,
                              backgroundColor: Colors.white24,
                              child: Text(
                                storyOwnerName[0],
                                style: TextStyle(
                                  fontSize: 12,
                                  color: Colors.white,
                                ),
                              ),
                            ),
                            SizedBox(width: 10),
                            Text(
                              storyOwnerName,
                              style: TextStyle(
                                fontWeight: FontWeight.bold,
                                fontSize: 16,
                              ),
                            ),
                          ],
                        ),
                        Padding(
                          padding: const EdgeInsets.symmetric(vertical: 12.0),
                          child: Text(
                            '"$story"',
                            style: TextStyle(
                              fontSize: 16,
                              fontStyle: FontStyle.italic,
                            ),
                          ),
                        ),

                        if (isVoted)
                          Container(
                            width: double.infinity,
                            padding: EdgeInsets.symmetric(vertical: 8),
                            decoration: BoxDecoration(
                              color:
                                  myVote == 'Vrai'
                                      ? Colors.green.withOpacity(0.2)
                                      : Colors.red.withOpacity(0.2),
                              borderRadius: BorderRadius.circular(8),
                            ),
                            child: Center(
                              child: Text(
                                "Tu as voté : ${myVote!.toUpperCase()}",
                                style: TextStyle(
                                  fontWeight: FontWeight.bold,
                                  color:
                                      myVote == 'Vrai'
                                          ? Colors.greenAccent
                                          : Colors.redAccent,
                                ),
                              ),
                            ),
                          )
                        else
                          Row(
                            children: [
                              Expanded(
                                child: ElevatedButton.icon(
                                  icon: Icon(Icons.check),
                                  label: Text("VRAI"),
                                  style: ElevatedButton.styleFrom(
                                    backgroundColor: Colors.green,
                                    foregroundColor: Colors.white,
                                  ),
                                  onPressed:
                                      _isActionPending
                                          ? null
                                          : () {
                                            setState(
                                              () => _isActionPending = true,
                                            );
                                            _firebaseService
                                                .submitSimplifiedLiarVote(
                                                  widget.gameCode,
                                                  voterId,
                                                  storyOwnerId,
                                                  'Vrai',
                                                )
                                                .whenComplete(() {
                                                  if (mounted)
                                                    setState(
                                                      () =>
                                                          _isActionPending =
                                                              false,
                                                    );
                                                });
                                          },
