                                  onPressed:
                                      _isActionPending
                                          ? null
                                          : () {
                                            setState(
                                              () => _isActionPending = true,
                                            );
                                            _firebaseService
                                                .submitSimplifiedLiarVote(
                                                  widget.gameCode,
