  Widget _buildResultUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    // Détection du mode Mondial : Soit c'est un lobby Premium, soit c'est un jeu configuré avec Timer + Scope Monde
    final bool isWorldMode =
        gameData['isPremiumLobby'] == true ||
        (gameData['useTimer'] == true && gameData['scope'] == 'monde');

    final String gameState = gameData['gameState'];
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isHost = gameData['hostId'] == playerId;

    // ---------------------------------------------------------------------
    // 1. ÉTAT REFILLING : Un joueur a quitté, on cherche un remplaçant
    // ---------------------------------------------------------------------
    if (gameState == 'refilling') {
      // Initialisation du timer de 10s si ce n'est pas déjà fait
      if (_postGameTimer == null || !_postGameTimer!.isActive) {
        _refillCountdown = 10;
        _postGameTimer = Timer.periodic(Duration(seconds: 1), (timer) {
          if (!mounted) return;
          setState(() {
            if (_refillCountdown > 0) _refillCountdown--;
          });
          if (_refillCountdown <= 0) {
            timer.cancel();
            // Le temps est écoulé, on force le démarrage avec les joueurs présents
            _firebaseService.forceStartAfterRefill(widget.gameCode);
          }
        });
      }

      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircularProgressIndicator(),
                SizedBox(height: 20),
                Text(
                  "Un joueur a quitté...",
                  style: Theme.of(context).textTheme.headlineSmall,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 10),
                Text(
                  "Recherche de remplaçants en cours...",
                  style: Theme.of(context).textTheme.bodyLarge,
                ),
                SizedBox(height: 20),
                Text(
                  "Démarrage automatique dans",
                  style: TextStyle(color: Colors.white70),
                ),
                Text(
                  "$_refillCountdown s",
                  style: TextStyle(
                    fontSize: 32,
                    fontWeight: FontWeight.bold,
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 20),
                Text(
                  "Joueurs connectés : ${players.length}",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // ---------------------------------------------------------------------
    // 2. ÉTAT GAME OVER (MODE MONDIAL) : Vote pour Rejouer ou Quitter
    // ---------------------------------------------------------------------
    if (isWorldMode && gameState == 'gameOver') {
      final restartVotes = Map<String, dynamic>.from(
        gameData['restartVotes'] ?? {},
      );
      final bool hasVoted = restartVotes.containsKey(playerId);

      // Initialisation du timer de vote de 15s
      if (_postGameTimer == null || !_postGameTimer!.isActive) {
        _postGameCountdown = 15;
        _postGameTimer = Timer.periodic(Duration(seconds: 1), (timer) {
          if (!mounted) return;
          setState(() {
            if (_postGameCountdown > 0) _postGameCountdown--;
          });
          if (_postGameCountdown <= 0) {
            timer.cancel();
            // Si je suis l'hôte ou le premier joueur (fail-safe), je déclenche le nettoyage
            // FirebaseService gère la concurrence via Transaction
            if (isHost || players.keys.first == playerId) {
              _firebaseService.handleRestartDecisionTimeout(widget.gameCode);
            }
          }
        });
      }

      // Récupération du gagnant pour l'affichage
      List<MapEntry<String, dynamic>> sortedPlayers =
          players.entries.toList()..sort(
            (a, b) => (b.value['score'] ?? 0).compareTo(a.value['score'] ?? 0),
          );
      String winnerName =
          sortedPlayers.isNotEmpty
              ? sortedPlayers.first.value['name']
              : "Personne";

      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie Terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  "Vainqueur : $winnerName",
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 5),
                Text(
                  gameData['gameEndReason'] ?? "",
                  textAlign: TextAlign.center,
                  style: TextStyle(color: Colors.white70),
                ),

                Divider(height: 30),

                Text(
                  "Voulez-vous rejouer ?",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                SizedBox(height: 5),
                Text(
                  "$_postGameCountdown s",
                  style: TextStyle(
                    fontSize: 30,
                    fontWeight: FontWeight.bold,
                    color:
                        _postGameCountdown <= 5
                            ? Colors.redAccent
                            : Colors.white,
                  ),
                ),

                SizedBox(height: 20),
                Wrap(
                  spacing: 20,
                  alignment: WrapAlignment.center,
                  children: [
                    ElevatedButton.icon(
                      icon: Icon(Icons.replay),
                      label: Text(
                        hasVoted
                            ? "En attente (${restartVotes.length}/${players.length})"
                            : "REJOUER",
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: hasVoted ? Colors.grey : Colors.green,
                        padding: EdgeInsets.symmetric(
                          horizontal: 24,
                          vertical: 12,
                        ),
                      ),
                      onPressed:
                          hasVoted
                              ? null
                              : () {
                                _firebaseService.submitRestartVote(
                                  widget.gameCode,
                                  playerId,
                                );
                              },
                    ),
                    OutlinedButton.icon(
                      icon: Icon(Icons.exit_to_app),
                      label: Text("Quitter"),
                      style: OutlinedButton.styleFrom(
                        foregroundColor: Colors.redAccent,
                        side: BorderSide(color: Colors.redAccent),
                        padding: EdgeInsets.symmetric(
                          horizontal: 24,
                          vertical: 12,
                        ),
                      ),
                      onPressed: () async {
                        if (_agoraInitialized) {
                          await _agoraService.leaveChannel();
                          await Future.delayed(const Duration(milliseconds: 300));
                        }
                        _firebaseService.removePlayerFromGame(
                          widget.gameCode,
                          playerId,
                        );
                        Navigator.of(
                          context,
                        ).popUntil((route) => route.isFirst);
                      },
                    ),
                  ],
                ),
                SizedBox(height: 15),
                Text(
                  "Si un joueur ne répond pas ou quitte, la partie cherchera un remplaçant.",
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.white38,
                    fontStyle: FontStyle.italic,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
      );
    }

    // ---------------------------------------------------------------------
    // 3. AFFICHAGE STANDARD DES RÉSULTATS (Mode Amis ou Fin de Tour)
    // ---------------------------------------------------------------------
    final gameType = gameData['gameType'];
    String resultText = "";
    Widget? extraInfo;
    final isSimplifiedLiar = gameData['isSimplifiedLiar'] ?? false;
    final String? gameEndReason = gameData['gameEndReason'];
    final String? memeUrl = gameData['memeUrl'];
    final bool isSkullGameOver =
        gameType == 'Skull' && gameData['gameState'] == 'gameOver';

    // --- LOGIQUE SPÉCIFIQUE PAR JEU (Copiée de l'ancienne version) ---
    switch (gameType) {
      case 'Le Juge':
        final winnerId = gameData['roundWinnerId'];
        final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
        final winningAnswer =
            (gameData['answers'] as Map<String, dynamic>?)?[winnerId] ??
            'aucune réponse';
        resultText =
            "$winnerName a été choisi pour sa réponse et gagne 1 point !";
        extraInfo = Text(
          '"${winningAnswer}"',
          style: TextStyle(fontStyle: FontStyle.italic, color: Colors.white70),
          textAlign: TextAlign.center,
        );
        break;

      case 'Le Menteur':
        if (isSimplifiedLiar) {
          resultText = "Résultats des votes";
          final answers = gameData['answers'] as Map<String, dynamic>;
          final storyTruths = gameData['storyTruths'] as Map<String, dynamic>;
          final votes = gameData['voteResults'] as Map<String, dynamic>;
          extraInfo = Expanded(
            child: ListView(
              children:
                  answers.keys.map((storyOwnerId) {
                    final storyOwnerName =
                        players[storyOwnerId]?['name'] ?? '...';
                    final story = answers[storyOwnerId];
                    final actualTruth =
                        storyTruths[storyOwnerId] == true ? "VRAIE" : "FAUSSE";
                    final storyVotes = Map.from(
                      votes[storyOwnerId] as Map<String, dynamic>? ?? {},
                    );

                    return Card(
                      margin: EdgeInsets.symmetric(vertical: 8),
                      child: Padding(
                        padding: const EdgeInsets.all(12.0),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Histoire de $storyOwnerName (était $actualTruth)',
                              style: Theme.of(
                                context,
                              ).textTheme.titleLarge?.copyWith(
                                color:
                                    actualTruth == "VRAIE"
                                        ? Colors.greenAccent
                                        : Colors.redAccent,
                              ),
                            ),
                            SizedBox(height: 4),
                            Text(
                              '"$story"',
                              style: TextStyle(
                                fontStyle: FontStyle.italic,
                                color: Colors.white70,
                              ),
                            ),
                            Divider(height: 20),
                            Text(
                              "Votes :",
                              style: Theme.of(context).textTheme.bodyMedium,
                            ),
                            ...storyVotes.entries.map((voteEntry) {
                              final voterName =
                                  players[voteEntry.key]?['name'] ?? '...';
                              final voteValue = voteEntry.value;
                              final bool wasCorrect =
                                  (voteValue == "Vrai" &&
                                      actualTruth == "VRAIE") ||
                                  (voteValue == "Faux" &&
                                      actualTruth == "FAUSSE");
                              return Row(
                                children: [
                                  Icon(
                                    wasCorrect
                                        ? Icons.check_circle
                                        : Icons.cancel,
                                    color:
                                        wasCorrect ? Colors.green : Colors.red,
                                    size: 16,
                                  ),
                                  SizedBox(width: 8),
                                  Text('$voterName a voté : $voteValue'),
                                ],
                              );
                            }),
                          ],
                        ),
                      ),
                    );
                  }).toList(),
            ),
          );
          break;
        } else {
          final liarId = gameData['liarId'];
          final liarName = players[liarId]?['name'] ?? 'Le menteur';
          resultText = "Le menteur était... $liarName !";
          extraInfo = Text(
            "Les points ont été distribués en fonction de vos votes.",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        }
        break;

      case 'Infiltré & Mr. White':
        final undercoverId = gameData['undercoverId'];
        final mrWhiteId = gameData['mrWhiteId'];
        final undercoverName = players[undercoverId]?['name'] ?? 'Inconnu';
        final mrWhiteName = players[mrWhiteId]?['name'] ?? 'Inconnu';
        final wordPair = (gameData['roundData'] as String? ?? ":").split(":");
        final winner = gameData['roundWinnerId'];

        if (winner == 'impostors') {
          resultText = "Les imposteurs ont gagné ! Un civil a été éliminé.";
        } else if (winner == 'civilians_and_mrwhite') {
          resultText = "L'Infiltré ($undercoverName) a été démasqué !";
        } else if (winner == 'civilians_and_undercover') {
          resultText = "Mr. White ($mrWhiteName) a été démasqué !";
        } else {
          resultText = "Le tour est terminé !";
        }

        extraInfo = Column(
          children: [
            Text(
              "Le mot des Civils était : '${wordPair[0]}'",
              style: TextStyle(
                fontStyle: FontStyle.italic,
                color: Colors.white70,
              ),
            ),
            if (undercoverId != null)
              Text(
                "Le mot de l'Infiltré (${undercoverName}) était : '${wordPair[1]}'",
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
            if (mrWhiteId != null)
              Text(
                "Mr. White (${mrWhiteName}) n'avait pas de mot.",
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
          ],
        );
        break;

      case 'Synonyme ou Banni':
        final loserId = gameData['roundLoserId'];
        if (loserId != null) {
          final loserName = players[loserId]?['name'] ?? 'Quelqu\'un';
          final word = gameData['roundData'];
          final loserAnswer = gameData['answers'][loserId];
          resultText =
              "$loserName a été banni pour sa proposition '$loserAnswer' !";
          extraInfo = Text(
            "Le mot à trouver était un synonyme de '$word'. Les autres joueurs marquent 1 point.",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText = "Égalité dans les votes ! Personne n'est banni.";
        }
        break;

      case 'Le Jeu des Catégories':
      case 'La Patate Chaude':
        final loserId = gameData['roundWinnerId'];
        if (loserId != null) {
          final loserName = players[loserId]?['name'] ?? 'Inconnu';
          resultText =
              "${loserName} n'a pas répondu à temps et gagne 1 point !";
          extraInfo = Text(
            gameData['gameEndReason'] ?? "Temps écoulé !",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText = "Égalité ! Personne ne prend de point ce tour-ci.";
        }
        break;

      case 'Pictionary':
        final winnerId = gameData['roundWinnerId'];
        final currentWord = gameData['currentPictionaryWord'] ?? 'Mot';
        final drawingPlayerName =
            players[gameData['currentDrawingPlayerId']]?['name'] ??
            'Le dessinateur';
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          resultText = "$winnerName a trouvé le mot : '$currentWord' !";
          extraInfo = Text(
            "Félicitations au dessinateur $drawingPlayerName et à $winnerName !",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        } else {
          resultText = "Personne n'a trouvé le mot : '$currentWord'.";
          extraInfo = Text(
            gameEndReason ??
                "Le temps est écoulé ou le dessin était trop complexe !",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          );
        }
        break;

      case 'Just One':
        final currentWord = gameData['justOneCurrentWord'] ?? 'Mot';
        final guesserName =
            players[gameData['justOneGuesserId']]?['name'] ?? 'Le devin';
        final guesserAnswer =
            gameData['justOneGuesserAnswer'] ?? '(pas de réponse)';
        if (gameEndReason == 'Mot deviné !') {
          resultText = "$guesserName a trouvé le mot : '$currentWord' !";
          extraInfo = Text(
            "Sa réponse était : '$guesserAnswer'.",
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.greenAccent,
            ),
          );
        } else {
          resultText = "$guesserName n'a pas trouvé le mot.";
          extraInfo = Column(
            children: [
              Text(
                "Le mot était : '$currentWord'.",
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.white70,
                ),
              ),
              Text(
                "Sa réponse était : '$guesserAnswer'.",
                textAlign: TextAlign.center,
                style: TextStyle(
                  fontStyle: FontStyle.italic,
                  color: Colors.redAccent,
                ),
              ),
            ],
          );
        }
        break;

      case 'Skull':
        final String? outcome = gameData['skullLastChallengeOutcome'];
        final int challengeBid = gameData['skullLastChallengeBid'] ?? 0;
        final List<dynamic> revealed = List<dynamic>.from(
          gameData['skullLastChallengeRevealed'] ?? [],
        );
        final String? winnerId = gameData['gameWinner'];

        if (gameData['gameState'] == 'gameOver' && winnerId != null) {
          resultText =
              "${players[winnerId]?['name'] ?? 'Un joueur'} remporte Skull !";
          extraInfo = Text(
            gameData['gameEndReason'] ?? 'Deux défis réussis.',
            textAlign: TextAlign.center,
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.greenAccent,
            ),
          );
        } else if (outcome == 'won') {
          resultText = "Défi gagné : $challengeBid carte(s) révélée(s) !";
        } else if (outcome == 'lost') {
          final loserName =
              players[gameData['skullLastChallengeLoserId']]?['name'] ??
              'Le challenger';
          resultText = "$loserName a perdu le défi.";
        } else {
          resultText = "Le tour est terminé.";
        }

        if (revealed.isNotEmpty) {
          extraInfo = Column(
            children: [
              Text(
                "Cartes révélées :",
                style: TextStyle(color: Colors.white70),
              ),
              SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children:
                    revealed.map((entry) {
                      final Map<String, dynamic> card =
                          Map<String, dynamic>.from(entry as Map);
                      final String ownerName =
                          players[card['ownerId']]?['name'] ?? 'Joueur';
                      return Chip(
                        label: Text(
                          '$ownerName : ${card['type'] == 'Crane' ? 'Crâne' : 'Rose'}',
                        ),
                        backgroundColor:
                            card['type'] == 'Crane'
                                ? Colors.redAccent.withOpacity(0.3)
                                : Colors.greenAccent.withOpacity(0.2),
                      );
                    }).toList(),
              ),
            ],
          );
        }
        break;

      case 'Le Roi des Mèmes':
        final winnerId = gameData['roundWinnerId'];
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          final winningDescription =
              (gameData['answers'] as Map<String, dynamic>?)?[winnerId] ??
              'une description hilarante';
          resultText = "$winnerName a gagné avec sa description :";
          extraInfo = Column(
            children: [
              Text(
                '"${winningDescription}"',
                style: Theme.of(
                  context,
                ).textTheme.titleLarge?.copyWith(color: Colors.greenAccent),
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 15),
              if (memeUrl != null)
                Container(
                  constraints: BoxConstraints(maxHeight: 250),
                  child: Image.network(
                    memeUrl,
                    fit: BoxFit.contain,
                    errorBuilder:
                        (context, error, stackTrace) => Center(
                          child: Text("Erreur de chargement du mème."),
                        ),
                  ),
                ),
            ],
          );
        } else {
          resultText =
              "Personne n'a gagné ce tour. Égalité des votes ou pas de description.";
          extraInfo = Text(
            gameEndReason ?? "",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
            textAlign: TextAlign.center,
          );
        }
        break;

      case 'Dobble':
        final winnerId = gameData['roundWinnerId'];
        if (winnerId != null) {
          final winnerName = players[winnerId]?['name'] ?? 'Quelqu\'un';
          final commonSym = gameData['commonSymbol'];
          resultText =
              "$winnerName a trouvé le symbole $commonSym ! Il gagne la carte.";
          extraInfo = Text(
            "Score actuel de ${players[winnerId]?['name'] ?? 'Lui'}: ${players[winnerId]?['score'] ?? 0} cartes.",
            style: TextStyle(fontStyle: FontStyle.italic),
          );
        } else {
          resultText =
              "Le tour est terminé. Personne n'a trouvé le symbole commun.";
          extraInfo = Text(
            gameEndReason ?? "Un problème est survenu.",
            style: TextStyle(fontStyle: FontStyle.italic),
          );
        }
        break;

      case 'Qui Pourrait le Plus ?':
      default:
        final roundWinnerId = gameData['roundWinnerId'];
        if (roundWinnerId != null) {
          final winnerName = players[roundWinnerId]?['name'] ?? 'Inconnu';
          resultText = "$winnerName a été désigné(e) et gagne 1 point !";
        } else {
          resultText = "Égalité ! Personne ne marque de point ce tour-ci.";
        }
        break;
    }

    // Affichage final de la carte de résultat
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text("Fin du tour", style: Theme.of(context).textTheme.headlineMedium),
        SizedBox(height: 20),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              resultText,
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.titleLarge,
            ),
          ),
        ),
        SizedBox(height: 10),
        if (extraInfo != null) extraInfo,
        SizedBox(height: 40),

        // Affichage des contrôles (Hôte vs Client)
        if (isHost && !isSkullGameOver)
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () {
                      setState(() => _isActionPending = true);

                      if (gameType == 'Dobble') {
                        _firebaseService
                            .nextDobbleRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'La Patate Chaude' ||
                          gameType == 'Le Jeu des Catégories') {
                        _firebaseService
                            .nextHotPotatoRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Pictionary') {
                        _firebaseService
                            .nextPictionaryRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Just One') {
                        _firebaseService
                            .nextJustOneRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else if (gameType == 'Skull') {
                        _firebaseService
                            .nextSkullRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      } else {
                        _firebaseService
                            .nextRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      }
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Tour suivant"),
          )
        else if (isSkullGameOver)
          TextButton(
            onPressed:
                () => Navigator.of(context).popUntil((route) => route.isFirst),
            child: Text("Retour à l'accueil"),
          )
        else
          Text(
            "En attente de l'hôte pour le tour suivant...",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          ),
      ],
    );
  }

  Widget _buildWaitingWidget(
    String message,
    Map<String, dynamic> players,
    int currentCount,
    int totalExpected,
  ) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        CircularProgressIndicator(
          value: totalExpected > 0 ? currentCount / totalExpected : null,
          backgroundColor: Colors.white12,
          valueColor: AlwaysStoppedAnimation<Color>(Colors.deepPurpleAccent),
        ),
        SizedBox(height: 20),
        Text(
          message,
          style: TextStyle(color: Colors.white70, fontStyle: FontStyle.italic),
          textAlign: TextAlign.center,
        ),
        if (totalExpected > 0)
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              "$currentCount / $totalExpected",
              style: TextStyle(color: Colors.white, fontSize: 18),
            ),
          ),

        if (_isActionPending)
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              "Votre action est en cours d'enregistrement...",
              style: TextStyle(color: Colors.amberAccent, fontSize: 14),
            ),
          ),
      ],
    );
  }

  Widget _buildCodenamesUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'],
    );
    final List<String> redTeam = List<String>.from(gameData['redTeam'] ?? []);
    final List<String> blueTeam = List<String>.from(gameData['blueTeam'] ?? []);
    final String? masterSpyRed = gameData['masterSpyRed'];
    final String? masterSpyBlue = gameData['masterSpyBlue'];
    final String activeTeam = gameData['activeTeam'] ?? 'red';
    final String roundState = gameData['roundState'] ?? 'clue_giving';
    final List<String> codenamesWords = List<String>.from(
      gameData['codenamesWords'] ?? [],
    );
    final Map<String, String> keyCard = Map<String, String>.from(
      gameData['codenamesKeyCard'] ?? {},
    );
    final Map<String, bool> revealedWords = Map<String, bool>.from(
      gameData['codenamesRevealed'] ?? {},
    );
    final String? currentClue = gameData['currentClue'];
    final int clueCount = gameData['clueCount'] ?? 0;
    final int guessesLeft = gameData['guessesLeft'] ?? 0;
    final String gameWinner = gameData['gameWinner'] ?? '';
    final String gameEndReason = gameData['gameEndReason'] ?? '';

    bool isMasterSpy = (playerId == masterSpyRed || playerId == masterSpyBlue);
    bool isMyTeamTurn =
        (activeTeam == 'red' && redTeam.contains(playerId)) ||
        (activeTeam == 'blue' && blueTeam.contains(playerId));
    bool canGiveClue =
        isMasterSpy && isMyTeamTurn && roundState == 'clue_giving';
    bool canGuess = !isMasterSpy && isMyTeamTurn && roundState == 'guessing';
    bool isGameOver = gameData['gameState'] == 'gameOver';

    if (isGameOver) {
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie Terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  "L'équipe ${gameWinner == 'red' ? 'Rouge' : 'Bleue'} a gagné !",
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color:
                        gameWinner == 'red'
                            ? Colors.redAccent
                            : Colors.blueAccent,
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  gameEndReason,
                  textAlign: TextAlign.center,
                  style: TextStyle(color: Colors.white70),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed: () {
                    Navigator.of(context).popUntil((route) => route.isFirst);
                  },
                  child: Text("Retour à l'accueil"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    return Column(
      children: [
        Container(
          padding: EdgeInsets.symmetric(vertical: 8.0),
          decoration: BoxDecoration(
            color:
                activeTeam == 'red'
                    ? Colors.red.withOpacity(0.2)
                    : Colors.blue.withOpacity(0.2),
            borderRadius: BorderRadius.circular(8),
          ),
          child: Column(
            children: [
              Text(
                "C'est au tour de l'équipe : ${activeTeam == 'red' ? 'Rouge' : 'Bleue'}",
                style: Theme.of(context).textTheme.titleLarge,
              ),
              SizedBox(height: 5),
              Text(
                "Vous êtes : ${redTeam.contains(playerId) ? 'Équipe Rouge' : (blueTeam.contains(playerId) ? 'Équipe Bleue' : 'Spectateur')}"
                "${(playerId == masterSpyRed || playerId == masterSpyBlue) ? ' (Maître-espion)' : ' (Agent)'}",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
            ],
          ),
        ),
        SizedBox(height: 15),
        Expanded(
          child: GridView.builder(
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 5,
              childAspectRatio: 2.0,
              crossAxisSpacing: 8.0,
              mainAxisSpacing: 8.0,
            ),
            itemCount: codenamesWords.length,
            itemBuilder: (context, index) {
              String word = codenamesWords[index];
              String actualColor = keyCard[word] ?? 'neutral';
              bool isRevealed = revealedWords[word] ?? false;

              Color cardColor = Colors.grey[800]!;
              Color textColor = Colors.white;

              if (isRevealed) {
                if (actualColor == 'red')
                  cardColor = Colors.red[900]!;
                else if (actualColor == 'blue')
                  cardColor = Colors.blue[900]!;
                else if (actualColor == 'assassin')
                  cardColor = Colors.black;
                else
                  cardColor = Colors.brown[700]!;
              }

              return GestureDetector(
                onTap:
                    canGuess && !isRevealed && !_isActionPending
                        ? () {
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .revealCodenamesWord(widget.gameCode, word)
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        }
                        : null,

                child: Card(
                  color: cardColor,
                  child: Center(
                    child: Text(
                      word,
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        color: textColor,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        SizedBox(height: 15),
        if (isMasterSpy)
          _buildCodenamesMasterSpyUI(context, gameData, playerId, canGiveClue)
        else
          _buildCodenamesAgentUI(context, gameData, playerId, canGuess),
      ],
    );
  }

  Widget _buildCodenamesMasterSpyUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    bool canGiveClue,
  ) {
    final Map<String, String> keyCard = Map<String, String>.from(
      gameData['codenamesKeyCard'] ?? {},
    );
    final Map<String, bool> revealedWords = Map<String, bool>.from(
      gameData['codenamesRevealed'] ?? {},
    );
    final List<String> codenamesWords = List<String>.from(
      gameData['codenamesWords'] ?? {},
    );
    final TextEditingController clueController = TextEditingController();
    int chosenCount = 1;

    return Column(
      children: [
        Text(
          "Vue Maître-Espion (Carte Clé)",
          style: Theme.of(context).textTheme.titleLarge,
        ),
        SizedBox(
          height: 200,
          child: GridView.builder(
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: 5,
              childAspectRatio: 1.0,
              crossAxisSpacing: 4.0,
              mainAxisSpacing: 4.0,
            ),
            itemCount: codenamesWords.length,
            itemBuilder: (context, index) {
              String word = codenamesWords[index];
              String actualColor = keyCard[word] ?? 'neutral';
              bool isRevealed = revealedWords[word] ?? false;

              Color dotColor = Colors.grey;
              if (actualColor == 'red')
                dotColor = Colors.red;
              else if (actualColor == 'blue')
                dotColor = Colors.blue;
              else if (actualColor == 'assassin')
                dotColor = Colors.black;

              return Container(
                decoration: BoxDecoration(
                  color:
                      isRevealed ? dotColor.withOpacity(0.5) : Colors.grey[900],
                  border: Border.all(color: dotColor, width: 2),
                  borderRadius: BorderRadius.circular(4),
                ),
                child: Center(
                  child: Text(
                    word,
                    textAlign: TextAlign.center,
                    style: TextStyle(color: Colors.white, fontSize: 10),
                  ),
                ),
              );
            },
          ),
        ),
        SizedBox(height: 10),
        if (canGiveClue)
          Column(
            children: [
              TextField(
                controller: clueController,
                decoration: InputDecoration(labelText: "Votre indice (un mot)"),
              ),
              SizedBox(height: 10),
              DropdownButtonFormField<int>(
                value: chosenCount,
                items:
                    List.generate(10, (index) => index + 1)
                        .map(
                          (count) => DropdownMenuItem(
                            value: count,
                            child: Text("$count"),
                          ),
                        )
                        .toList(),
                onChanged: (val) => chosenCount = val!,
                decoration: InputDecoration(labelText: "Nombre de mots"),
              ),
              SizedBox(height: 10),

              ElevatedButton(
                onPressed:
                    _isActionPending
                        ? null
                        : () {
                          if (clueController.text.trim().isNotEmpty &&
                              chosenCount > 0) {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .submitCodenamesClue(
                                  widget.gameCode,
                                  clueController.text.trim(),
                                  chosenCount,
                                )
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                            clueController.clear();
                          }
                        },
                child:
                    _isActionPending
                        ? SizedBox(
                          height: 20,
                          width: 20,
                          child: CircularProgressIndicator(
                            color: Colors.white,
                            strokeWidth: 2,
                          ),
                        )
                        : Text("Donner l'indice"),
              ),
            ],
          )
        else if (gameData['currentClue'] != null)
          Text(
            "Vous avez donné l'indice: '${gameData['currentClue']} ${gameData['clueCount']}'",
            textAlign: TextAlign.center,
            style: TextStyle(fontStyle: FontStyle.italic),
          ),
      ],
    );
  }

  Widget _buildCodenamesAgentUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
    bool canGuess,
  ) {
    final String activeTeam = gameData['activeTeam'];
    final String? currentClue = gameData['currentClue'];
    final int clueCount = gameData['clueCount'] ?? 0;
    final int guessesLeft = gameData['guessesLeft'] ?? 0;

    return Column(
      children: [
        Text("Vue Agent", style: Theme.of(context).textTheme.titleLarge),
        SizedBox(height: 10),
        if (currentClue != null)
          Column(
            children: [
              Text(
                "Indice de ${activeTeam == 'red' ? 'votre maître-espion rouge' : 'votre maître-espion bleu'}:",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              Text(
                "'$currentClue $clueCount'",
                style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                  color:
                      activeTeam == 'red'
                          ? Colors.redAccent
                          : Colors.blueAccent,
                ),
              ),
              SizedBox(height: 5),
              Text(
                "Essais restants : $guessesLeft",
                style: Theme.of(context).textTheme.titleLarge,
              ),
              SizedBox(height: 10),
              if (canGuess)
                ElevatedButton(
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .passCodenamesTurn(widget.gameCode)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                  child:
                      _isActionPending
                          ? SizedBox(
                            height: 20,
                            width: 20,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                          : Text("Passer son tour"),
                ),
            ],
          )
        else
          Text(
            "En attente de l'indice du Maître-Espion ${activeTeam == 'red' ? 'rouge' : 'bleu'}...",
            style: Theme.of(
              context,
            ).textTheme.titleLarge?.copyWith(color: Colors.white70),
          ),
      ],
    );
  }

  Widget _buildTimesUpUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'collecting_words';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isHost = gameData['hostId'] == playerId;

    // --- CORRECTION ICI : Récupération correcte du numéro de la manche ---
    final int currentRoundNumber = gameData['currentRoundNumber'] ?? 1;

    // --- ECRAN GAME OVER ---
    if (gameData['gameState'] == 'gameOver') {
      final Map<String, dynamic> teamScores = gameData['teamScores'] ?? {};
      String winnerMessage = "La partie est finie !";

      int scoreA = teamScores['teamA'] ?? 0;
      int scoreB = teamScores['teamB'] ?? 0;

      if (scoreA > scoreB) {
        winnerMessage = "L'équipe A a gagné !";
      } else if (scoreB > scoreA) {
        winnerMessage = "L'équipe B a gagné !";
      } else {
        winnerMessage = "Égalité parfaite !";
      }

      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie Terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  winnerMessage,
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  "Scores finaux :",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                Text(
                  "Équipe A: $scoreA points",
                  style: Theme.of(context).textTheme.bodyLarge,
                ),
                Text(
                  "Équipe B: $scoreB points",
                  style: Theme.of(context).textTheme.bodyLarge,
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour à l'accueil"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    // --- PHASE 1 : SAISIE DES MOTS ---
    if (roundState == 'collecting_words') {
      final Map<String, dynamic> submittedPlayers = Map<String, dynamic>.from(
        gameData['timesUpSubmittedPlayers'] ?? {},
      );

      if (submittedPlayers.containsKey(playerId)) {
        return _buildWaitingWidget(
          "En attente que tous les joueurs soumettent leurs mots...",
          players,
          submittedPlayers.length,
          players.length,
        );
      }

      final int targetWordCount = players.length <= 4 ? 3 : 5;
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            "Ajoutez $targetWordCount mots ou expressions",
            style: Theme.of(context).textTheme.headlineSmall,
            textAlign: TextAlign.center,
          ),
          Text(
            "(personnes, objets, films, lieux...)",
            style: Theme.of(context).textTheme.bodyMedium,
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 20),
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: _timesUpWordController,
                  enabled: _myTimesUpWords.length < targetWordCount,
                  decoration: InputDecoration(
                    labelText:
                        "Mot à deviner (${_myTimesUpWords.length}/$targetWordCount)",
                  ),
                  onSubmitted: (value) {
                    final word = value.trim();
                    if (word.isNotEmpty &&
                        _myTimesUpWords.length < targetWordCount &&
                        !_myTimesUpWords.contains(word)) {
                      setState(() {
                        _myTimesUpWords.add(word);
                        _timesUpWordController.clear();
                      });
                    }
                  },
                ),
              ),
              IconButton(
                icon: Icon(
                  Icons.add_circle,
                  color: Colors.deepPurpleAccent,
                  size: 30,
                ),
                onPressed:
                    (_timesUpWordController.text.trim().isEmpty ||
                            _myTimesUpWords.length >= targetWordCount ||
                            _myTimesUpWords.contains(
                              _timesUpWordController.text.trim(),
                            ))
                        ? null
                        : () {
                          setState(() {
                            _myTimesUpWords.add(
                              _timesUpWordController.text.trim(),
                            );
                            _timesUpWordController.clear();
                          });
                        },
                tooltip: "Ajouter ce mot",
              ),
            ],
          ),
          SizedBox(height: 20),
          Text("Vos mots :", style: Theme.of(context).textTheme.titleLarge),
          SizedBox(height: 10),
          Expanded(
            child: SingleChildScrollView(
              child: Wrap(
                spacing: 8.0,
                runSpacing: 4.0,
                children:
                    _myTimesUpWords
                        .map(
                          (word) => Chip(
                            label: Text(word),
                            onDeleted: () {
                              setState(() {
                                _myTimesUpWords.remove(word);
                              });
                            },
                          ),
                        )
                        .toList(),
              ),
            ),
          ),
          SizedBox(height: 20),
          ElevatedButton(
            onPressed:
                _isActionPending || _myTimesUpWords.length < targetWordCount
                    ? null
                    : () {
                      setState(() => _isActionPending = true);
                      _firebaseService
                          .submitTimesUpWords(
                            widget.gameCode,
                            playerId,
                            _myTimesUpWords,
                          )
                          .catchError((e) {
                            if (mounted) {
                              ScaffoldMessenger.of(context).showSnackBar(
                                SnackBar(
                                  content: Text("Erreur: ${e.toString()}"),
                                ),
                              );
                            }
                          })
                          .whenComplete(() {
                            if (mounted) {
                              setState(() => _isActionPending = false);
                            }
                          });
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Soumettre mes $targetWordCount mots"),
          ),
        ],
      );
    }
    // --- PHASE JEU ---
    else {
      final List<String> currentDeck = List<String>.from(
        gameData['timesUpCurrentDeck'] ?? [],
      );
      final String? currentGuesserId = gameData['currentGuesserId'];
      final int currentRoundTime = gameData['currentRoundTime'] ?? 0;
      final bool amICurrentGuesser = playerId == currentGuesserId;
      final Map<String, dynamic> teamScores = Map<String, dynamic>.from(
        gameData['teamScores'] ?? {},
      );
      final Map<String, dynamic> teams = Map<String, dynamic>.from(
        gameData['teams'] ?? {},
      );
      final List<dynamic> teamA = List.from(teams['teamA'] ?? []);
      final List<dynamic> teamB = List.from(teams['teamB'] ?? []);
      final String myTeam = teamA.contains(playerId) ? 'Équipe A' : 'Équipe B';

      String currentModeDescription = "";
      if (currentRoundNumber == 1)
        currentModeDescription = "Description libre";
      else if (currentRoundNumber == 2)
        currentModeDescription = "Un seul mot";
      else if (currentRoundNumber == 3)
        currentModeDescription = "Mime";

      String currentWordToGuess =
          currentDeck.isNotEmpty ? currentDeck.first : "FIN DE MANCHE !";

      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          // Team scores
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              Text(
                "Équipe A: ${teamScores['teamA'] ?? 0}",
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color:
                      teamA.contains(playerId)
                          ? Colors.greenAccent
                          : Colors.white70,
                ),
              ),
              Text(
                "Équipe B: ${teamScores['teamB'] ?? 0}",
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color:
                      teamB.contains(playerId)
                          ? Colors.greenAccent
                          : Colors.white70,
                ),
              ),
            ],
          ),
          SizedBox(height: 4),
          Text(
            "Vous êtes dans $myTeam",
            style: TextStyle(fontSize: 12, color: Colors.white54),
          ),
          SizedBox(height: 8),
          // Info Manche
          Container(
            padding: EdgeInsets.symmetric(vertical: 8, horizontal: 20),
            decoration: BoxDecoration(
              color: Colors.deepPurple,
              borderRadius: BorderRadius.circular(20),
            ),
            child: Text(
              "Manche $currentRoundNumber : $currentModeDescription",
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
            ),
          ),

          Spacer(),

          if (amICurrentGuesser)
            Column(
              children: [
                Text(
                  "C'est TON tour de faire deviner !",
                  style: TextStyle(
                    color: Colors.greenAccent,
                    fontSize: 20,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 20),

                // CARTE À DEVINER
                Container(
                  height: 200,
                  width: 300,
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(20),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black45,
                        blurRadius: 10,
                        offset: Offset(0, 10),
                      ),
                    ],
                  ),
                  child: Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          Icons.visibility,
                          color: Colors.grey[400],
                          size: 30,
                        ),
                        SizedBox(height: 10),
                        Padding(
                          padding: const EdgeInsets.all(16.0),
                          child: Text(
                            currentWordToGuess,
                            style: TextStyle(
                              color: Colors.black87,
                              fontSize: 32,
                              fontWeight: FontWeight.bold,
                            ),
                            textAlign: TextAlign.center,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),

                SizedBox(height: 40),

                // BOUTONS D'ACTION (Gros boutons)
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    FloatingActionButton.large(
                      heroTag: "pass",
                      backgroundColor: Colors.orange,
                      onPressed:
                          _isActionPending || currentDeck.isEmpty
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .guessTimesUpWord(
                                      widget.gameCode,
                                      currentWordToGuess,
                                      false,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                      child: Icon(
                        Icons.skip_next,
                        size: 40,
                        color: Colors.white,
                      ),
                    ),
                    FloatingActionButton.large(
                      heroTag: "guess",
                      backgroundColor: Colors.green,
                      onPressed:
                          _isActionPending || currentDeck.isEmpty
                              ? null
                              : () {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .guessTimesUpWord(
                                      widget.gameCode,
                                      currentWordToGuess,
                                      true,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              },
                      child: Icon(Icons.check, size: 50, color: Colors.white),
                    ),
                  ],
                ),
                SizedBox(height: 10),
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    Text("Passer", style: TextStyle(color: Colors.orange)),
                    Text("Trouvé !", style: TextStyle(color: Colors.green)),
                  ],
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      _isActionPending
                          ? null
                          : () {
                            setState(() => _isActionPending = true);
                            _firebaseService
                                .startTimesUpRoundTurn(widget.gameCode)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                  child: Text("Fin de mon tour"),
                  style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
                ),
              ],
            )
          else
            // Vue Spectateur
            Column(
              children: [
                Text(
                  "C'est au tour de",
                  style: TextStyle(fontSize: 20, color: Colors.white70),
                ),
                SizedBox(height: 10),
                CircleAvatar(
                  radius: 40,
                  child: Text(
                    players[currentGuesserId]?['name']?[0] ?? '?',
                    style: TextStyle(fontSize: 30),
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  players[currentGuesserId]?['name'] ?? 'Quelqu\'un',
                  style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
                ),
                SizedBox(height: 40),
                Container(
                  padding: EdgeInsets.all(30),
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(color: Colors.white24, width: 5),
                  ),
                  child: Column(
                    children: [
                      Text(
                        "$currentRoundTime",
                        style: TextStyle(
                          fontSize: 40,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      Text("secondes", style: TextStyle(fontSize: 12)),
                    ],
                  ),
                ),
                SizedBox(height: 40),
                Text(
                  "Cartes restantes : ${currentDeck.length}",
                  style: TextStyle(color: Colors.white54),
                ),
                SizedBox(height: 20),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .startTimesUpRoundTurn(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child: Text("Forcer le joueur suivant (Hôte)"),
                  ),
              ],
            ),

          Spacer(),
        ],
      );
    }
  }

  Widget _buildPetitBacUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState =
        gameData['roundState'] ?? 'waiting_for_categories';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final bool isHost = gameData['hostId'] == playerId;
    final String currentLetter = gameData['petitBacCurrentLetter'] ?? '';
    List<String> categories = List<String>.from(
      gameData['petitBacCategories'] ?? [],
    );
    Map<String, dynamic> myAnswers = Map<String, dynamic>.from(
      gameData['petitBacAnswers']?[playerId] ?? {},
    );
    Map<String, dynamic> submittedPlayers = Map<String, dynamic>.from(
      gameData['petitBacSubmittedPlayers'] ?? {},
    );
    int roundTime = gameData['turnTimerSeconds'] ?? 120;
    Timestamp? roundStartTime = gameData['petitBacRoundStartTime'];

    int secondsRemaining = roundTime;
    if (roundStartTime != null) {
      secondsRemaining = max(
        0,
        roundTime -
            DateTime.now().difference(roundStartTime.toDate()).inSeconds,
      );
    }

    // Décoration style "Tableau noir"
    final BoxDecoration blackboardDecoration = BoxDecoration(
      color: Color(0xFF2F3E2F), // Vert foncé tableau
      borderRadius: BorderRadius.circular(12),
      border: Border.all(color: Color(0xFF8D6E63), width: 8), // Cadre en bois
      boxShadow: [
        BoxShadow(color: Colors.black54, blurRadius: 10, offset: Offset(0, 4)),
      ],
    );

    final TextStyle chalkStyle = TextStyle(
      color: Colors.white.withOpacity(0.9),
      fontFamily: 'Courier', // Police monospaced simple
      fontSize: 16,
      fontWeight: FontWeight.bold,
    );

    if (roundState == 'waiting_for_categories') {
      TextEditingController categoryController = TextEditingController();
      List<String> currentCategories = List.from(categories);

      return Column(
        children: [
          Text(
            "Tour ${gameData['currentRound']}",
            style: Theme.of(context).textTheme.bodyMedium,
          ),
          SizedBox(height: 10),
          Text(
            "Choisissez les catégories :",
            style: Theme.of(context).textTheme.headlineSmall,
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 10),
          if (isHost)
            Expanded(
              child: Column(
                children: [
                  Expanded(
                    child: ListView.builder(
                      itemCount: currentCategories.length,
                      itemBuilder: (context, index) {
                        final cat = currentCategories[index];
                        return Card(
                          child: ListTile(
                            title: Text(cat),
                            trailing: IconButton(
                              icon: Icon(
                                Icons.remove_circle,
                                color: Colors.redAccent,
                              ),
                              onPressed: () {
                                setState(() {
                                  currentCategories.removeAt(index);
                                });
                              },
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                  SizedBox(height: 10),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: categoryController,
                          decoration: InputDecoration(
                            labelText: "Ajouter une catégorie",
                          ),
                        ),
                      ),
                      IconButton(
                        icon: Icon(Icons.add_circle, color: Colors.greenAccent),
                        onPressed: () {
                          if (categoryController.text.trim().isNotEmpty &&
                              !currentCategories.contains(
                                categoryController.text.trim(),
                              )) {
                            setState(() {
                              currentCategories.add(
                                categoryController.text.trim(),
                              );
                              categoryController.clear();
                            });
                          }
                        },
                      ),
                    ],
                  ),
                  SizedBox(height: 20),

                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              if (currentCategories.isNotEmpty) {
                                setState(() => _isActionPending = true);
                                _firebaseService
                                    .submitPetitBacCategories(
                                      widget.gameCode,
                                      currentCategories,
                                    )
                                    .whenComplete(() {
                                      if (mounted)
                                        setState(
                                          () => _isActionPending = false,
                                        );
                                    });
                              } else {
                                ScaffoldMessenger.of(context).showSnackBar(
                                  SnackBar(
                                    content: Text(
                                      "Veuillez choisir au moins une catégorie.",
                                    ),
                                  ),
                                );
                              }
                            },
                    child:
                        _isActionPending
                            ? SizedBox(
                              height: 20,
                              width: 20,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            )
                            : Text("Valider les catégories"),
                  ),
                ],
              ),
            )
          else
            Text(
              "En attente de l'hôte...",
              style: TextStyle(
                fontStyle: FontStyle.italic,
                color: Colors.white70,
              ),
            ),
        ],
      );
    } else if (roundState == 'answering') {
      for (String category in categories) {
        if (!_answerControllers.containsKey(category)) {
          _answerControllers[category] = TextEditingController(
            text: myAnswers[category] ?? '',
          );
        }
      }

      bool hasSubmitted = submittedPlayers.containsKey(playerId);

      return Column(
        children: [
          // En-tête Tableau
          Container(
            padding: EdgeInsets.symmetric(vertical: 10, horizontal: 20),
            decoration: blackboardDecoration.copyWith(
              borderRadius: BorderRadius.vertical(
                top: Radius.circular(12),
                bottom: Radius.circular(12),
              ),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      "Tour ${gameData['currentRound']}",
                      style: chalkStyle.copyWith(
                        fontSize: 14,
                        color: Colors.white70,
                      ),
                    ),
                    Text(
                      "Lettre : $currentLetter",
                      style: chalkStyle.copyWith(
                        fontSize: 32,
                        color: Colors.yellowAccent,
                      ),
                    ),
                  ],
                ),
                Container(
                  padding: EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    border: Border.all(color: Colors.white30, width: 2),
                  ),
                  child:
                      (roundStartTime != null)
                          ? TweenAnimationBuilder<Duration>(
                            duration:
                                (() {
                                  final diff = roundStartTime
                                      .toDate()
                                      .add(Duration(seconds: roundTime))
                                      .difference(DateTime.now());
                                  return diff.isNegative ? Duration.zero : diff;
                                })(),
                            tween: Tween(
                              begin:
                                  (() {
                                    final diff = roundStartTime
                                        .toDate()
                                        .add(Duration(seconds: roundTime))
                                        .difference(DateTime.now());
                                    return diff.isNegative
                                        ? Duration.zero
                                        : diff;
                                  })(),
                              end: Duration.zero,
                            ),
                            builder: (
                              BuildContext context,
                              Duration value,
                              Widget? child,
                            ) {
                              final secs = value.inSeconds;
                              return Text(
                                "$secs",
                                style: chalkStyle.copyWith(
                                  fontSize: 20,
                                  color:
                                      secs < 30
                                          ? Colors.redAccent
                                          : Colors.white,
                                ),
                              );
                            },
                          )
                          : Text(
                            "...",
                            style: chalkStyle.copyWith(
                              fontSize: 20,
                              color: Colors.white,
                            ),
                          ),
                ),
              ],
            ),
          ),

          SizedBox(height: 10),

          Expanded(
            child:
                hasSubmitted
                    ? Center(
                      child: _buildWaitingWidget(
                        "Copies ramassées ! Attente de la sonnerie...",
                        players,
                        submittedPlayers.length,
                        players.length,
                      ),
                    )
                    : Container(
                      decoration: BoxDecoration(
                        color: Colors.white, // Feuille de papier
                        borderRadius: BorderRadius.circular(8),
                        boxShadow: [
                          BoxShadow(color: Colors.black26, blurRadius: 5),
                        ],
                      ),
                      child: ListView.separated(
                        padding: EdgeInsets.all(16),
                        itemCount: categories.length,
                        separatorBuilder:
                            (ctx, i) => Divider(
                              color: Colors.blue[100],
                              thickness: 1,
                            ), // Lignes de cahier
                        itemBuilder: (context, index) {
                          String category = categories[index];
                          return Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                category.toUpperCase(),
                                style: TextStyle(
                                  color: Colors.grey[600],
                                  fontSize: 12,
                                  fontWeight: FontWeight.bold,
                                ),
                              ),
                              TextField(
                                controller: _answerControllers[category],
                                style: TextStyle(
                                  color: Colors.indigo[900],
                                  fontSize: 18,
                                  fontFamily: 'Courier',
                                ), // Style écriture
                                decoration: InputDecoration(
                                  hintText: "$currentLetter...",
                                  hintStyle: TextStyle(color: Colors.grey[300]),
                                  border: InputBorder.none,
                                  isDense: true,
                                  contentPadding: EdgeInsets.symmetric(
                                    vertical: 8,
                                  ),
                                ),
                                onChanged: (value) {
                                  _firebaseService.submitPetitBacAnswer(
                                    widget.gameCode,
                                    playerId,
                                    category,
                                    value,
                                  );
                                },
                              ),
                            ],
                          );
                        },
                      ),
                    ),
          ),

          SizedBox(height: 10),

          if (!hasSubmitted)
            ElevatedButton.icon(
              icon: Icon(Icons.check),
              label: Text("J'ai fini !"),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.green[700],
                padding: EdgeInsets.symmetric(vertical: 12, horizontal: 24),
                textStyle: TextStyle(fontSize: 18),
              ),
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .endPetitBacTurn(widget.gameCode, playerId)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
            ),
        ],
      );
    } else if (roundState == 'round_results') {
      Map<String, dynamic> petitBacRoundScores = Map<String, dynamic>.from(
        gameData['petitBacRoundScores'] ?? {},
      );
      Map<String, dynamic> allPlayerAnswers = Map<String, dynamic>.from(
        gameData['petitBacAnswers'] ?? {},
      );

      List<String> sortedPlayersThisRound =
          petitBacRoundScores.keys.toList()..sort(
            (a, b) => (petitBacRoundScores[b] ?? 0).compareTo(
              petitBacRoundScores[a] ?? 0,
            ),
          );

      return Column(
        children: [
          Container(
            width: double.infinity,
            padding: EdgeInsets.all(16),
            decoration: blackboardDecoration,
            child: Column(
              children: [
                Text(
                  "CORRECTION",
                  style: chalkStyle.copyWith(
                    fontSize: 24,
                    decoration: TextDecoration.underline,
                  ),
                ),
                SizedBox(height: 5),
                Text("Lettre : $currentLetter", style: chalkStyle),
              ],
            ),
          ),
          SizedBox(height: 10),
          Expanded(
            child: ListView.builder(
              itemCount: categories.length,
              itemBuilder: (context, catIndex) {
                String category = categories[catIndex];
                return Card(
                  margin: EdgeInsets.symmetric(vertical: 5),
                  elevation: 3,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: ExpansionTile(
                    title: Text(
                      category,
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        color: Colors.deepPurple,
                      ),
                    ),
                    initiallyExpanded: true,
                    children:
                        sortedPlayersThisRound.map((pId) {
                          String playerName =
                              players[pId]?['name'] ?? 'Inconnu';
                          String answer =
                              (allPlayerAnswers[pId]?[category] ?? '')
                                  .toString()
                                  .trim();
                          bool isValid =
                              answer.toUpperCase().startsWith(currentLetter) &&
                              answer.isNotEmpty;

                          int uniquenessCount = 0;
                          for (String otherPId in allPlayerAnswers.keys) {
                            if (allPlayerAnswers[otherPId]?[category]
                                        ?.toString()
                                        .trim()
                                        .toLowerCase() ==
                                    answer.toLowerCase() &&
                                answer.isNotEmpty) {
                              uniquenessCount++;
                            }
                          }

                          Color scoreColor = Colors.grey;
                          String scoreText = "0";
                          IconData scoreIcon = Icons.close;

                          if (isValid) {
                            if (uniquenessCount == 1) {
                              scoreColor = Colors.green;
                              scoreText = "+10";
                              scoreIcon = Icons.star;
                            } else {
                              scoreColor = Colors.orange;
                              scoreText = "+5";
                              scoreIcon = Icons.check;
                            }
                          }

                          return Container(
                            color:
                                isValid
                                    ? Colors.transparent
                                    : Colors.red.withOpacity(0.05),
                            child: ListTile(
                              dense: true,
                              leading: CircleAvatar(
                                radius: 12,
                                backgroundColor: scoreColor,
                                child: Icon(
                                  scoreIcon,
                                  size: 14,
                                  color: Colors.white,
                                ),
                              ),
                              title: Text(
                                playerName,
                                style: TextStyle(fontSize: 12),
                              ),
                              subtitle: Text(
                                answer.isEmpty ? "-" : answer,
                                style: TextStyle(
                                  fontWeight: FontWeight.bold,
                                  color: Colors.black87,
                                  fontSize: 14,
                                ),
                              ),
                              trailing: Text(
                                scoreText,
                                style: TextStyle(
                                  color: scoreColor,
                                  fontWeight: FontWeight.bold,
                                  fontSize: 16,
                                ),
                              ),
                            ),
                          );
                        }).toList(),
                  ),
                );
              },
            ),
          ),
          SizedBox(height: 10),
          Container(
            height: 60,
            child: ListView(
              scrollDirection: Axis.horizontal,
              children:
                  sortedPlayersThisRound.map((pId) {
                    return Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 8.0),
                      child: Chip(
                        avatar: CircleAvatar(
                          child: Text("${petitBacRoundScores[pId]}"),
                        ),
                        label: Text(players[pId]?['name'] ?? '...'),
                        backgroundColor: Colors.deepPurple[100],
                      ),
                    );
                  }).toList(),
            ),
          ),
          SizedBox(height: 10),
          if (isHost)
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.green,
                foregroundColor: Colors.white,
              ),
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .nextPetitBacRound(widget.gameCode)
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
              child:
                  _isActionPending
                      ? SizedBox(
                        height: 20,
                        width: 20,
                        child: CircularProgressIndicator(
                          color: Colors.white,
                          strokeWidth: 2,
                        ),
                      )
                      : Text("Prochain Tour"),
            ),
        ],
      );
    }
    return _buildWaitingWidget("Chargement...", players, 0, 0);
  }

  Widget _buildPresidentUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final gameState = gameData['gameState'];
    final isHost = gameData['hostId'] == playerId;
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'],
    );
    final Map<String, String> ranks = Map<String, String>.from(
      gameData['playerRanks'] ?? {},
    );

    // --- ÉCRAN DE FIN DE MANCHE ---
    if (gameState == 'round_over') {
      List<String> finalRanking = List<String>.from(
        gameData['finishedPlayers'] ?? [],
      );
      var sortedRanks =
          ranks.entries.toList()..sort(
            (a, b) => finalRanking
                .indexOf(a.key)
                .compareTo(finalRanking.indexOf(b.key)),
          );

      return Center(
        child: Card(
          margin: EdgeInsets.all(16),
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Fin de la Manche",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                Divider(),
                Container(
                  height: 300,
                  child: ListView.builder(
                    shrinkWrap: true,
                    itemCount: sortedRanks.length,
                    itemBuilder: (context, index) {
                      var rankEntry = sortedRanks[index];
                      return ListTile(
                        leading: CircleAvatar(child: Text("#${index + 1}")),
                        title: Text(
                          players[rankEntry.key]?['name'] ?? 'Inconnu',
                        ),
                        trailing: Text(
                          rankEntry.value,
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.amber,
                          ),
                        ),
                      );
                    },
                  ),
                ),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .nextPresidentRound(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child: Text("Suite"),
                  )
                else
                  Text("En attente de l'hôte..."),
              ],
            ),
          ),
        ),
      );
    }

    // --- ÉCRAN D'ÉCHANGE ---
    if (gameState == 'card_exchange') {
      List<Map<String, dynamic>> exchangeData = List<Map<String, dynamic>>.from(
        gameData['cardExchangeData'] ?? [],
      );
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Text(
            "Échange des cartes",
            style: Theme.of(context).textTheme.headlineMedium,
          ),
          SizedBox(height: 20),
          ...exchangeData.map((exchange) {
            String fromName = players[exchange['from']]?['name'] ?? '...';
            String toName = players[exchange['to']]?['name'] ?? '...';
            List<String> cards = List<String>.from(exchange['cards']);

            return Card(
              child: Padding(
                padding: EdgeInsets.all(12),
                child: Column(
                  children: [
                    Text("$fromName donne à $toName :"),
                    SizedBox(height: 10),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children:
                          cards
                              .map(
                                (c) => _buildCard(
                                  card: c,
                                  isSelected: false,
                                  scale: 0.8,
                                ),
                              )
                              .toList(),
                    ),
                  ],
                ),
              ),
            );
          }).toList(),
          SizedBox(height: 30),
          if (isHost)
            ElevatedButton(
              onPressed:
                  _isActionPending
                      ? null
                      : () {
                        setState(() => _isActionPending = true);
                        _firebaseService
                            .startNextPresidentRoundAfterExchange(
                              widget.gameCode,
                            )
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      },
              child: Text("Commencer"),
            ),
        ],
      );
    }

    // --- JEU ACTIF ---
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final int currentPlayerIndex = gameData['currentPlayerIndex'] ?? 0;
    final String currentPlayerId =
        playerOrder.isNotEmpty ? playerOrder[currentPlayerIndex] : '';
    final bool isMyTurn = currentPlayerId == playerId;
    final bool isRevolutionActive = gameData['isRevolutionActive'] ?? false;
    final Map<String, dynamic> hands = Map<String, dynamic>.from(
      gameData['playerHands'] ?? {},
    );
    final List<String> myHand = List<String>.from(hands[playerId] ?? []);
    final Map<String, dynamic>? lastPlay =
        gameData['lastPlay'] != null ? Map.from(gameData['lastPlay']) : null;
    final List<String> finishedPlayers = List<String>.from(
      gameData['finishedPlayers'] ?? [],
    );

    String instructionText =
        isMyTurn
            ? "À vous de jouer !"
            : "Au tour de ${players[currentPlayerId]?['name']}";
    if (isRevolutionActive) instructionText += " (Révolution !)";

    // Validation locale pour activer/désactiver le bouton
    bool isPlayValid() {
      if (_selectedPresidentCards.isEmpty) return false;
      // (Ici vous pouvez remettre votre logique de validation complète présente dans votre code original)
      // Pour l'UI, on simplifie : s'il a sélectionné quelque chose, le bouton s'active, le backend vérifiera.
      return true;
    }

    return Column(
      children: [
        // 1. Info & Révolution
        Container(
          padding: EdgeInsets.symmetric(vertical: 8, horizontal: 16),
          decoration: BoxDecoration(
            color:
                isRevolutionActive
                    ? Colors.redAccent.withOpacity(0.2)
                    : Colors.black26,
            borderRadius: BorderRadius.circular(20),
          ),
          child: Text(
            instructionText,
            style: TextStyle(
              fontSize: 18,
              fontWeight: FontWeight.bold,
              color: isMyTurn ? Colors.greenAccent : Colors.white,
            ),
          ),
        ),

        SizedBox(height: 10),

        // 2. Adversaires (Chips)
        SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children:
                playerOrder.map((pId) {
                  if (pId == playerId) return SizedBox.shrink(); // Pas moi
                  bool isCurrent = pId == currentPlayerId;
                  bool isFinished = finishedPlayers.contains(pId);
                  int cardCount = (hands[pId] as List?)?.length ?? 0;

                  return Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4.0),
                    child: Chip(
                      avatar: CircleAvatar(
                        backgroundColor: isCurrent ? Colors.green : Colors.grey,
                        child: Text(
                          "$cardCount",
                          style: TextStyle(color: Colors.white),
                        ),
                      ),
                      label: Text(players[pId]?['name'] ?? '...'),
                      backgroundColor:
                          isFinished
                              ? Colors.grey[800]
                              : (isCurrent
                                  ? Colors.green[900]
                                  : Colors.black45),
                    ),
                  );
                }).toList(),
          ),
        ),

        Spacer(),

        // 3. TABLE CENTRALE
        Container(
          height: 140,
          width: double.infinity,
          alignment: Alignment.center,
          child:
              lastPlay == null
                  ? Container(
                    width: 60,
                    height: 90,
                    decoration: BoxDecoration(
                      border: Border.all(color: Colors.white12),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Center(
                      child: Text(
                        "Vide",
                        style: TextStyle(color: Colors.white24),
                      ),
                    ),
                  )
                  : Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children:
                        (lastPlay['cards'] as List).map((card) {
                          return Padding(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 4.0,
                            ),
                            child: _buildCard(
                              card: card,
                              isSelected: false,
                              scale: 1.2,
                            ),
                          );
                        }).toList(),
                  ),
        ),

        Spacer(),

        // 4. MAIN DU JOUEUR (ÉVENTAIL + SÉLECTION)
        if (finishedPlayers.contains(playerId))
          Text(
            "Vous avez fini !",
            style: TextStyle(fontSize: 24, color: Colors.amber),
          )
        else
          _buildHandFan(
            cards: myHand,
            isSelectedPredicate:
                (card) => _selectedPresidentCards.contains(card),
            onCardTap: (card) {
              if (!isMyTurn) return;
              setState(() {
                if (_selectedPresidentCards.contains(card)) {
                  _selectedPresidentCards.remove(card);
                } else {
                  // Logique : si on clique sur un autre rang, on change la sélection
                  if (_selectedPresidentCards.isNotEmpty) {
                    // On récupère le rang de la première carte sélectionnée
                    String currentRank = _selectedPresidentCards.first
                        .substring(0, _selectedPresidentCards.first.length - 1);
                    String newRank = card.substring(0, card.length - 1);

                    if (currentRank != newRank) {
                      _selectedPresidentCards.clear();
                    }
                  }
                  _selectedPresidentCards.add(card);
                }
              });
            },
          ),

        SizedBox(height: 20),

        // 5. ACTION BAR
        if (isMyTurn && !finishedPlayers.contains(playerId))
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: [
              ElevatedButton.icon(
                icon: Icon(Icons.skip_next),
                label: Text("Passer"),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.grey[700],
                  padding: EdgeInsets.symmetric(horizontal: 30, vertical: 15),
                ),
                onPressed:
                    _isActionPending
                        ? null
                        : () {
                          setState(() {
                            _isActionPending = true;
                            _selectedPresidentCards.clear();
                          });
                          _firebaseService
                              .passPresidentTurn(widget.gameCode, playerId)
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        },
              ),
              ElevatedButton.icon(
                icon: Icon(Icons.play_arrow),
                label: Text("JOUER (${_selectedPresidentCards.length})"),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.green[700],
                  padding: EdgeInsets.symmetric(horizontal: 30, vertical: 15),
                ),
                onPressed:
                    isPlayValid() && !_isActionPending
                        ? () {
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .playPresidentCards(
                                widget.gameCode,
                                playerId,
                                List.from(_selectedPresidentCards),
                              )
                              .then((_) {
                                if (mounted)
                                  setState(
                                    () => _selectedPresidentCards.clear(),
                                  );
                              })
                              .catchError((e) {
                                if (mounted)
                                  ScaffoldMessenger.of(context).showSnackBar(
                                    SnackBar(content: Text("Coup invalide !")),
                                  );
                              })
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                        }
                        : null,
              ),
            ],
          )
        else
          SizedBox(height: 50), // Espace réservé
      ],
    );
  }

  // --- 1. WIDGET CARTE AMÉLIORÉ ET CORRIGÉ ---
  Widget _buildCard({
    required String card,
    required bool isSelected,
    Function()? onTap,
    double scale = 1.0,
    double rotation = 0.0,
  }) {
    // Extraction des données
    String suit = "";
    String rank = "";
    bool isUno = card.contains('-');

    if (isUno) {
      suit = GameData.getUnoCardColor(card);
      rank = GameData.getUnoCardValue(card);
    } else {
      suit = card.substring(card.length - 1);
      rank = card.substring(0, card.length - 1);
    }

    // Couleurs
    Color cardBaseColor = Colors.white;
    Color textColor = Colors.black;
    Color borderColor = Colors.grey[300]!;

    if (isUno) {
      // Pour UNO
      switch (suit) {
        case 'red':
          cardBaseColor = Colors.red;
          break;
        case 'yellow':
          cardBaseColor = Colors.yellow;
          break;
        case 'green':
          cardBaseColor = Colors.green;
          break;
        case 'blue':
          cardBaseColor = Colors.blue;
          break;
        case 'wild':
          cardBaseColor = Colors.black;
          break;
        default:
          cardBaseColor = Colors.grey;
          break;
      }

      if (suit == 'yellow' || suit == 'wild')
        textColor = Colors.black;
      else
        textColor = Colors.white;

      borderColor = Colors.white24;

      switch (rank) {
        case 'skip':
          rank = '🚫';
          break;
        case 'reverse':
          rank = '🔄';
          break;
        case 'draw2':
          rank = '+2';
          break;
        case 'wild':
          rank = '🌈';
          break;
        case 'wild_draw4':
          rank = '+4';
          break;
      }
    } else {
      // Pour les cartes classiques
      if (suit == 'D' || suit == 'H')
        textColor = Colors.red[800]!;
      else
        textColor = Colors.black;

      switch (suit) {
        case 'H':
          suit = '♥';
          break;
        case 'D':
          suit = '♦';
          break;
        case 'C':
          suit = '♣';
          break;
        case 'S':
          suit = '♠';
          break;
      }
    }

    return GestureDetector(
      onTap: onTap,
      child: Transform.rotate(
        angle: rotation,
        child: AnimatedContainer(
          duration: Duration(milliseconds: 200),
          curve: Curves.easeOutBack,
          transform:
              Matrix4.identity()
                ..translate(
                  0.0,
                  isSelected ? -30.0 : 0.0,
                ) // La carte monte si sélectionnée
                ..scale(isSelected ? 1.1 : 1.0),
          margin: EdgeInsets.all(4.0),
          width: 70 * scale,
          height: 105 * scale,
          decoration: BoxDecoration(
            color: cardBaseColor,
            borderRadius: BorderRadius.circular(8 * scale),
            border: Border.all(color: borderColor, width: 1.5),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withOpacity(0.3),
                blurRadius: isSelected ? 12 : 4,
                offset: isSelected ? Offset(0, 8) : Offset(0, 2),
              ),
            ],
          ),
          child: Stack(
            children: [
              // Valeur centrale
              Center(
                child: Text(
                  rank,
                  style: TextStyle(
                    fontSize: 28 * scale,
                    fontWeight: FontWeight.bold,
                    color: textColor,
                  ),
                ),
              ),
              // Coin haut gauche
              Positioned(
                top: 4,
                left: 4,
                child: Column(
                  children: [
                    Text(
                      rank,
                      style: TextStyle(
                        fontSize: 12 * scale,
                        fontWeight: FontWeight.bold,
                        color: textColor,
                      ),
                    ),
                    // Afficher le symbole seulement si ce n'est pas une carte Uno
                    if (!isUno)
                      Text(
                        suit,
                        style: TextStyle(
                          fontSize: 12 * scale,
                          color: textColor,
                        ),
                      ),
                  ],
                ),
              ),
              // Coin bas droit (inversé)
              Positioned(
                bottom: 4,
                right: 4,
                child: Transform.rotate(
                  angle: pi,
                  child: Column(
                    children: [
                      Text(
                        rank,
                        style: TextStyle(
                          fontSize: 12 * scale,
                          fontWeight: FontWeight.bold,
                          color: textColor,
                        ),
                      ),
                      if (!isUno)
                        Text(
                          suit,
                          style: TextStyle(
                            fontSize: 12 * scale,
                            color: textColor,
                          ),
                        ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  // --- 2. MAIN EN ÉVENTAIL (FAN) ---
  // --- 2. MAIN EN ÉVENTAIL (FAN) ---
  Widget _buildHandFan({
    required List<String> cards,
    required Function(String) onCardTap,
    required bool Function(String) isSelectedPredicate,
  }) {
    if (cards.isEmpty)
      return SizedBox(
        height: 120,
        child: Center(child: Text("Plus de cartes !")),
      );

    return Container(
      height: 160, // Espace suffisant pour l'animation
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        padding: EdgeInsets.symmetric(horizontal: 20),
        child: Container(
          height: 160,
          // On utilise un Stack ou un Row avec largeur négative pour l'effet éventail
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.end,
            mainAxisAlignment: MainAxisAlignment.center,
            children:
                cards.asMap().entries.map((entry) {
                  int index = entry.key;
                  String card = entry.value;
                  bool isSelected = isSelectedPredicate(card);

                  // Calcul de l'angle pour l'effet éventail (subtil)
                  // On peut complexifier, mais un simple Row avec chevauchement fait l'affaire ici
                  // Pour un vrai éventail courbe, il faudrait un Stack et du calcul trigo.
                  // Restons simple mais joli : chevauchement.

                  return Align(
                    widthFactor: 0.6, // Les cartes se chevauchent à 40%
                    alignment: Alignment.bottomCenter,
                    child: _buildCard(
                      card: card,
                      isSelected: isSelected,
                      onTap: () => onCardTap(card),
                      scale: 1.1, // Cartes un peu plus grandes en main
                      rotation:
                          0.0, // On garde droit pour la lisibilité, ou index * 0.05 pour courbe
                    ),
                  );
                }).toList(),
          ),
        ),
      ),
    );
  }

  // Dans _MultiplayerGameScreenState

  Future<int?> _askSkullBid(
    BuildContext context, {
    required int minimumBid,
    required int maximumBid,
  }) async {
    final TextEditingController bidController = TextEditingController(
      text: minimumBid.toString(),
    );

    return showDialog<int>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          title: Text("Annoncer un défi"),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text("Choisissez un nombre entre $minimumBid et $maximumBid."),
              SizedBox(height: 12),
              TextField(
                controller: bidController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(labelText: "Nombre de cartes"),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(),
              child: Text("Annuler"),
            ),
            ElevatedButton(
              onPressed: () {
                final int? bid = int.tryParse(bidController.text.trim());
                if (bid == null) return;
                Navigator.of(dialogContext).pop(bid);
              },
              child: Text("Valider"),
            ),
          ],
        );
      },
    );
  }

  Widget _buildSkullUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? players.keys.toList(),
    );
    final Map<String, dynamic> skullHands = Map<String, dynamic>.from(
      gameData['skullHands'] ?? {},
    );
    final Map<String, dynamic> skullMats = Map<String, dynamic>.from(
      gameData['skullMats'] ?? {},
    );
    final int currentPlayerIndex = gameData['skullCurrentPlayerIndex'] ?? 0;
    final String? currentPlayerId =
        playerOrder.isNotEmpty && currentPlayerIndex < playerOrder.length
            ? playerOrder[currentPlayerIndex]
            : null;
    final String roundState = gameData['roundState'] ?? 'placing';
    final int currentBid = gameData['skullCurrentBid'] ?? 0;
    final String? highestBidderId = gameData['skullHighestBidderId'];
    final List<String> passedPlayers = List<String>.from(
      gameData['skullPassedPlayers'] ?? [],
    );
    final String? lastOutcome = gameData['skullLastChallengeOutcome'];
    final int lastBid = gameData['skullLastChallengeBid'] ?? 0;
    final List<dynamic> revealedCards = List<dynamic>.from(
      gameData['skullLastChallengeRevealed'] ?? [],
    );
    final bool isMyTurn = currentPlayerId == playerId;
    final List<String> myHand = List<String>.from(skullHands[playerId] ?? []);
    final List<Map<String, dynamic>> myMat = List<Map<String, dynamic>>.from(
      (skullMats[playerId] as List? ?? []).map(
        (card) => Map<String, dynamic>.from(card as Map),
      ),
    );
    final int totalCardsOnTables = skullMats.values.fold<int>(0, (sum, cards) {
      return sum + (cards is List ? cards.length : 0);
    });

    Widget buildPlayerMat(String ownerId) {
      final List<Map<String, dynamic>> mat = List<Map<String, dynamic>>.from(
        (skullMats[ownerId] as List? ?? []).map(
          (card) => Map<String, dynamic>.from(card as Map),
        ),
      );
      final int hiddenCount =
          mat.where((card) => card['revealed'] != true).length;
      final int revealedCount = mat.length - hiddenCount;
      final bool isMe = ownerId == playerId;
      final String ownerName = players[ownerId]?['name'] ?? 'Joueur';

      return Card(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  CircleAvatar(
                    radius: 14,
                    child: Text(ownerName.isNotEmpty ? ownerName[0] : '?'),
                  ),
                  SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      ownerName,
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                  ),
                  Text(
                    "${players[ownerId]?['score'] ?? 0} défi(s)",
                    style: TextStyle(color: Colors.amberAccent),
                  ),
                ],
              ),
              SizedBox(height: 8),
              Text(
                isMe
                    ? "Votre tapis"
                    : "$hiddenCount carte${hiddenCount > 1 ? 's' : ''} cachée${hiddenCount > 1 ? 's' : ''}",
                style: TextStyle(color: Colors.white70),
              ),
              if (revealedCount > 0)
                Text(
                  "$revealedCount carte${revealedCount > 1 ? 's' : ''} révélée${revealedCount > 1 ? 's' : ''}",
                  style: TextStyle(color: Colors.greenAccent),
                ),
              if (isMe && mat.isNotEmpty)
                Padding(
                  padding: const EdgeInsets.only(top: 8.0),
                  child: Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children:
                        mat
                            .map(
                              (card) => Chip(
                                label: Text(
                                  card['type'] == 'Crane' ? 'Crâne' : 'Rose',
                                ),
                                backgroundColor:
                                    card['type'] == 'Crane'
                                        ? Colors.redAccent.withOpacity(0.25)
                                        : Colors.greenAccent.withOpacity(0.2),
                              ),
                            )
                            .toList(),
                  ),
                ),
            ],
          ),
        ),
      );
    }

    if (roundState == 'result') {
      return _buildResultUI(context, gameData, playerId);
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
          padding: EdgeInsets.only(
            bottom: MediaQuery.of(context).viewInsets.bottom + 16,
          ),
          child: ConstrainedBox(
            constraints: BoxConstraints(minHeight: constraints.maxHeight),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16.0),
                    child: Column(
                      children: [
                        Text(
                          roundState == 'bidding'
                              ? 'Phase d\'enchère'
                              : 'Phase de pose',
                          style: Theme.of(context).textTheme.titleLarge,
                        ),
                        SizedBox(height: 6),
                        Text(
                          currentPlayerId != null
                              ? "Au tour de ${players[currentPlayerId]?['name'] ?? 'un joueur'}"
                              : "En attente...",
                          style: TextStyle(color: Colors.white70),
                        ),
                        SizedBox(height: 6),
                        Text(
                          "Tapis en jeu : $totalCardsOnTables",
                          style: TextStyle(color: Colors.amberAccent),
                        ),
                      ],
                    ),
                  ),
                ),
                SizedBox(height: 12),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children:
                      playerOrder.map((pId) {
                        final bool active = players[pId]?['isOut'] != true;
                        final int handCount =
                            players[pId]?['cardsInHand'] ??
                            (List.from(skullHands[pId] ?? [])).length;
                        return Chip(
                          label: Text(
                            '${players[pId]?['name'] ?? 'Joueur'}${active ? '' : ' (éliminé)'} : $handCount',
                          ),
                          backgroundColor:
                              pId == currentPlayerId
                                  ? Colors.deepPurple
                                  : Colors.white12,
                        );
                      }).toList(),
                ),
                SizedBox(height: 12),
                ...playerOrder.map(buildPlayerMat),
                SizedBox(height: 12),
                if (roundState == 'placing' && isMyTurn) ...[
                  Card(
                    color: Colors.black.withOpacity(0.25),
                    child: Padding(
                      padding: const EdgeInsets.all(16.0),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            'Votre main',
                            style: Theme.of(context).textTheme.titleLarge,
                            textAlign: TextAlign.center,
                          ),
                          SizedBox(height: 12),
                          if (myHand.isEmpty)
                            Text(
                              'Vous n\'avez plus de carte à poser.',
                              textAlign: TextAlign.center,
                              style: TextStyle(color: Colors.white70),
                            )
                          else
                            Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              alignment: WrapAlignment.center,
                              children:
                                  myHand
                                      .map(
                                        (card) => ElevatedButton(
                                          onPressed:
                                              _isActionPending
                                                  ? null
                                                  : () {
                                                    setState(
                                                      () =>
                                                          _isActionPending =
                                                              true,
                                                    );
                                                    _firebaseService
                                                        .placeSkullCard(
                                                          widget.gameCode,
                                                          playerId,
                                                          card,
                                                        )
                                                        .whenComplete(() {
                                                          if (mounted) {
                                                            setState(
                                                              () =>
                                                                  _isActionPending =
                                                                      false,
                                                            );
                                                          }
                                                        });
                                                  },
                                          style: ElevatedButton.styleFrom(
                                            backgroundColor:
                                                card == 'Crane'
                                                    ? Colors.redAccent
                                                    : Colors.green,
                                          ),
                                          child: Text(
                                            card == 'Crane'
                                                ? 'Poser Crâne'
                                                : 'Poser Rose',
                                          ),
                                        ),
                                      )
                                      .toList(),
                            ),
                          SizedBox(height: 12),
                          ElevatedButton.icon(
                            icon: Icon(Icons.casino),
                            label: Text('Lancer le défi'),
                            onPressed:
                                _isActionPending || totalCardsOnTables < 1
                                    ? null
                                    : () async {
                                      final int? bid = await _askSkullBid(
                                        context,
                                        minimumBid: 1,
                                        maximumBid: max(1, totalCardsOnTables),
                                      );
                                      if (bid == null) return;
                                      setState(() => _isActionPending = true);
                                      _firebaseService
                                          .startSkullBid(
                                            widget.gameCode,
                                            playerId,
                                            bid,
                                          )
                                          .whenComplete(() {
                                            if (mounted) {
                                              setState(
                                                () => _isActionPending = false,
                                              );
                                            }
                                          });
                                    },
                          ),
                        ],
                      ),
                    ),
                  ),
                ] else if (roundState == 'bidding' && isMyTurn) ...[
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(16.0),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            'Enchère actuelle : $currentBid',
                            style: Theme.of(context).textTheme.titleLarge,
                            textAlign: TextAlign.center,
                          ),
                          SizedBox(height: 6),
                          Text(
                            highestBidderId != null
                                ? "Meilleur enchérisseur : ${players[highestBidderId]?['name'] ?? 'Joueur'}"
                                : 'Aucune enchère',
                            textAlign: TextAlign.center,
                            style: TextStyle(color: Colors.white70),
                          ),
                          SizedBox(height: 12),
                          if (passedPlayers.isNotEmpty)
                            Text(
                              'Joueurs passés : ${passedPlayers.map((pId) => players[pId]?['name'] ?? pId).join(', ')}',
                              textAlign: TextAlign.center,
                              style: TextStyle(color: Colors.white60),
                            ),
                          SizedBox(height: 12),
                          Wrap(
                            alignment: WrapAlignment.center,
                            spacing: 12,
                            runSpacing: 12,
                            children: [
                              ElevatedButton(
                                onPressed:
                                    _isActionPending
                                        ? null
                                        : () {
                                          setState(
                                            () => _isActionPending = true,
                                          );
                                          _firebaseService
                                              .passSkullBid(
                                                widget.gameCode,
                                                playerId,
                                              )
                                              .whenComplete(() {
                                                if (mounted) {
                                                  setState(
                                                    () =>
                                                        _isActionPending =
                                                            false,
                                                  );
                                                }
                                              });
                                        },
                                child: Text('Passer'),
                              ),
                              ElevatedButton.icon(
                                icon: Icon(Icons.trending_up),
                                label: Text('Surenchérir'),
                                onPressed:
                                    _isActionPending ||
                                            currentBid >= totalCardsOnTables
                                        ? null
                                        : () async {
                                          final int? bid = await _askSkullBid(
                                            context,
                                            minimumBid: currentBid + 1,
                                            maximumBid: totalCardsOnTables,
                                          );
                                          if (bid == null) return;
                                          setState(
                                            () => _isActionPending = true,
                                          );
                                          _firebaseService
                                              .raiseSkullBid(
                                                widget.gameCode,
                                                playerId,
                                                bid,
                                              )
                                              .whenComplete(() {
                                                if (mounted) {
                                                  setState(
                                                    () =>
                                                        _isActionPending =
                                                            false,
                                                  );
                                                }
                                              });
                                        },
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                ] else if (roundState == 'placing') ...[
                  _buildWaitingWidget(
                    currentPlayerId == playerId
                        ? 'Choisissez une carte ou lancez un défi.'
                        : 'En attente de ${players[currentPlayerId]?['name'] ?? 'un joueur'}...',
                    players,
                    0,
                    0,
                  ),
                ] else if (roundState == 'bidding') ...[
                  _buildWaitingWidget(
                    currentPlayerId == playerId
                        ? 'À vous de surenchérir ou de passer.'
                        : 'En attente de ${players[currentPlayerId]?['name'] ?? 'un joueur'}...',
                    players,
                    0,
                    0,
                  ),
                ],
                if (lastOutcome != null && revealedCards.isNotEmpty)
                  Card(
                    child: Padding(
                      padding: const EdgeInsets.all(16.0),
                      child: Column(
                        children: [
                          Text(
                            lastOutcome == 'won'
                                ? 'Défi réussi !'
                                : 'Défi perdu !',
                            style: Theme.of(context).textTheme.titleLarge,
                          ),
                          SizedBox(height: 8),
                          Text('Dernier défi : $lastBid carte(s)'),
                          SizedBox(height: 8),
                          Wrap(
                            spacing: 8,
                            runSpacing: 8,
                            children:
                                revealedCards.map((card) {
                                  final ownerName =
                                      players[card['ownerId']]?['name'] ??
                                      'Joueur';
                                  return Chip(
                                    label: Text(
                                      '$ownerName : ${card['type'] == 'Crane' ? 'Crâne' : 'Rose'}',
                                    ),
                                    backgroundColor:
                                        card['type'] == 'Crane'
                                            ? Colors.redAccent.withOpacity(0.3)
                                            : Colors.greenAccent.withOpacity(
                                              0.2,
                                            ),
                                  );
                                }).toList(),
                          ),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }

  Widget _buildPictionaryUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'setup';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? currentDrawingPlayerId = gameData['currentDrawingPlayerId'];
    final String? currentPictionaryWord = gameData['currentPictionaryWord'];
    final String? pictionaryDrawingData = gameData['pictionaryDrawing'];

    final Timestamp? startTime = gameData['pictionaryStartTime'];
    final int roundDuration =
        (roundState == 'drawing')
            ? (gameData['turnTimerSeconds'] ?? 90)
            : (gameData['resultTimerSeconds'] ?? 30);

    int secondsRemaining = 0;
    if (startTime != null) {
      secondsRemaining = max(
        0,
        roundDuration - DateTime.now().difference(startTime.toDate()).inSeconds,
      );
    }

    final bool pictionaryOnly30Strokes =
        gameData['pictionaryOnly30Strokes'] == true;
    final bool isCollective = gameData['pictionaryTeams'] == true;
    final int collectiveCardIndex =
        (gameData['pictionaryCollectiveCardIndex'] ?? 0) as int;
    final int collectiveGuessed =
        (gameData['pictionaryCollectiveGuessed'] ?? 0) as int;
    final int collectiveTotal =
        (gameData['pictionaryCollectiveWords'] as List?)?.length ?? 13;
    final bool amIDrawingPlayer = playerId == currentDrawingPlayerId;
    final bool drawingBlocked =
        pictionaryOnly30Strokes && _pictionaryStrokeCount >= 30;
    final String drawerName =
        players[currentDrawingPlayerId]?['name'] ?? 'Quelqu\'un';

    if (roundState == 'result') {
      return _buildResultUI(context, gameData, playerId);
    }

    return Column(
      children: [
        // EN-TÊTE AVEC INFO
        Card(
          child: Padding(
            padding: const EdgeInsets.all(8.0),
            child: Column(
              children: [
                if (isCollective) ...[
                  Text(
                    "Mode Collectif",
                    style: Theme.of(
                      context,
                    ).textTheme.bodySmall?.copyWith(color: Colors.white54),
                  ),
                  Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Chip(
                        label: Text(
                          "Carte ${collectiveCardIndex + 1}/$collectiveTotal",
                        ),
                        backgroundColor: Colors.deepPurple,
                        labelStyle: TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.bold,
                        ),
                        visualDensity: VisualDensity.compact,
                      ),
                      SizedBox(width: 8),
                      Chip(
                        label: Text("✅ $collectiveGuessed devinés"),
                        backgroundColor: Colors.green[800],
                        labelStyle: TextStyle(color: Colors.white),
                        visualDensity: VisualDensity.compact,
                      ),
                    ],
                  ),
                  SizedBox(height: 4),
                ],
                if (amIDrawingPlayer) ...[
                  Text(
                    "À TOI DE DESSINER !",
                    style: Theme.of(
                      context,
                    ).textTheme.titleLarge?.copyWith(color: Colors.greenAccent),
                  ),
                  Text(
                    '"${currentPictionaryWord ?? "..."}"',
                    style: Theme.of(context).textTheme.headlineSmall,
                  ),
                ] else ...[
                  Text(
                    "$drawerName est en train de dessiner...",
                    style: Theme.of(context).textTheme.titleLarge,
                  ),
                ],
                SizedBox(height: 8),
                _buildSyncTimer(startTime, roundDuration),
              ],
            ),
          ),
        ),
        SizedBox(height: 10),

        // ZONE DE DESSIN (TABLEAU BLANC)
        Expanded(
          flex: 5,
          child: Container(
            margin: EdgeInsets.symmetric(horizontal: 8),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: Colors.grey[400]!,
                width: 8,
              ), // Cadre épais style tableau
              boxShadow: [
                BoxShadow(
                  color: Colors.black45,
                  blurRadius: 10,
                  offset: Offset(0, 5),
                ),
              ],
            ),
            child: Stack(
              children: [
                // Canvas ou Image
                ClipRRect(
                  borderRadius: BorderRadius.circular(4),
                  child:
                      amIDrawingPlayer
                          ? (pictionaryOnly30Strokes
                              // Mode 30 traits : segments droits uniquement
                              ? RepaintBoundary(
                                key: _straightLineKey,
                                child: GestureDetector(
                                  onPanStart:
                                      drawingBlocked
                                          ? null
                                          : (d) {
                                            setState(
                                              () =>
                                                  _straightLineStart =
                                                      d.localPosition,
                                            );
                                          },
                                  onPanUpdate:
                                      drawingBlocked
                                          ? null
                                          : (d) {
                                            if (_straightLineStart != null) {
                                              setState(
                                                () =>
                                                    _straightLineCurrentEnd =
                                                        d.localPosition,
                                              );
                                            }
                                          },
                                  onPanEnd:
                                      drawingBlocked
                                          ? null
                                          : (d) async {
                                            if (_straightLineStart == null ||
                                                _straightLineCurrentEnd == null)
                                              return;
                                            setState(() {
                                              _straightLinePoints.add(
                                                _straightLineStart!,
                                              );
                                              _straightLinePoints.add(
                                                _straightLineCurrentEnd!,
                                              );
                                              _straightLineStart = null;
                                              _straightLineCurrentEnd = null;
                                              _pictionaryStrokeCount++;
                                            });
                                            // Capture and upload
                                            await Future.delayed(
                                              Duration(milliseconds: 50),
                                            );
                                            if (!mounted) return;
                                            try {
                                              final boundary =
                                                  _straightLineKey
                                                          .currentContext
                                                          ?.findRenderObject()
                                                      as RenderRepaintBoundary?;
                                              if (boundary != null) {
                                                final image = await boundary
                                                    .toImage(pixelRatio: 1.0);
                                                final bytes = await image
                                                    .toByteData(
                                                      format:
                                                          ui
                                                              .ImageByteFormat
                                                              .png,
                                                    );
                                                if (bytes != null && mounted) {
                                                  final base64Image =
                                                      base64Encode(
                                                        bytes.buffer
                                                            .asUint8List(),
                                                      );
                                                  await _firebaseService
                                                      .updatePictionaryDrawing(
                                                        widget.gameCode,
                                                        base64Image,
                                                        _pictionaryStrokeCount,
                                                      );
                                                }
                                              }
                                            } catch (_) {}
                                          },
                                  child: CustomPaint(
                                    foregroundPainter: _StraightLinePainter(
                                      points: _straightLinePoints,
                                      currentStart: _straightLineStart,
                                      currentEnd: _straightLineCurrentEnd,
                                    ),
                                    child: Container(color: Colors.white),
                                  ),
                                ),
                              )
                              // Mode libre : Signature widget
                              : AbsorbPointer(
                                absorbing: drawingBlocked,
                                child: Listener(
                                  onPointerUp: (_) async {
                                    setState(() => _pictionaryStrokeCount++);
                                    if (_pictionaryDrawingController
                                        .isNotEmpty) {
                                      final pngBytes =
                                          await _pictionaryDrawingController
                                              .toPngBytes();
                                      if (pngBytes != null) {
                                        final String base64Image = base64Encode(
                                          pngBytes,
                                        );
                                        await _firebaseService
                                            .updatePictionaryDrawing(
                                              widget.gameCode,
                                              base64Image,
                                              _pictionaryStrokeCount,
                                            );
                                      }
                                    }
                                  },
                                  child: Signature(
                                    controller: _pictionaryDrawingController,
                                    backgroundColor: Colors.white,
                                  ),
                                ),
                              ))
                          // Utilisation de Realtime Database pour éviter le spam de StreamBuilder Firestore
                          : StreamBuilder<DatabaseEvent>(
                            stream:
                                FirebaseDatabase.instance
                                    .ref(
                                      'games/${widget.gameCode}/pictionary/drawing',
                                    )
                                    .onValue,
                            builder: (context, snapshot) {
                              final data =
                                  snapshot.data?.snapshot.value as String?;
                              if (data != null &&
                                  data.isNotEmpty &&
                                  data != 'rtdb_used') {
                                return Image.memory(
                                  base64Decode(data),
                                  gaplessPlayback: true,
                                  fit: BoxFit.contain,
                                  width: double.infinity,
                                  height: double.infinity,
                                  filterQuality: FilterQuality.low,
                                );
                              }
                              return Center(
                                child: Column(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    Icon(
                                      Icons.brush,
                                      size: 40,
                                      color: Colors.grey[300],
                                    ),
                                    Text(
                                      "En attente du dessin...",
                                      style: TextStyle(color: Colors.grey[400]),
                                    ),
                                  ],
                                ),
                              );
                            },
                          ),
                ),

                // Petit badge avec le nom de l'artiste et compteur de traits
                Positioned(
                  top: 10,
                  left: 10,
                  child: Container(
                    padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: Colors.black12,
                      borderRadius: BorderRadius.circular(10),
                    ),
                    child: Row(
                      children: [
                        Icon(Icons.edit, size: 12, color: Colors.black54),
                        SizedBox(width: 4),
                        Text(
                          drawerName,
                          style: TextStyle(color: Colors.black54, fontSize: 12),
                        ),
                        if (pictionaryOnly30Strokes && amIDrawingPlayer) ...[
                          SizedBox(width: 8),
                          Text(
                            "$_pictionaryStrokeCount/30 traits",
                            style: TextStyle(
                              color:
                                  drawingBlocked ? Colors.red : Colors.black54,
                              fontSize: 12,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),
                ),

                // Bouton Clear pour le dessinateur
                if (amIDrawingPlayer)
                  Positioned(
                    top: 10,
                    right: 10,
                    child: IconButton(
                      icon: Icon(Icons.delete, color: Colors.red),
                      onPressed: () {
                        setState(() {
                          _pictionaryStrokeCount = 0;
                          _straightLinePoints = [];
                          _straightLineStart = null;
                          _straightLineCurrentEnd = null;
                        });
                        _pictionaryDrawingController.clear();
                        _firebaseService.updatePictionaryDrawing(
                          widget.gameCode,
                          "",
                          0,
                        );
                      },
                    ),
                  ),
              ],
            ),
          ),
        ),

        // ZONE DE CHAT / DEVINETTES
        Expanded(
          flex: 4,
          child: Column(
            children: [
              Expanded(
                child: Builder(
                  builder: (context) {
                    // Utilisation du Provider pour avoir les mises à jour en temps réel
                    final gameDataFromProvider =
                        Provider.of<DocumentSnapshot>(
                              context,
                              listen: true,
                            ).data()
                            as Map<String, dynamic>;
                    final List<dynamic> pictionaryGuesses = List.from(
                      gameDataFromProvider['pictionaryGuesses'] ?? [],
                    );

                    pictionaryGuesses.sort(
                      (a, b) => (a['timestamp'] as int).compareTo(
                        b['timestamp'] as int,
                      ),
                    );

                    return ListView.builder(
                      reverse:
                          true, // Pour afficher les nouveaux messages en bas
                      itemCount: pictionaryGuesses.length,
                      itemBuilder: (context, index) {
                        final guessData =
                            pictionaryGuesses.reversed.toList()[index]
                                as Map<String, dynamic>;

                        return Card(
                          color: Colors.grey[900],
                          margin: EdgeInsets.symmetric(
                            vertical: 2,
                            horizontal: 8,
                          ),
                          child: ListTile(
                            dense: true,
                            title: Text(
                              guessData['guess'] ?? '',
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            subtitle: Text(
                              guessData['guesserName'] ?? '...',
                              style: TextStyle(fontSize: 10),
                            ),
                            // Bouton pour valider la bonne réponse (seulement pour le dessinateur)
                            trailing:
                                amIDrawingPlayer
                                    ? ElevatedButton(
                                      onPressed:
                                          () => _firebaseService
                                              .validatePictionaryGuess(
                                                widget.gameCode,
                                                guessData['guesserId'],
                                              ),
                                      child: Icon(Icons.check, size: 16),
                                      style: ElevatedButton.styleFrom(
                                        backgroundColor: Colors.green,
                                        padding: EdgeInsets.all(8),
                                        shape: CircleBorder(),
                                        minimumSize: Size(30, 30),
                                      ),
                                    )
                                    : null,
                          ),
                        );
                      },
                    );
                  },
                ),
              ),

              if (!amIDrawingPlayer)
                Padding(
                  padding: const EdgeInsets.all(8.0),
                  child: Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: _pictionaryGuessController,
                          decoration: InputDecoration(
                            labelText: "Propose une réponse...",
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(20),
                            ),
                            filled: true,
                            fillColor: Colors.grey[800],
                          ),
                          onSubmitted: (value) {
                            final guess = value.trim();
                            if (guess.isNotEmpty) {
                              _firebaseService.submitPictionaryGuess(
                                widget.gameCode,
                                playerId,
                                players[playerId]?['name'] ?? 'Anonyme',
                                guess,
                              );
                              setState(() {
                                _pictionaryGuessController.clear();
                              });
                            }
                          },
                        ),
                      ),
                      SizedBox(width: 8),
                      IconButton(
                        icon: Icon(Icons.send, color: Colors.deepPurpleAccent),
                        onPressed: () {
                          final guess = _pictionaryGuessController.text.trim();
                          if (guess.isNotEmpty) {
                            _firebaseService.submitPictionaryGuess(
                              widget.gameCode,
                              playerId,
                              players[playerId]?['name'] ?? 'Anonyme',
                              guess,
                            );
                            setState(() {
                              _pictionaryGuessController.clear();
                            });
                          }
                        },
                      ),
                    ],
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildJustOneUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'clue_giving';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? justOneGuesserId = gameData['justOneGuesserId'];
    final String? justOneCurrentWord = gameData['justOneCurrentWord'];
    final Map<String, dynamic> justOneClues = Map<String, dynamic>.from(
      gameData['justOneClues'] ?? {},
    );
    final List<dynamic> justOneFilteredClues = List<dynamic>.from(
      gameData['justOneFilteredClues'] ?? [],
    );
    final int deckIndex = (gameData['justOneDeckIndex'] ?? 0) + 1;
    final int deckTotal = (gameData['justOneDeck'] as List?)?.length ?? 13;
    final int totalScore = gameData['justOneTotalScore'] ?? 0;

    bool amIGuesser = playerId == justOneGuesserId;
    String guesserName = players[justOneGuesserId]?['name'] ?? 'Quelqu\'un';

    // Reset flag si nouveau tour (indice pas encore soumis)
    if (roundState == 'clue_giving' && !justOneClues.containsKey(playerId)) {
      _justOneHasSubmittedClue = false;
    }

    // Fin de partie collective
    if (gameData['gameState'] == 'gameOver') {
      String rating =
          totalScore >= 12
              ? '🏆 Légendaire !'
              : totalScore >= 10
              ? '⭐ Excellent !'
              : totalScore >= 7
              ? '👍 Bien joué !'
              : totalScore >= 4
              ? '😅 Pas mal !'
              : '💪 On peut mieux faire !';
      bool isHost = gameData['hostId'] == playerId;
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 16),
                Text(
                  "Score collectif",
                  style: Theme.of(context).textTheme.titleLarge,
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  "$totalScore / $deckTotal",
                  style: TextStyle(
                    fontSize: 64,
                    fontWeight: FontWeight.bold,
                    color: Colors.amberAccent,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  rating,
                  style: TextStyle(fontSize: 22),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 24),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .returnToLobby(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child: Text("Retour au salon"),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    // Résultat du tour
    if (roundState == 'result') {
      final String answer = gameData['justOneGuesserAnswer'] ?? '';
      final bool wasCorrect =
          answer.trim().toLowerCase() ==
          (justOneCurrentWord ?? '').toLowerCase();
      bool isHost = gameData['hostId'] == playerId;
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Carte $deckIndex / $deckTotal",
                  style: TextStyle(color: Colors.white54, fontSize: 14),
                ),
                SizedBox(height: 12),
                Text(
                  wasCorrect ? "✅ Bravo !" : "❌ Raté !",
                  style: TextStyle(
                    fontSize: 28,
                    fontWeight: FontWeight.bold,
                    color: wasCorrect ? Colors.greenAccent : Colors.redAccent,
                  ),
                  textAlign: TextAlign.center,
                ),
                SizedBox(height: 8),
                Text(
                  "Le mot était : ${justOneCurrentWord ?? ''}",
                  style: Theme.of(context).textTheme.titleLarge,
                  textAlign: TextAlign.center,
                ),
                if (answer.isNotEmpty)
                  Text(
                    "Réponse de $guesserName : \"$answer\"",
                    style: TextStyle(color: Colors.white70),
                    textAlign: TextAlign.center,
                  ),
                SizedBox(height: 16),
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 24, vertical: 12),
                  decoration: BoxDecoration(
                    color: Colors.amberAccent.withOpacity(0.15),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Text(
                    "Score : $totalScore / $deckIndex",
                    style: TextStyle(
                      fontSize: 20,
                      fontWeight: FontWeight.bold,
                      color: Colors.amberAccent,
                    ),
                  ),
                ),
                SizedBox(height: 20),
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () {
                              setState(() => _isActionPending = true);
                              _firebaseService
                                  .nextJustOneRound(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child:
                        _isActionPending
                            ? CircularProgressIndicator(color: Colors.white)
                            : Text(
                              deckIndex >= deckTotal
                                  ? "Voir le score final"
                                  : "Carte suivante →",
                            ),
                  ),
                if (!isHost)
                  Text(
                    "En attente de l'hôte pour la suite...",
                    style: TextStyle(color: Colors.white54),
                  ),
              ],
            ),
          ),
        ),
      );
    }

    switch (roundState) {
      // --- PHASE 2 : LES AUTRES ÉCRIVENT LES INDICES ---
      case 'clue_giving':
        if (amIGuesser) {
          return Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                "Chut ! Ferme les yeux 🙈",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              SizedBox(height: 8),
              Text(
                "Carte $deckIndex / $deckTotal",
                style: TextStyle(color: Colors.white54, fontSize: 14),
              ),
              SizedBox(height: 20),
              Text(
                "Les autres écrivent des indices pour toi...",
                style: TextStyle(fontSize: 16, color: Colors.white70),
              ),
              SizedBox(height: 30),
              _buildWaitingWidget(
                "Indices soumis : ${justOneClues.length} / ${players.length - 1}",
                players,
                justOneClues.length,
                players.length - 1,
              ),
            ],
          );
        } else {
          // Si j'ai déjà soumis
          if (justOneClues.containsKey(playerId) || _justOneHasSubmittedClue) {
            return _buildWaitingWidget(
              "Indice envoyé ! En attente des autres...",
              players,
              justOneClues.length,
              players.length - 1,
            );
          }
          return Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                "Carte $deckIndex / $deckTotal — Score : $totalScore",
                style: TextStyle(color: Colors.white54, fontSize: 14),
              ),
              SizedBox(height: 8),
              Text(
                "Faites deviner le mot :",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              Container(
                padding: EdgeInsets.symmetric(horizontal: 20, vertical: 10),
                margin: EdgeInsets.symmetric(vertical: 10),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Text(
                  justOneCurrentWord ?? "...",
                  style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                    color: Colors.deepPurple,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
              SizedBox(height: 20),
              TextField(
                controller: _justOneClueController,
                decoration: InputDecoration(
                  labelText: "Ton indice (UN SEUL mot)",
                ),
                onChanged:
                    (val) =>
                        setState(() {}), // Rafraichit pour activer le bouton
              ),
              SizedBox(height: 10),
              ElevatedButton(
                onPressed:
                    _justOneClueController.text.trim().isEmpty ||
                            _isActionPending
                        ? null
                        : () {
                          if (_justOneClueController.text
                                  .trim()
                                  .split(' ')
                                  .length >
                              1) {
                            ScaffoldMessenger.of(context).showSnackBar(
                              SnackBar(content: Text("Un seul mot autorisé !")),
                            );
                            return;
                          }
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .submitJustOneClue(
                                widget.gameCode,
                                playerId,
                                _justOneClueController.text.trim(),
                              )
                              .then((_) {
                                if (mounted)
                                  setState(() {
                                    _justOneHasSubmittedClue = true;
                                  });
                              })
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                          _justOneClueController.clear();
                        },
                child:
                    _isActionPending
                        ? CircularProgressIndicator(color: Colors.white)
                        : Text("Envoyer l'indice"),
              ),
            ],
          );
        }

      // --- PHASE 3 : LE DEVIN LIT LES INDICES ---
      case 'reveal_clues':
        if (!amIGuesser) {
          return Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text(
                  "Carte $deckIndex / $deckTotal",
                  style: TextStyle(color: Colors.white54, fontSize: 14),
                ),
                SizedBox(height: 8),
                Text(
                  "Le mot est : ${justOneCurrentWord}",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                SizedBox(height: 20),
                Text(
                  "Indices montrés à $guesserName :",
                  style: TextStyle(color: Colors.white70),
                ),
                SizedBox(height: 20),
                Wrap(
                  alignment: WrapAlignment.center,
                  children:
                      justOneFilteredClues
                          .map((clue) => _buildEasel(clue.toString()))
                          .toList(),
                ),
                SizedBox(height: 20),
                if (justOneFilteredClues.isEmpty)
                  Text(
                    "Tous les indices ont été annulés !",
                    style: TextStyle(color: Colors.red),
                  ),
              ],
            ),
          );
        } else {
          // C'est au devin de jouer
          return Column(
            children: [
              Text(
                "Carte $deckIndex / $deckTotal — Score : $totalScore",
                style: TextStyle(color: Colors.white54, fontSize: 14),
              ),
              SizedBox(height: 8),
              Text(
                "Voici tes indices !",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              SizedBox(height: 20),

              if (justOneFilteredClues.isEmpty)
                Container(
                  padding: EdgeInsets.all(20),
                  decoration: BoxDecoration(
                    color: Colors.red.withOpacity(0.2),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Text(
                    "Aïe ! Tous les indices étaient identiques ou invalides. Ils ont été effacés !",
                    style: TextStyle(color: Colors.white),
                    textAlign: TextAlign.center,
                  ),
                )
              else
                Wrap(
                  alignment: WrapAlignment.center,
                  children:
                      justOneFilteredClues
                          .map((clue) => _buildEasel(clue.toString()))
                          .toList(),
                ),

              Spacer(),

              TextField(
                controller: _justOneGuessController,
                decoration: InputDecoration(labelText: "Ta proposition..."),
                onChanged: (val) => setState(() {}),
              ),
              SizedBox(height: 10),
              ElevatedButton(
                onPressed:
                    _justOneGuessController.text.trim().isEmpty ||
                            _isActionPending
                        ? null
                        : () {
                          setState(() => _isActionPending = true);
                          _firebaseService
                              .submitJustOneGuess(
                                widget.gameCode,
                                _justOneGuessController.text.trim(),
                              )
                              .whenComplete(() {
                                if (mounted)
                                  setState(() => _isActionPending = false);
                              });
                          _justOneGuessController.clear();
                        },
                child:
                    _isActionPending
                        ? CircularProgressIndicator(color: Colors.white)
                        : Text("Je valide !"),
              ),
              SizedBox(height: 20),
            ],
          );
        }

      default:
        return _buildWaitingWidget("Chargement...", players, 0, 0);
    }
  }

  Widget _buildHotPotatoUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String roundState = gameData['roundState'] ?? 'playing';
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? currentPotatoPlayerId = gameData['hotPotatoCurrentPlayerId'];

    // Handle gameOver for Categories
    if (gameData['gameState'] == 'gameOver') {
      final String gameEndReason =
          gameData['gameEndReason'] ?? 'Partie terminée !';
      List<MapEntry<String, int>> sortedScores = [];
      players.forEach((id, data) {
        sortedScores.add(
          MapEntry(data['name'] ?? 'Inconnu', data['score'] ?? 0),
        );
      });
      sortedScores.sort((a, b) => a.value.compareTo(b.value));
      return Center(
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(24.0),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Partie Terminée !",
                  style: Theme.of(context).textTheme.headlineMedium,
                ),
                SizedBox(height: 10),
                Text(
                  gameEndReason,
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                    color: Colors.amberAccent,
                  ),
                ),
                SizedBox(height: 20),
                Text(
                  "Classement final",
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                SizedBox(height: 8),
                ...sortedScores.asMap().entries.map(
                  (e) => Padding(
                    padding: const EdgeInsets.symmetric(vertical: 2),
                    child: Text(
                      "${e.key + 1}. ${e.value.key}: ${e.value.value} pt${e.value.value > 1 ? 's' : ''}",
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight:
                            e.key == 0 ? FontWeight.bold : FontWeight.normal,
                      ),
                    ),
                  ),
                ),
                SizedBox(height: 20),
                ElevatedButton(
                  onPressed:
                      () => Navigator.of(
                        context,
                      ).popUntil((route) => route.isFirst),
                  child: Text("Retour à l'accueil"),
                ),
              ],
            ),
          ),
        ),
      );
    }

    int secondsLeft = gameData['hotPotatoSecondsLeft'] ?? 0;
    if (gameData['hotPotatoRoundStartedAt'] != null) {
      final Timestamp startTimeStamp = gameData['hotPotatoRoundStartedAt'];
      final DateTime startTime = startTimeStamp.toDate();
      final int duration = secondsLeft;
      final int elapsed = DateTime.now().difference(startTime).inSeconds;
      secondsLeft = max(0, duration - elapsed);
    }

    final String category = gameData['hotPotatoCategory'] ?? "Catégorie";
    final List<String> usedAnswers = List<String>.from(
      gameData['hotPotatoUsedAnswers'] ?? [],
    );

    final bool isMyTurn = playerId == currentPotatoPlayerId;
    final String currentPotatoPlayerName =
        players[currentPotatoPlayerId]?['name'] ?? 'Quelqu\'un';

    if (roundState == 'exploded') {
      return _buildHotPotatoExplodedUI(context, gameData, playerId);
    }

    // Couleur de fond dynamique (Vert -> Rouge)
    Color timerColor =
        secondsLeft > 10
            ? Colors.green
            : (secondsLeft > 5 ? Colors.orange : Colors.red);
    // Animation simple de pulsation quand il reste peu de temps
    double pulseScale =
        isMyTurn
            ? (1.0 +
                (secondsLeft <= 5
                    ? (DateTime.now().millisecond % 500) / 1000.0
                    : 0.0))
            : 1.0;

    final String gameType = gameData['gameType'] ?? '';
    final bool isCategories = gameType == 'Le Jeu des Catégories';
    final int currentRound = gameData['currentRound'] ?? 1;

    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        // Round & score info for Categories
        if (isCategories) ...[
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                "Manche $currentRound",
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14),
              ),
              Row(
                mainAxisSize: MainAxisSize.min,
                children:
                    players.entries
                        .map(
                          (e) => Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 4),
                            child: Chip(
                              label: Text(
                                "${e.value['name']?.toString().substring(0, min(4, (e.value['name']?.toString().length ?? 0)))}: ${e.value['score'] ?? 0}",
                                style: TextStyle(fontSize: 11),
                              ),
                              padding: EdgeInsets.zero,
                              visualDensity: VisualDensity.compact,
                            ),
                          ),
                        )
                        .toList(),
              ),
            ],
          ),
          SizedBox(height: 8),
        ],
        // Indicateur de tour
        Container(
          padding: EdgeInsets.all(16),
          decoration: BoxDecoration(
            color:
                isMyTurn
                    ? Colors.redAccent.withOpacity(0.2)
                    : Colors.transparent,
            borderRadius: BorderRadius.circular(20),
            border:
                isMyTurn ? Border.all(color: Colors.redAccent, width: 2) : null,
          ),
          child: Column(
            children: [
              Text(
                isMyTurn
                    ? "C'EST À TOI !"
                    : "Au tour de $currentPotatoPlayerName",
                style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                  fontWeight: FontWeight.bold,
                  color: isMyTurn ? Colors.redAccent : Colors.white,
                ),
              ),
              SizedBox(height: 10),
              // Bombe visuelle
              Transform.scale(
                scale: pulseScale,
                child: Container(
                  width: 100,
                  height: 100,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.black,
                    boxShadow: [
                      BoxShadow(
                        color: timerColor,
                        blurRadius: 20,
                        spreadRadius: 5,
                      ),
                    ],
                  ),
                  child: Center(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          Icons.local_fire_department,
                          color: timerColor,
                          size: 40,
                        ),
                        Text(
                          "$secondsLeft",
                          style: TextStyle(
                            fontSize: 24,
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),

        SizedBox(height: 30),

        // Carte de la catégorie
        Card(
          elevation: 8,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(15),
          ),
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.all(24.0),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(15),
              gradient: LinearGradient(
                colors: [Colors.deepPurple[700]!, Colors.deepPurple[900]!],
              ),
            ),
            child: Column(
              children: [
                Text(
                  "Catégorie",
                  style: TextStyle(color: Colors.white70, letterSpacing: 2),
                ),
                SizedBox(height: 10),
                Text(
                  category,
                  style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                  ),
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),

        SizedBox(height: 20),

        // Zone de saisie (active seulement si c'est mon tour)
        if (isMyTurn)
          Column(
            children: [
              TextField(
                controller: _answerController,
                autofocus: true,
                decoration: InputDecoration(
                  labelText: "Vite ! Un mot !",
                  filled: true,
                  fillColor: Colors.white,
                  labelStyle: TextStyle(color: Colors.black54),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(30),
                  ),
                ),
                style: TextStyle(color: Colors.black, fontSize: 18),
                onSubmitted: (_) => _submitHotPotatoAnswer(),
              ),
              SizedBox(height: 15),
              ElevatedButton.icon(
                icon: Icon(Icons.send),
                label: Text("VALIDER & PASSER"),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.redAccent,
                  padding: EdgeInsets.symmetric(horizontal: 40, vertical: 15),
                  textStyle: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                onPressed:
                    _isActionPending ? null : () => _submitHotPotatoAnswer(),
              ),
            ],
          )
        else
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              "Prépare ta réponse pendant que les autres paniquent...",
              style: TextStyle(
                fontStyle: FontStyle.italic,
                color: Colors.white38,
              ),
            ),
          ),

        Spacer(),

        // Historique des mots
        Container(
          height: 100,
          child: SingleChildScrollView(
            reverse: true,
            child: Wrap(
              spacing: 8.0,
              runSpacing: 4.0,
              alignment: WrapAlignment.center,
              children:
                  usedAnswers
                      .map(
                        (answer) => Chip(
                          label: Text(answer),
                          backgroundColor: Colors.grey[800],
                        ),
                      )
                      .toList(),
            ),
          ),
        ),
      ],
    );
  }

  void _submitHotPotatoAnswer() async {
    if (_isActionPending) return;

    // --- CORRECTION ICI ---
    // Au lieu de : final String playerId = Provider.of<String>(context, listen: false);
    // Utilisez ceci :
    final String playerId = widget.playerId;
    // ----------------------

    final answer = _answerController.text.trim();

    setState(() => _isActionPending = true);
    try {
      await _firebaseService.submitHotPotatoAnswer(
        widget.gameCode,
        playerId,
        answer,
      );
      _answerController.clear();
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString().replaceAll('Exception: ', ''))),
      );
    } finally {
      if (mounted) setState(() => _isActionPending = false);
    }
  }

  Widget _buildHotPotatoExplodedUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final Map<String, dynamic> players = Map<String, dynamic>.from(
      gameData['players'] ?? {},
    );
    final String? loserId = gameData['roundWinnerId'];
    final String loserName = players[loserId]?['name'] ?? 'Inconnu';
    final String gameEndReason =
        gameData['gameEndReason'] ?? "La patate a explosé !";
    final isHost = gameData['hostId'] == playerId;
    final String gameType = gameData['gameType'] ?? '';
    final bool isCategories = gameType == 'Le Jeu des Catégories';

    if (_isHotPotatoMusicPlaying) {
      _hotPotatoPlayer?.stop();
      _hotPotatoPlayer?.dispose();
      _hotPotatoPlayer = null;
      _isHotPotatoMusicPlaying = false;
    }

    // Build score list for Categories
    List<MapEntry<String, int>> sortedScores = [];
    if (isCategories) {
      players.forEach((id, data) {
        sortedScores.add(
          MapEntry(data['name'] ?? 'Inconnu', data['score'] ?? 0),
        );
      });
      sortedScores.sort((a, b) => a.value.compareTo(b.value));
    }

    return Column(
      key: ValueKey('exploded_multi'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(Icons.local_fire_department, size: 100, color: Colors.redAccent),
        SizedBox(height: 20),
        Text(
          "BOOM !",
          style: Theme.of(context).textTheme.headlineMedium?.copyWith(
            fontSize: 48,
            color: Colors.redAccent,
          ),
        ),
        SizedBox(height: 20),
        Text(
          "$loserName a perdu !",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 10),
        Text(gameEndReason, style: Theme.of(context).textTheme.bodyMedium),
        if (isCategories) ...[
          SizedBox(height: 20),
          Text(
            "Scores (moins = mieux)",
            style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16),
          ),
          SizedBox(height: 8),
          ...sortedScores.map(
            (e) => Text(
              "${e.key}: ${e.value} pt${e.value > 1 ? 's' : ''}",
              style: TextStyle(fontSize: 14),
            ),
          ),
        ],
        SizedBox(height: 40),
        if (isHost)
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () async {
                      setState(() => _isActionPending = true);
                      await _firebaseService
                          .nextHotPotatoRound(widget.gameCode)
                          .whenComplete(() {
                            if (mounted)
                              setState(() => _isActionPending = false);
                          });
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Nouvelle Manche"),
          )
        else
          Text(
            "En attente de l'hôte pour la prochaine manche...",
            style: TextStyle(
              fontStyle: FontStyle.italic,
              color: Colors.white70,
            ),
          ),
      ],
    );
  }

  Widget _buildLoupGarouUI(
    BuildContext context,
    Map<String, dynamic> gameData,
    String playerId,
  ) {
    final String phase = gameData['phase'] ?? 'lobby';
    final String subPhase = gameData['subPhase'] ?? '';
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final List<String> playerOrder = List<String>.from(
      gameData['playerOrder'] ?? [],
    );
    final List<dynamic> gameLog = List<dynamic>.from(gameData['gameLog'] ?? []);
    final Map<String, dynamic> nightActions = Map<String, dynamic>.from(
      gameData['nightActions'] ?? {},
    );
    final Map<String, dynamic> dayVotes = Map<String, dynamic>.from(
      gameData['dayVotes'] ?? {},
    );
    final String? captainId = gameData['captainId'];
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    final int nightNumber = gameData['nightNumber'] ?? 0;
    final bool dictatorTookPowerAtNight =
        gameData['dictatorTookPowerAtNight'] ?? false;

    final myData = playerData[playerId] ?? {};
    final myRole = myData['role'] ?? 'Inconnu';
    final myStatus = myData['status'] ?? 'vivant';
    final myPrivateInfo = myData['privateInfo'];
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';

    Widget? actionWidget;
    String mainMessage = "";

    Map<String, List<String>> votesReceived = {};
    dayVotes.forEach((voterId, targetId) {
      final voterName = playerData[voterId]?['name'] ?? 'Inconnu';
      if (!votesReceived.containsKey(targetId)) {
        votesReceived[targetId] = [];
      }
      votesReceived[targetId]!.add(voterName);
    });

    Map<String, int> loupVoteTallies = {};
    if (nightActions['votes'] != null) {
      (nightActions['votes'] as Map<String, dynamic>).values.forEach((
        targetId,
      ) {
        loupVoteTallies[targetId] = (loupVoteTallies[targetId] ?? 0) + 1;
      });
    }

    List<String> contaminatedPlayers = List<String>.from(
      gameData['ratMaladeContaminated'] ?? [],
    );

    switch (phase) {
      case 'nuit':
        mainMessage = "La nuit tombe... Le village s'endort.";
        switch (subPhase) {
          case 'cupidon_turn':
            mainMessage =
                "Seul Cupidon est éveillé. Il doit désigner deux amoureux.";
            if (lovers.length >= 2) {
              actionWidget = Center(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.favorite, color: Colors.pink, size: 32),
                    SizedBox(height: 8),
                    Text(
                      "Cupidon a désigné les amoureux !",
                      style: TextStyle(fontStyle: FontStyle.italic),
                    ),
                    Text(
                      "Passage à la phase suivante...",
                      style: TextStyle(color: Colors.white54, fontSize: 12),
                    ),
                  ],
                ),
              );
            } else if (myRole == 'Cupidon' && myStatus == 'vivant') {
              actionWidget = _buildCupidonSelection(
                playerData,
                playerOrder,
                playerId,
                lovers,
              );
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente de Cupidon...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'heritier_turn':
            mainMessage = "L'Héritier se réveille et choisit son testateur.";
            if (myRole == 'Héritier' &&
                myStatus == 'vivant' &&
                myData['testateurId'] == null) {
              actionWidget = _buildLoupGarouActionGrid(
                title:
                    "Choisissez votre testateur (qui vous lèguera son rôle si vous mourrez) :",
                players: playerData,
                playerOrder: playerOrder,
                canSelectPlayerId:
                    (targetId) =>
                        targetId != playerId &&
                        playerData[targetId]?['status'] == 'vivant',
                onPlayerSelected: (targetId) async {
                  setState(() => _isActionPending = true);
                  await _firebaseService
                      .heritierChooseTestateur(
                        widget.gameCode,
                        playerId,
                        targetId,
                      )
                      .whenComplete(() {
                        if (mounted) setState(() => _isActionPending = false);
                      });
                },
                buttonText: "Désigner",
                isActionPending: _isActionPending,
              );
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente de l'Héritier...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'garde_turn':
            mainMessage = "Le Garde protège quelqu'un cette nuit.";
            if (myRole == 'Garde' && myStatus == 'vivant') {
              if (nightActions['gardeActed'] == true) {
                actionWidget = Center(
                  child: Text(
                    "Vous protégez quelqu'un cette nuit. En attente...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.white70,
                    ),
                  ),
                );
              } else {
                final String? lastProtected = myData['lastProtectedId'];
                actionWidget = _buildLoupGarouActionGrid(
                  title: "Qui protégez-vous cette nuit ? (Pas le même qu'hier)",
                  players: playerData,
                  playerOrder: playerOrder,
                  canSelectPlayerId:
                      (targetId) =>
                          targetId != lastProtected &&
                          playerData[targetId]?['status'] == 'vivant',
                  onPlayerSelected: (targetId) async {
                    setState(() => _isActionPending = true);
                    await _firebaseService
                        .gardeProtect(widget.gameCode, playerId, targetId)
                        .whenComplete(() {
                          if (mounted) setState(() => _isActionPending = false);
                        });
                  },
                  buttonText: "Protéger",
                  isActionPending: _isActionPending,
                );
              }
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente du Garde...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'voyante_turn':
            mainMessage = "La Voyante se réveille...";
            if (myRole == 'Voyante' && myStatus == 'vivant') {
              if (nightActions['voyanteActed'] == true) {
                actionWidget = Center(
                  child: Text(
                    "Vous avez déjà observé ce joueur. En attente...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.white70,
                    ),
                  ),
                );
              } else {
                actionWidget = _buildLoupGarouActionGrid(
                  title: "Sondez l'âme d'un joueur...",
                  players: playerData,
                  playerOrder: playerOrder,
                  canSelectPlayerId:
                      (targetId) =>
                          targetId != playerId &&
                          playerData[targetId]?['status'] == 'vivant',
                  onPlayerSelected: (targetId) async {
                    setState(() => _isActionPending = true);
                    try {
                      await _firebaseService.voyanteSee(
                        widget.gameCode,
                        targetId,
                      );
                    } catch (e) {
                      if (mounted)
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text("Erreur. Réessayez."),
                            backgroundColor: Colors.red,
                          ),
                        );
                    } finally {
                      if (mounted) setState(() => _isActionPending = false);
                    }
                  },
                  buttonText: "Sonder",
                  isActionPending: _isActionPending,
                );
              }
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente de la Voyante...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'rat_malade_turn':
            mainMessage = "Le Rat Malade se réveille et propage la maladie !";
            if (myRole == 'Rat Malade' && myStatus == 'vivant') {
              actionWidget = _buildRatMaladeAction(
                playerData,
                playerOrder,
                playerId,
                contaminatedPlayers,
              );
            }
            break;
          case 'loups_turn':
            mainMessage =
                "Les Loups-Garous se réveillent et choisissent leur proie !";
            if (amILoup && myStatus == 'vivant') {
              actionWidget = _buildLoupGarouActionGrid(
                title: "Choisissez qui dévorer cette nuit...",
                players: playerData,
                playerOrder: playerOrder,
                canSelectPlayerId:
                    (targetId) =>
                        (GameData.roleCamps[playerData[targetId]?['role']] !=
                                'loups' &&
                            playerData[targetId]?['infectionStatus'] !=
                                'infecte') &&
                        playerData[targetId]?['status'] == 'vivant',
                onPlayerSelected: (targetId) async {
                  setState(() => _isActionPending = true);
                  try {
                    await _firebaseService.loupGarouVote(
                      widget.gameCode,
                      playerId,
                      targetId,
                    );
                  } catch (e) {
                    if (mounted)
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text("Erreur lors du vote. Réessayez."),
                          backgroundColor: Colors.red,
                        ),
                      );
                  } finally {
                    if (mounted) setState(() => _isActionPending = false);
                  }
                },
                buttonText: "Voter",
                highlightedIds:
                    playerData.entries
                        .where(
                          (e) =>
                              GameData.roleCamps[e.value['role']] == 'loups' ||
                              e.value['infectionStatus'] == 'infecte',
                        )
                        .map((e) => e.key)
                        .toList(),
                voteTallies: loupVoteTallies,
                isActionPending: _isActionPending,
              );
            }
            if (myRole == 'Petite Fille' && myStatus == 'vivant' && !amILoup) {
              actionWidget = _buildLoupGarouActionGrid(
                title: "Tentez d'espionner quelqu'un...",
                players: playerData,
                playerOrder: playerOrder,
                canSelectPlayerId:
                    (targetId) =>
                        targetId != playerId &&
                        playerData[targetId]?['status'] == 'vivant',
                onPlayerSelected: (targetId) async {
                  setState(() => _isActionPending = true);
                  try {
                    await _firebaseService.petiteFilleSpy(
                      widget.gameCode,
                      playerId,
                      targetId,
                    );
                  } catch (e) {
                    if (mounted)
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text("Erreur. Réessayez."),
                          backgroundColor: Colors.red,
                        ),
                      );
                  } finally {
                    if (mounted) setState(() => _isActionPending = false);
                  }
                },
                buttonText: "Espionner",
                isActionPending: _isActionPending,
              );
            }
            break;
          case 'loup_noir_action':
            mainMessage = "Le Loup Noir peut transformer la victime des loups.";
            String? loupNoirId =
                playerData.entries
                    .firstWhere(
                      (e) =>
                          e.value['role'] == 'Loup Noir' &&
                          e.value['status'] == 'vivant',
                      orElse: () => MapEntry('', {}),
                    )
                    .key;
            bool infectionAlreadyUsed =
                playerData[loupNoirId]?['infectionUsed'] ?? true;
            String? loupTargetId = nightActions['loupTarget'];
            if (loupNoirId == playerId &&
                myStatus == 'vivant' &&
                loupTargetId != null &&
                !infectionAlreadyUsed) {
              actionWidget = _buildLoupNoirAction(
                playerData,
                loupTargetId,
                playerId,
              );
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente du Loup Noir...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'loup_blanc_turn':
            mainMessage = "Le Loup Blanc se réveille et choisit sa proie.";
            if (myRole == 'Loup Blanc' &&
                myStatus == 'vivant' &&
                (nightNumber % 2 != 0)) {
              if (nightActions['loupBlancActed'] == true) {
                actionWidget = Center(
                  child: Text(
                    "Vous avez agi. En attente de la suite...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.white70,
                    ),
                  ),
                );
              } else {
                actionWidget = _buildLoupGarouActionGrid(
                  title:
                      "Choisissez qui dévorer (son pouvoir ignore les protections) :",
                  players: playerData,
                  playerOrder: playerOrder,
                  canSelectPlayerId:
                      (targetId) =>
                          targetId != playerId &&
                          playerData[targetId]?['status'] == 'vivant',
                  onPlayerSelected: (targetId) async {
                    setState(() => _isActionPending = true);
                    try {
                      await _firebaseService.loupBlancDevour(
                        widget.gameCode,
                        playerId,
                        targetId,
                      );
                    } catch (e) {
                      if (mounted)
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text("Erreur. Réessayez."),
                            backgroundColor: Colors.red,
                          ),
                        );
                    } finally {
                      if (mounted) setState(() => _isActionPending = false);
                    }
                  },
                  buttonText: "Dévourer",
                  isActionPending: _isActionPending,
                );
              }
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente du Loup Blanc...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'sorciere_turn':
            mainMessage = "La Sorcière se réveille...";
            if (myRole == 'Sorcière' && myStatus == 'vivant') {
              if (nightActions['sorciereActed'] == true) {
                actionWidget = Center(
                  child: Text(
                    "Vous avez agi. En attente de la suite...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.white70,
                    ),
                  ),
                );
              } else {
                final victimeId = nightActions['loupTarget'];
                final victimeName =
                    playerData[victimeId]?['name'] ?? 'personne';
                final potions = myData['potions'] ?? {};
                actionWidget = _buildSorciereActions(
                  context,
                  playerData,
                  playerOrder,
                  victimeId,
                  victimeName,
                  potions,
                  playerId,
                );
              }
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente de la Sorcière...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
          case 'pyromancien_turn':
            mainMessage = "Le Pyromancien agit avec son feu grégeois.";
            if (myRole == 'Pyromancien' && myStatus == 'vivant') {
              actionWidget = _buildPyromancienActions(
                playerData,
                playerOrder,
                playerId,
                Map<String, int>.from(gameData['pyromancienBarrels'] ?? {}),
              );
            } else {
              actionWidget = Center(
                child: Text(
                  "En attente du Pyromancien...",
                  style: TextStyle(fontStyle: FontStyle.italic),
                ),
              );
            }
            break;
        }
        break;

      case 'jour_discussion':
        mainMessage = "Le village se réveille et débat...";

        if (subPhase == 'captain_designate') {
          mainMessage = "Le Capitaine défunt doit désigner son successeur !";
          if (gameData['activePlayerId'] == playerId) {
            actionWidget = _buildLoupGarouActionGrid(
              title: "Désignez le nouveau Capitaine",
              players: playerData,
              playerOrder: playerOrder,
              canSelectPlayerId:
                  (targetId) =>
                      targetId != playerId &&
                      playerData[targetId]?['status'] == 'vivant',
              onPlayerSelected: (targetId) async {
                setState(() => _isActionPending = true);
                await _firebaseService
                    .captainDesignate(widget.gameCode, playerId, targetId)
                    .whenComplete(() {
                      if (mounted) setState(() => _isActionPending = false);
                    });
              },
              buttonText: "Désigner",
              isActionPending: _isActionPending,
            );
          } else {
            actionWidget = Center(
              child: Text(
                "En attente que le Capitaine désigne son successeur...",
                style: TextStyle(fontStyle: FontStyle.italic),
              ),
            );
          }
        } else if (subPhase == 'chasseur_revenge') {
          mainMessage = "Le Chasseur doit choisir sa cible !";
          if (gameData['activePlayerId'] == playerId) {
            actionWidget = _buildLoupGarouActionGrid(
              title: "Qui emportez-vous dans la tombe ?",
              players: playerData,
              playerOrder: playerOrder,
              canSelectPlayerId:
                  (targetId) =>
                      targetId != playerId &&
                      playerData[targetId]?['status'] == 'vivant',
              onPlayerSelected: (targetId) async {
                setState(() => _isActionPending = true);
                await _firebaseService
                    .chasseurShoot(widget.gameCode, playerId, targetId)
                    .whenComplete(() {
                      if (mounted) setState(() => _isActionPending = false);
                    });
              },
              buttonText: "TIRER !",
              isActionPending: _isActionPending,
            );
          }
        } else if (subPhase == 'fossoyeur_reveal') {
          mainMessage = "Le Fossoyeur va révéler des rôles !";
          if (gameData['activePlayerId'] == playerId) {
            actionWidget = _buildLoupGarouActionGrid(
              title:
                  "Choisissez un joueur à révéler (un joueur du camp opposé sera aussi révélé) :",
              players: playerData,
              playerOrder: playerOrder,
              canSelectPlayerId:
                  (targetId) =>
                      targetId != playerId &&
                      playerData[targetId]?['status'] == 'vivant',
              onPlayerSelected: (targetId) async {
                setState(() => _isActionPending = true);
                await _firebaseService
                    .fossoyeurReveal(widget.gameCode, playerId, targetId)
                    .whenComplete(() {
                      if (mounted) setState(() => _isActionPending = false);
                    });
              },
              buttonText: "Révéler",
              isActionPending: _isActionPending,
            );
          } else {
            actionWidget = Center(
              child: Text(
                "En attente du Fossoyeur...",
                style: TextStyle(fontStyle: FontStyle.italic),
              ),
            );
          }
        } else if (subPhase == 'dictateur_coup') {
          mainMessage = "Le Dictateur s'empare du vote du village !";
          if (gameData['activePlayerId'] == playerId) {
            actionWidget = _buildLoupGarouActionGrid(
              title:
                  "Qui voulez-vous exécuter ? (Si c'est un Loup/Solitaire, vous devenez Maire. Sinon, vous mourez.)",
              players: playerData,
              playerOrder: playerOrder,
              canSelectPlayerId:
                  (targetId) =>
                      targetId != playerId &&
                      playerData[targetId]?['status'] == 'vivant',
              onPlayerSelected: (targetId) async {
                setState(() => _isActionPending = true);
                await _firebaseService
                    .dictateurCoup(widget.gameCode, playerId, targetId)
                    .whenComplete(() {
                      if (mounted) setState(() => _isActionPending = false);
                    });
              },
              buttonText: "EXÉCUTER",
              isActionPending: _isActionPending,
            );
          } else {
            actionWidget = Center(
              child: Text(
                "En attente du Dictateur...",
                style: TextStyle(fontStyle: FontStyle.italic),
              ),
            );
          }
        } else {
          final isHost = gameData['hostId'] == playerId;
          final bool amIDictateur =
              myRole == 'Dictateur' &&
              myStatus == 'vivant' &&
              !(myData['powerUsed'] ?? false) &&
              !(gameData['dictatorUsed'] ?? false);
          actionWidget = Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (isHost)
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () async {
                              setState(() => _isActionPending = true);
                              await _firebaseService
                                  .startDayVotePhase(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child:
                        _isActionPending
                            ? SizedBox(
                              height: 20,
                              width: 20,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            )
                            : Text("Lancer la phase de vote"),
                  )
                else
                  Padding(
                    padding: const EdgeInsets.all(8.0),
                    child: Text(
                      "En attente de l'hôte pour lancer le vote...",
                      style: TextStyle(fontStyle: FontStyle.italic),
                      textAlign: TextAlign.center,
                    ),
                  ),
                if (amIDictateur) ...[
                  SizedBox(height: 12),
                  ElevatedButton.icon(
                    icon: Icon(Icons.gavel),
                    label: Text("Coup d'État !"),
                    onPressed:
                        _isActionPending
                            ? null
                            : () async {
                              setState(() => _isActionPending = true);
                              await _firebaseService
                                  .triggerDictateurCoup(
                                    widget.gameCode,
                                    playerId,
                                  )
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.purple[800],
                    ),
                  ),
                ],
              ],
            ),
          );
        }
        break;

      case 'jour_vote':
        mainMessage = "Le moment est venu de voter ! Qui est un Loup-Garou ?";
        final int totalVivants =
            playerData.entries
                .where((e) => e.value['status'] == 'vivant')
                .length;
        final int totalVotes = dayVotes.length;
        if (myStatus == 'vivant' && !dayVotes.containsKey(playerId)) {
          actionWidget = _buildLoupGarouActionGrid(
            title: "Votez pour éliminer un joueur ($totalVotes/$totalVivants)",
            players: playerData,
            playerOrder: playerOrder,
            canSelectPlayerId:
                (targetId) =>
                    targetId != playerId &&
                    playerData[targetId]?['status'] == 'vivant',
            onPlayerSelected: (targetId) async {
              setState(() => _isActionPending = true);
              await _firebaseService
                  .submitDayVote(widget.gameCode, playerId, targetId)
                  .whenComplete(() {
                    if (mounted) setState(() => _isActionPending = false);
                  });
            },
            buttonText: "Voter",
            isActionPending: _isActionPending,
          );
        } else {
          final isHost = gameData['hostId'] == playerId;
          actionWidget = Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  "Votes : $totalVotes / $totalVivants",
                  style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
                ),
                SizedBox(height: 8),
                if (dayVotes.containsKey(playerId))
                  Text(
                    "Vous avez voté. En attente des autres joueurs...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.white70,
                    ),
                  ),
                if (myStatus == 'mort')
                  Text(
                    "Vous êtes mort. En attente du vote...",
                    style: TextStyle(
                      fontStyle: FontStyle.italic,
                      color: Colors.grey,
                    ),
                  ),
                if (isHost) ...[
                  SizedBox(height: 12),
                  ElevatedButton(
                    onPressed:
                        _isActionPending
                            ? null
                            : () async {
                              setState(() => _isActionPending = true);
                              await _firebaseService
                                  .processDayVote(widget.gameCode)
                                  .whenComplete(() {
                                    if (mounted)
                                      setState(() => _isActionPending = false);
                                  });
                            },
                    child:
                        _isActionPending
                            ? SizedBox(
                              height: 20,
                              width: 20,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            )
                            : Text("Forcer la fin du vote"),
                  ),
                ],
              ],
            ),
          );
        }
        break;
      case 'gameOver':
        mainMessage = "La partie est terminée !";
        actionWidget = Column(
          children: [
            Text(
              gameLog.last,
              style: Theme.of(context).textTheme.headlineSmall,
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: () => Navigator.of(context).popUntil((r) => r.isFirst),
              child: Text("Retour à l'accueil"),
            ),
            if (gameData['hostId'] == playerId)
              Padding(
                padding: const EdgeInsets.only(top: 10.0),
                child: ElevatedButton(
                  onPressed:
                      _isActionPending
                          ? null
                          : () async {
                            setState(() => _isActionPending = true);
                            await _firebaseService
                                .resetLoupGarouGame(widget.gameCode)
                                .whenComplete(() {
                                  if (mounted)
                                    setState(() => _isActionPending = false);
                                });
                          },
                  child:
                      _isActionPending
                          ? SizedBox(
                            height: 20,
                            width: 20,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                          : Text("Rejouer !"),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.green,
                  ),
                ),
              ),
          ],
        );
        break;
    }

    final bool canSeeLovers = lovers.contains(playerId) || myRole == 'Cupidon';
    return Row(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // Barre latérale gauche - Messages
        SizedBox(
          width: 240,
          child: Container(
            decoration: BoxDecoration(
              color: Colors.grey[900],
              border: Border(
                right: BorderSide(
                  color: Colors.deepPurpleAccent.withOpacity(0.4),
                  width: 1,
                ),
              ),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Container(
                  padding: EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                  color: Colors.grey[850],
                  child: Row(
                    children: [
                      Icon(
                        Icons.forum,
                        size: 16,
                        color: Colors.deepPurpleAccent,
                      ),
                      SizedBox(width: 6),
                      Text(
                        "Messages",
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                    ],
                  ),
                ),
                Expanded(child: _buildChatInterface(gameData, playerId)),
              ],
            ),
          ),
        ),
        // Contenu principal
        Expanded(
          child: Column(
            children: [
              // Barre d'info en haut
              ConstrainedBox(
                constraints: BoxConstraints(maxHeight: 90),
                child: Card(
                  margin: EdgeInsets.all(4),
                  child: SingleChildScrollView(
                    child: Padding(
                      padding: const EdgeInsets.all(6.0),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          if (myPrivateInfo != null)
                            Padding(
                              padding: const EdgeInsets.only(bottom: 4.0),
                              child: Text(
                                myPrivateInfo,
                                style: TextStyle(
                                  color: Colors.lightBlueAccent,
                                  fontStyle: FontStyle.italic,
                                ),
                                textAlign: TextAlign.center,
                              ),
                            ),
                          Text(
                            mainMessage,
                            style: Theme.of(context).textTheme.titleMedium,
                            textAlign: TextAlign.center,
                          ),
                          SizedBox(height: 2),
                          Chip(
                            label: Text(
                              "Votre rôle : $myRole",
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            backgroundColor:
                                amILoup
                                    ? Colors.red[800]
                                    : (GameData.roleCamps[myRole] == 'solitaire'
                                        ? Colors.orange[800]
                                        : Colors.blue[800]),
                            materialTapTargetSize:
                                MaterialTapTargetSize.shrinkWrap,
                            visualDensity: VisualDensity.compact,
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ),
              // Cercle des joueurs
              Expanded(
                flex: 3,
                child: LayoutBuilder(
                  builder: (context, constraints) {
                    final double availableRadius =
                        min(
                          constraints.maxWidth / 2.0,
                          constraints.maxHeight / 2.0,
                        ) *
                        0.88;
                    final double outerRadius = availableRadius;
                    final double circleRadius = outerRadius * 0.62;
                    const double avatarHalfSize = 30.0;

                    return Stack(
                      alignment: Alignment.center,
                      children: [
                        Positioned.fill(
                          child: Center(
                            child: Container(
                              width: circleRadius * 2,
                              height: circleRadius * 2,
                              decoration: BoxDecoration(
                                color: Colors.grey[900]?.withOpacity(0.8),
                                shape: BoxShape.circle,
                                border: Border.all(
                                  color: Colors.deepPurpleAccent,
                                  width: 2,
                                ),
                              ),
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  Text(
                                    "Tour ${gameData['nightNumber'] + 1}",
                                    style:
                                        Theme.of(
                                          context,
                                        ).textTheme.headlineSmall,
                                  ),
                                  Expanded(
                                    child: ListView.builder(
                                      itemCount: gameLog.length,
                                      reverse: true,
                                      shrinkWrap: true,
                                      padding: EdgeInsets.all(8),
                                      itemBuilder: (context, index) {
                                        final reversedIndex =
                                            gameLog.length - 1 - index;
                                        return Text(
                                          gameLog[reversedIndex],
                                          style:
                                              Theme.of(
                                                context,
                                              ).textTheme.bodySmall,
                                          textAlign: TextAlign.center,
                                        );
                                      },
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        ),
                        ...List.generate(playerOrder.length, (index) {
                          final angle =
                              2 * pi * index / playerOrder.length - (pi / 2);
                          final pId = playerOrder[index];
                          final pData = playerData[pId] ?? {};
                          final x = outerRadius * cos(angle);
                          final y = outerRadius * sin(angle);
                          return Positioned(
                            left:
                                (constraints.maxWidth / 2) + x - avatarHalfSize,
                            top:
                                (constraints.maxHeight / 2) +
                                y -
                                avatarHalfSize,
                            child: _buildPlayerAvatar(
                              pData,
                              pId,
                              pId == playerId,
                              votesReceived[pId],
                              captainId,
                              lovers,
                              amILoup,
                              nightNumber,
                              currentRoundState: phase,
                              contaminatedPlayers: contaminatedPlayers,
                              canSeeLovers: canSeeLovers,
                            ),
                          );
                        }),
                      ],
                    );
                  },
                ),
              ),
              // Zone d'action
              Expanded(
                flex: 2,
                child: Container(
                  decoration: BoxDecoration(
                    border: Border(
                      top: BorderSide(
                        color: Colors.deepPurpleAccent.withOpacity(0.3),
                        width: 1,
                      ),
                    ),
                  ),
                  child:
                      _isActionPending
                          ? Center(
                            child: Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                SizedBox(
                                  width: 20,
                                  height: 20,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                  ),
                                ),
                                SizedBox(width: 10),
                                Text(
                                  "Action en cours...",
                                  style: TextStyle(fontStyle: FontStyle.italic),
                                ),
                              ],
                            ),
                          )
                          : SingleChildScrollView(
                            padding: EdgeInsets.all(8),
                            child:
                                actionWidget ??
                                (myStatus == 'vivant'
                                    ? Center(
                                      child: Padding(
                                        padding: EdgeInsets.all(16),
                                        child: Text(
                                          "Attendez que les autres joueurs agissent...",
                                          style: TextStyle(
                                            fontStyle: FontStyle.italic,
                                            color: Colors.white70,
                                          ),
                                          textAlign: TextAlign.center,
                                        ),
                                      ),
                                    )
                                    : Center(
                                      child: Padding(
                                        padding: EdgeInsets.all(16),
                                        child: Text(
                                          "Vous êtes mort. Vous ne pouvez plus agir.",
                                          style: TextStyle(
                                            fontStyle: FontStyle.italic,
                                            color: Colors.grey,
                                          ),
                                          textAlign: TextAlign.center,
                                        ),
                                      ),
                                    )),
                          ),
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildPlayerAvatar(
    Map<String, dynamic> pData,
    String pId,
    bool isMe,
    List<String>? voters,
    String? captainId,
    List<String> lovers,
    bool amICurrentPlayerLoup,
    int nightNumber, {
    required String currentRoundState,
    required List<String> contaminatedPlayers,
    bool canSeeLovers = true,
  }) {
    bool isDead = pData['status'] == 'mort';
    String roleToShow =
        isDead ? "(${pData['revealedRole'] ?? pData['role']})" : "";
    bool isLover = lovers.contains(pId);
    bool isContaminated = contaminatedPlayers.contains(pId);
    bool isInfectedLoup = pData['infectionStatus'] == 'infecte';

    Color? avatarBgColor =
        isMe
            ? Colors.deepPurpleAccent
            : (isDead ? Colors.grey[800] : Colors.grey[600]);

    if (currentRoundState == 'nuit' &&
        (amICurrentPlayerLoup || isInfectedLoup) &&
        (GameData.roleCamps[pData['role']] == 'loups' || isInfectedLoup)) {
      avatarBgColor = Colors.red[900]!;
    }

    if (isContaminated && contaminatedPlayers.contains(widget.playerId)) {
      // ------------------
      avatarBgColor = Colors.lightGreen[900]!;
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Stack(
          alignment: Alignment.center,
          children: [
            CircleAvatar(
              radius: 30,
              backgroundColor: avatarBgColor,
              child: Padding(
                padding: EdgeInsets.all(4),
                child: FittedBox(
                  fit: BoxFit.scaleDown,
                  child: Text(
                    pData['name'] ?? '?',
                    style: TextStyle(
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                    ),
                    textAlign: TextAlign.center,
                    maxLines: 2,
                  ),
                ),
              ),
            ),

            if (pId == captainId)
              Positioned(
                top: 0,
                right: 0,
                child: Icon(Icons.king_bed, color: Colors.yellow, size: 20),
              ),

            if (isLover && canSeeLovers)
              Positioned(
                bottom: 0,
                right: 0,
                child: Icon(Icons.favorite, color: Colors.pink, size: 20),
              ),

            if (isInfectedLoup)
              Positioned(
                top: 0,
                left: 0,
                child: Icon(Icons.bug_report, color: Colors.purple, size: 20),
              ),

            if (isContaminated)
              Positioned(
                bottom: 0,
                left: 0,
                child: Icon(
                  Icons.sick,
                  color: Colors.lightGreenAccent,
                  size: 20,
                ),
              ),
          ],
        ),
        if (isDead)
          Text(
            roleToShow,
            style: TextStyle(color: Colors.grey[600], fontSize: 10),
          ),

        if (voters != null && voters.isNotEmpty)
          Column(
            children: [
              Text(
                "Voté par :",
                style: TextStyle(color: Colors.white70, fontSize: 10),
              ),
              ...voters.map(
                (voterName) => Text(
                  voterName,
                  style: TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                    fontSize: 10,
                  ),
                ),
              ),
            ],
          ),
      ],
    );
  }

  Widget _buildRatMaladeAction(
    Map<String, dynamic> players,
    List<String> playerOrder,
    String ratMaladeId,
    List<String> contaminatedPlayers,
  ) {
    List<String> _selectedContaminationTargets = [];

    // Joueurs vivants autres que le Rat Malade non encore contaminés
    List<String> alreadyContaminableAlivePlayers =
        playerOrder
            .where(
              (pId) =>
                  pId != ratMaladeId && players[pId]?['status'] == 'vivant',
            )
            .toList();
    bool allAlreadyContaminated =
        alreadyContaminableAlivePlayers.isEmpty ||
        alreadyContaminableAlivePlayers.every(
          (pId) => contaminatedPlayers.contains(pId),
        );

    // Si tous les autres joueurs vivants sont déjà contaminés → victoire imminente
    if (allAlreadyContaminated) {
      return Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(Icons.biotech, color: Colors.greenAccent, size: 60),
          SizedBox(height: 16),
          Text(
            "🎉 Tous les joueurs sont contaminés !",
            style: TextStyle(
              color: Colors.greenAccent,
              fontSize: 18,
              fontWeight: FontWeight.bold,
            ),
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 8),
          Text(
            "La victoire du Rat Malade est assurée !",
            style: TextStyle(color: Colors.white70),
            textAlign: TextAlign.center,
          ),
          SizedBox(height: 24),
          ElevatedButton(
            onPressed:
                _isActionPending
                    ? null
                    : () async {
                      setState(() => _isActionPending = true);
                      await _firebaseService
                          .startNextNightPhase(widget.gameCode)
                          .whenComplete(() {
                            if (mounted)
                              setState(() => _isActionPending = false);
                          });
                    },
            child:
                _isActionPending
                    ? SizedBox(
                      width: 20,
                      height: 20,
                      child: CircularProgressIndicator(
                        color: Colors.white,
                        strokeWidth: 2,
                      ),
                    )
                    : Text("Passer"),
          ),
        ],
      );
    }

    return StatefulBuilder(
      builder: (BuildContext context, StateSetter setState) {
        List<String> selectablePlayers =
            playerOrder
                .where(
                  (pId) =>
                      pId != ratMaladeId &&
                      players[pId]?['status'] == 'vivant' &&
                      !contaminatedPlayers.contains(pId) &&
                      !_selectedContaminationTargets.contains(pId),
                )
                .toList();

        // Nombre max de cibles (2 ou moins si moins de joueurs disponibles)
        int maxTargets =
            selectablePlayers.length + _selectedContaminationTargets.length < 2
                ? selectablePlayers.length +
                    _selectedContaminationTargets.length
                : 2;

        return Column(
          children: [
            Text(
              maxTargets < 2
                  ? "Choisissez UN joueur à contaminer :"
                  : "Choisissez jusqu'à DEUX joueurs à contaminer :",
              style: Theme.of(context).textTheme.bodyMedium,
              textAlign: TextAlign.center,
            ),
            SizedBox(height: 10),
            GridView.builder(
              shrinkWrap: true,
              physics: NeverScrollableScrollPhysics(),
              gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 3,
                childAspectRatio: 2.0,
              ),
              itemCount: selectablePlayers.length,
              itemBuilder: (context, index) {
                final pId = selectablePlayers[index];
                final pName = players[pId]?['name'] ?? 'Inconnu';
                bool isSelected = _selectedContaminationTargets.contains(pId);
                return Padding(
                  padding: const EdgeInsets.all(2.0),
                  child: ElevatedButton(
                    onPressed:
                        _selectedContaminationTargets.length >= maxTargets &&
                                !isSelected
                            ? null
                            : () {
                              setState(() {
                                if (isSelected) {
                                  _selectedContaminationTargets.remove(pId);
                                } else {
                                  _selectedContaminationTargets.add(pId);
                                }
                              });
                            },
                    child: Text(pName, textAlign: TextAlign.center),
                    style: ElevatedButton.styleFrom(
                      backgroundColor:
                          isSelected
                              ? Colors.lightGreen[800]
                              : Colors.lightGreen.withOpacity(0.6),
                      side:
                          isSelected
                              ? BorderSide(color: Colors.white, width: 2)
                              : BorderSide.none,
                    ),
                  ),
                );
              },
            ),
            SizedBox(height: 10),
            if (_selectedContaminationTargets.isNotEmpty)
              Text(
                "Cibles : ${_selectedContaminationTargets.map((id) => players[id]['name']).join(', ')}",
                style: TextStyle(color: Colors.white70),
              ),
            SizedBox(height: 10),
            ElevatedButton(
              onPressed:
                  _selectedContaminationTargets.isNotEmpty && !_isActionPending
                      ? () async {
                        setState(() => _isActionPending = true);
                        await _firebaseService
                            .ratMaladeContaminate(
                              widget.gameCode,
                              ratMaladeId,
                              _selectedContaminationTargets,
                            )
                            .whenComplete(() {
                              if (mounted)
                                setState(() => _isActionPending = false);
                            });
                      }
                      : null,
              child:
                  _isActionPending
                      ? SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(
                          color: Colors.white,
                          strokeWidth: 2,
                        ),
                      )
                      : Text("Contaminer"),
            ),
          ],
        );
      },
    );
  }

