  Widget _buildSyncTimer(Timestamp? startTime, int durationInSeconds) {
    if (startTime == null) return const SizedBox.shrink();

    // TweenAnimationBuilder permet un chrono visuel super fluide sans Timer bloquant et setState manuel, ce qui allège grandement le thread (Point 4)
    final endTime = startTime.toDate().add(
      Duration(seconds: durationInSeconds),
    );
    final remaining = endTime.difference(DateTime.now());

    if (remaining.isNegative)
      return Text(
        "0 s",
        style: Theme.of(
          context,
        ).textTheme.headlineSmall?.copyWith(color: Colors.redAccent),
      );

    return TweenAnimationBuilder<Duration>(
      duration: remaining,
      tween: Tween(begin: remaining, end: Duration.zero),
      builder: (BuildContext context, Duration value, Widget? child) {
        final seconds = value.inSeconds;
        return Text(
          "Temps restant : $seconds s",
          style: Theme.of(context).textTheme.headlineSmall?.copyWith(
            color: seconds < 20 ? Colors.redAccent : Colors.amberAccent,
          ),
        );
      },
    );
  }

  Widget _buildChatInterface(Map<String, dynamic> gameData, String playerId) {
    final Map<String, dynamic> playerData = Map<String, dynamic>.from(
      gameData['playerData'] ?? {},
    );
    final myData = playerData[playerId] ?? {};
    final myStatus = myData['status'] ?? 'vivant';
    final myRole = myData['role'] ?? 'Inconnu';
    final bool amILoup =
        GameData.roleCamps[myRole] == 'loups' ||
        myData['infectionStatus'] == 'infecte';
    final bool amIDead = myStatus == 'mort';
    final bool amILover = (gameData['lovers'] ?? []).contains(playerId);
    final bool amINecromancer = myRole == 'Nécromancien';
    final List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
    List<dynamic> currentChatMessages;
    bool canSendMessage = false;

    switch (_selectedChatType) {
      case 'wolf':
        currentChatMessages = List<dynamic>.from(
          gameData['wolfChatMessages'] ?? [],
        );
        canSendMessage = amILoup && !amIDead;
        break;
      case 'dead':
        currentChatMessages = List<dynamic>.from(
          gameData['deadChatMessages'] ?? [],
        );
        canSendMessage = amIDead || amINecromancer;
        break;
      case 'lover':
        String chatKey = '';
        List<String> lovers = List<String>.from(gameData['lovers'] ?? []);
        if (lovers.isNotEmpty &&
            (lovers[0] == playerId || lovers[1] == playerId)) {
          chatKey = lovers[0];
        }
        currentChatMessages = List<dynamic>.from(
          gameData['loverChatMessages']?[chatKey]?['messages'] ?? [],
        );
        canSendMessage = amILover && !amIDead;
        break;
      default:
        currentChatMessages = List<dynamic>.from(
          gameData['chatMessages'] ?? [],
        );
        canSendMessage = !amIDead;
        break;
    }

    return Column(
      children: [
        SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              FilterChip(
                label: Text("Global"),
                selected: _selectedChatType == 'global',
                materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                visualDensity: VisualDensity.compact,
                onSelected: (bool selected) {
                  if (selected) setState(() => _selectedChatType = 'global');
                },
              ),
              SizedBox(width: 4),

              if (GameData.roleCamps[myRole] == 'loups' ||
                  myData['infectionStatus'] == 'infecte' ||
                  (amIDead &&
                      (GameData.roleCamps[myRole] == 'loups' ||
                          myData['infectionStatus'] == 'infecte')))
                FilterChip(
                  label: Text("Loups"),
                  selected: _selectedChatType == 'wolf',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'wolf');
                  },
                ),
              SizedBox(width: 4),

              if (amIDead || amINecromancer)
                FilterChip(
                  label: Text("Morts"),
                  selected: _selectedChatType == 'dead',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'dead');
                  },
                ),
              SizedBox(width: 4),

              if (amILover && lovers.length == 2)
                FilterChip(
                  label: Text("Amoureux"),
                  selected: _selectedChatType == 'lover',
                  materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  visualDensity: VisualDensity.compact,
                  onSelected: (bool selected) {
                    if (selected) setState(() => _selectedChatType = 'lover');
                  },
                ),
            ],
          ),
        ),
        Expanded(
          child: ListView.builder(
            reverse: true,
            itemCount: currentChatMessages.length,
            itemBuilder: (context, index) {
              final messageData =
                  currentChatMessages[currentChatMessages.length - 1 - index];
              final senderId = messageData['senderId'];
              final senderName = messageData['senderName'];
              final message = messageData['message'];

              final isMine = senderId == playerId;
              Color messageBgColor =
                  isMine ? Colors.deepPurple[700]! : Colors.grey[800]!;

              if (_selectedChatType == 'wolf') {
                messageBgColor = Colors.red[900]!.withOpacity(0.5);
              } else if (_selectedChatType == 'dead') {
                messageBgColor = Colors.grey[700]!.withOpacity(0.5);
              }

              return Align(
                alignment:
                    isMine ? Alignment.centerRight : Alignment.centerLeft,
                child: Container(
                  margin: const EdgeInsets.symmetric(
                    vertical: 4.0,
                    horizontal: 8.0,
                  ),
                  padding: const EdgeInsets.all(10.0),
                  decoration: BoxDecoration(
                    color: messageBgColor,
                    borderRadius: BorderRadius.circular(12.0),
                  ),
                  child: Column(
                    crossAxisAlignment:
                        isMine
                            ? CrossAxisAlignment.end
                            : CrossAxisAlignment.start,
                    children: [
                      Text(
                        isMine ? "Vous" : senderName,
                        style: TextStyle(
                          fontWeight: FontWeight.bold,
                          color: Colors.white70,
                          fontSize: 12,
                        ),
                      ),
                      Text(
                        message,
                        style: TextStyle(color: Colors.white, fontSize: 14),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
        if (canSendMessage)
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 8.0, vertical: 4.0),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _chatController,
                    decoration: InputDecoration(
                      hintText: "Écrire un message...",
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(20),
                      ),
                      contentPadding: EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 6,
                      ),
                      isDense: true,
                    ),
                    onSubmitted: (text) {
                      if (text.trim().isNotEmpty) {
                        _firebaseService.sendChatMessage(
                          widget.gameCode,
                          playerId,
                          text.trim(),
                          _selectedChatType,
                        );

                        if (myRole == 'Loup Bavard' &&
                            myData['currentBavardWord'] != null &&
                            text.toLowerCase().contains(
                              myData['currentBavardWord'].toLowerCase(),
                            )) {
                          _firebaseService._db
                              .collection('games')
                              .doc(widget.gameCode)
                              .update({
                                'playerData.$playerId.hasSaidBavardWord': true,
                              });
                        }
                        _chatController.clear();
                      }
                    },
                  ),
                ),
                SizedBox(width: 8),
                IconButton(
                  icon: Icon(Icons.send, color: Colors.deepPurpleAccent),
                  onPressed: () {
                    if (_chatController.text.trim().isNotEmpty) {
                      _firebaseService.sendChatMessage(
                        widget.gameCode,
                        playerId,
                        _chatController.text.trim(),
                        _selectedChatType,
                      );

                      if (myRole == 'Loup Bavard' &&
                          myData['currentBavardWord'] != null &&
                          _chatController.text.toLowerCase().contains(
                            myData['currentBavardWord'].toLowerCase(),
                          )) {
                        _firebaseService._db
                            .collection('games')
                            .doc(widget.gameCode)
                            .update({
                              'playerData.$playerId.hasSaidBavardWord': true,
                            });
                      }
                      _chatController.clear();
                    }
                  },
                ),
              ],
            ),
          )
        else
          Padding(
            padding: const EdgeInsets.all(8.0),
            child: Text(
              "Vous ne pouvez pas écrire dans ce chat.",
              style: TextStyle(
                color: Colors.redAccent,
                fontStyle: FontStyle.italic,
              ),
              textAlign: TextAlign.center,
            ),
          ),
      ],
    );
  }
}

// Painter for straight-line-only Pictionary drawing mode
class _StraightLinePainter extends CustomPainter {
  final List<Offset> points; // flat list of [start1, end1, start2, end2, ...]
  final Offset? currentStart;
  final Offset? currentEnd;

  const _StraightLinePainter({
    required this.points,
    this.currentStart,
    this.currentEnd,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint =
        Paint()
          ..color = Colors.black
          ..strokeWidth = 3.0
          ..strokeCap = StrokeCap.round;

    for (int i = 0; i + 1 < points.length; i += 2) {
      canvas.drawLine(points[i], points[i + 1], paint);
    }
    if (currentStart != null && currentEnd != null) {
      canvas.drawLine(
        currentStart!,
        currentEnd!,
        paint..color = Colors.black54,
      );
    }
  }

  @override
  bool shouldRepaint(_StraightLinePainter old) =>
      old.points != points ||
      old.currentStart != currentStart ||
      old.currentEnd != currentEnd;
}

class DrawingScreen extends StatefulWidget {
  final String prompt;
  final bool limitStrokes;
  final int maxStrokes;
  final SignatureController? initialController;
  final String? backgroundDrawingData;

  const DrawingScreen({
    Key? key,
    required this.prompt,
    this.limitStrokes = false,
    this.maxStrokes = 30,
    this.initialController,
    this.backgroundDrawingData,
  }) : super(key: key);

  @override
  _DrawingScreenState createState() => _DrawingScreenState();
}

class _DrawingScreenState extends State<DrawingScreen> {
  late SignatureController _controller;
  int _currentStrokeCount = 0;

  final GlobalKey _canvasKey = GlobalKey();

  static const double CANVAS_WIDTH = 800.0;
  static const double CANVAS_HEIGHT = 600.0;

  @override
  void initState() {
    super.initState();
    _controller =
        widget.initialController ??
        SignatureController(
          penStrokeWidth: 5,
          penColor: Colors.black,
          exportBackgroundColor: Colors.transparent,
        );
    _controller.addListener(_updateStrokeCount);
  }

  @override
  void dispose() {
    _controller.removeListener(_updateStrokeCount);
    if (widget.initialController == null) {
      _controller.dispose();
    }
    super.dispose();
  }

  void _updateStrokeCount() {
    if (mounted) {
      setState(() {
        _currentStrokeCount =
            _controller.points.where((p) => p == null).length +
            (_controller.points.isNotEmpty ? 1 : 0);
      });
    }
  }

  Future<Uint8List?> _captureCanvas() async {
    try {
      RenderRepaintBoundary boundary =
          _canvasKey.currentContext!.findRenderObject()
              as RenderRepaintBoundary;

      ui.Image image = await boundary.toImage(pixelRatio: 1.0);
      ByteData? byteData = await image.toByteData(
        format: ui.ImageByteFormat.png,
      );

      return byteData?.buffer.asUint8List();
    } catch (e) {
      print("Erreur lors de la capture: $e");
      return null;
    }
  }

  Future<String?> _exportMergedImage() async {
    final Uint8List? canvasBytes = await _captureCanvas();

    if (canvasBytes == null) return null;

    final img.Image? capturedImage = img.decodeImage(canvasBytes);
    if (capturedImage == null) return null;

    final img.Image finalImage = img.copyResize(
      capturedImage,
      width: CANVAS_WIDTH.round(),
      height: CANVAS_HEIGHT.round(),
      interpolation:
          img
              .Interpolation
              .nearest, // Pas d'interpolation pour garder la netteté
    );

    return base64Encode(img.encodePng(finalImage));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Dessine !"),
        actions: [
          IconButton(
            icon: Icon(Icons.undo),
            onPressed: () => _controller.undo(),
          ),
          IconButton(
            icon: Icon(Icons.clear),
            onPressed: () => _controller.clear(),
          ),
        ],
        automaticallyImplyLeading: false,
      ),
      body: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              widget.prompt,
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.headlineSmall,
            ),
          ),
          Expanded(
            child: Center(
              child: Container(
                margin: EdgeInsets.all(16),
                width: CANVAS_WIDTH,
                height: CANVAS_HEIGHT,
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(11),

                  child: RepaintBoundary(
                    key: _canvasKey,
                    child: Stack(
                      children: [
                        Positioned.fill(child: Container(color: Colors.white)),

                        if (widget.backgroundDrawingData != null)
                          Positioned.fill(
                            child: Image.memory(
                              base64Decode(widget.backgroundDrawingData!),
                              fit: BoxFit.fill,
                            ),
                          ),

                        Positioned.fill(
                          child: Signature(
                            controller: _controller,
                            backgroundColor: Colors.transparent,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: ElevatedButton(
              onPressed: () async {
                if (_controller.isEmpty &&
                    widget.backgroundDrawingData == null) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text("Vous devez dessiner quelque chose !"),
                    ),
                  );
                  return;
                }

                final String? mergedBase64 = await _exportMergedImage();

                if (mergedBase64 != null) {
                  Navigator.of(context).pop({
                    'drawing': mergedBase64,
                    'strokeCount': _currentStrokeCount,
                  });
                } else {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text("Erreur lors de la sauvegarde du dessin."),
                    ),
                  );
                }
              },
              child: Text("J'ai fini !"),
            ),
          ),
        ],
      ),
    );
  }
}

class LocalPlayerSetupScreen extends StatefulWidget {
  @override
  _LocalPlayerSetupScreenState createState() => _LocalPlayerSetupScreenState();
}

class _LocalPlayerSetupScreenState extends State<LocalPlayerSetupScreen> {
  final _nameController = TextEditingController();
  final List<String> _players = [];

  void _addPlayer() {
    final name = _nameController.text.trim();
    if (name.isNotEmpty && !_players.contains(name)) {
      setState(() {
        _players.add(name);
        _nameController.clear();
      });
    } else if (name.isNotEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text("Ce joueur existe déjà !")));
    }
  }

  void _removePlayer(String name) {
    setState(() {
      _players.remove(name);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Participants (Mode Local)")),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              "Ajoutez les joueurs",
              style: Theme.of(context).textTheme.headlineSmall,
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _nameController,
                    decoration: InputDecoration(labelText: "Prénom du joueur"),
                    onSubmitted: (_) => _addPlayer(),
                  ),
                ),
                SizedBox(width: 8),
                IconButton(
                  icon: Icon(
                    Icons.add_circle,
                    color: Colors.deepPurpleAccent,
                    size: 30,
                  ),
                  onPressed: _addPlayer,
                ),
              ],
            ),
            SizedBox(height: 16),
            Expanded(
              child:
                  _players.isEmpty
                      ? Center(
                        child: Text(
                          "Ajoutez au moins 2 joueurs pour commencer.",
                          style: TextStyle(color: Colors.white70),
                        ),
                      )
                      : ListView.builder(
                        itemCount: _players.length,
                        itemBuilder: (context, index) {
                          final player = _players[index];
                          return Card(
                            child: ListTile(
                              leading: CircleAvatar(
                                child: Text((index + 1).toString()),
                              ),
                              title: Text(player),
                              trailing: IconButton(
                                icon: Icon(
                                  Icons.remove_circle_outline,
                                  color: Colors.redAccent,
                                ),
                                onPressed: () => _removePlayer(player),
                              ),
                            ),
                          );
                        },
                      ),
            ),
            SizedBox(height: 16),
            ElevatedButton(
              onPressed:
                  _players.length < 2
                      ? null
                      : () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder:
                                (_) => OfflineMenuScreen(players: _players),
                          ),
                        );
                      },
              child: Text("Choisir un jeu"),
            ),
          ],
        ),
      ),
    );
  }
}

class TeamSelectionDialog extends StatefulWidget {
  final List<String> allPlayers;
  final Widget Function(List<String> teamA, List<String> teamB)
  onTeamsConfirmed;
  final int minPlayersPerTeam;
  final String gameName;

  const TeamSelectionDialog({
    Key? key,
    required this.allPlayers,
    required this.onTeamsConfirmed,
    required this.gameName,
    this.minPlayersPerTeam = 2,
  }) : super(key: key);

  @override
  _TeamSelectionDialogState createState() => _TeamSelectionDialogState();
}

class _TeamSelectionDialogState extends State<TeamSelectionDialog> {
  late List<String> unassignedPlayers;
  List<String> teamA = [];
  List<String> teamB = [];

  @override
  void initState() {
    super.initState();
    unassignedPlayers = List.from(widget.allPlayers);
  }

  void _assignPlayer(String player, String team) {
    setState(() {
      unassignedPlayers.remove(player);
      teamA.remove(player);
      teamB.remove(player);

      if (team == 'A') teamA.add(player);
      if (team == 'B') teamB.add(player);
    });
  }

  void _unassignPlayer(String player) {
    setState(() {
      teamA.remove(player);
      teamB.remove(player);
      if (!unassignedPlayers.contains(player)) {
        unassignedPlayers.add(player);
      }
    });
  }

  void _autoBalance() {
    setState(() {
      List<String> all = List.from(widget.allPlayers)..shuffle();
      teamA.clear();
      teamB.clear();
      unassignedPlayers.clear();
      for (int i = 0; i < all.length; i++) {
        if (i % 2 == 0) {
          teamA.add(all[i]);
        } else {
          teamB.add(all[i]);
        }
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    bool canConfirm =
        unassignedPlayers.isEmpty &&
        teamA.length >= widget.minPlayersPerTeam &&
        teamB.length >= widget.minPlayersPerTeam;

    return AlertDialog(
      title: Text("Équipes pour ${widget.gameName}"),
      content: Container(
        width: double.maxFinite,
        height: 400,
        child: Column(
          children: [
            ElevatedButton.icon(
              icon: Icon(Icons.sync),
              label: Text("Équilibrer Aléatoirement"),
              onPressed: _autoBalance,
            ),
            SizedBox(height: 10),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  _buildTeamColumn(
                    "Équipe A (Rouge)",
                    teamA,
                    'A',
                    Colors.redAccent,
                  ),
                  _buildTeamColumn(
                    "Équipe B (Bleue)",
                    teamB,
                    'B',
                    Colors.blueAccent,
                  ),
                ],
              ),
            ),
            Divider(),
            Text("Joueurs non assignés"),
            Expanded(
              child: SingleChildScrollView(
                child: Wrap(
                  spacing: 6,
                  children:
                      unassignedPlayers
                          .map(
                            (p) => ActionChip(
                              label: Text(p),
                              onPressed: () {
                                if (teamA.length <= teamB.length) {
                                  _assignPlayer(p, 'A');
                                } else {
                                  _assignPlayer(p, 'B');
                                }
                              },
                            ),
                          )
                          .toList(),
                ),
              ),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text("Annuler"),
        ),
        ElevatedButton(
          onPressed:
              canConfirm
                  ? () {
                    Navigator.of(context).pop();
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (_) => widget.onTeamsConfirmed(teamA, teamB),
                      ),
                    );
                  }
                  : null,
          child: Text("Confirmer & Lancer"),
        ),
      ],
    );
  }

  Widget _buildTeamColumn(
    String title,
    List<String> team,
    String teamId,
    Color color,
  ) {
    return Expanded(
      child: Column(
        children: [
          Text(
            title,
            style: TextStyle(color: color, fontWeight: FontWeight.bold),
          ),
          Expanded(
            child: ListView(
              children:
                  team
                      .map(
                        (p) => ListTile(
                          title: Text(p),
                          trailing: IconButton(
                            icon: Icon(Icons.undo, size: 18),
                            onPressed: () => _unassignPlayer(p),
                          ),
                        ),
                      )
                      .toList(),
            ),
          ),
        ],
      ),
    );
  }
}

