class OfflineTruthOrDareScreen extends StatefulWidget {
  final List<String> players;
  OfflineTruthOrDareScreen({required this.players});

  @override
  _OfflineTruthOrDareScreenState createState() =>
      _OfflineTruthOrDareScreenState();
}

class _OfflineTruthOrDareScreenState extends State<OfflineTruthOrDareScreen> {
  String _difficulty = 'soft';
  String _currentContent = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;
  bool _playerHasToChoose = false;

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _playerHasToChoose = true;
      _currentContent = "";
    });
  }

  void _generateNewContent(String type) {
    List<String> contentList =
        (type == 'truth')
            ? GameData.offlineTruths[_difficulty]!
            : GameData.offlineDares[_difficulty]!;

    String content = contentList[Random().nextInt(contentList.length)];

    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex != -1) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        content = content.replaceAll(
          '{player}',
          otherPlayers[Random().nextInt(otherPlayers.length)],
        );
      } else {
        content = content.replaceAll('{player}', 'toi-même');
      }
    }

    setState(() {
      _currentContent = content;
      _playerHasToChoose = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final currentPlayer =
        _currentPlayerIndex != -1 ? widget.players[_currentPlayerIndex] : "";

    return Scaffold(
      appBar: AppBar(
        title: Text("Action ou Vérité"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Action ou Vérité'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: 'soft', label: Text('Soft')),
                ButtonSegment(value: 'hard', label: Text('Hard')),
                ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
              ],
              selected: {_difficulty},
              onSelectionChanged: (newSelection) {
                setState(() => _difficulty = newSelection.first);
              },
            ),
            SizedBox(height: 20),
            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: Duration(milliseconds: 500),
                  child: _buildMainContent(currentPlayer),
                ),
              ),
            ),
            SizedBox(height: 10),
            _buildGameControls(),
            SizedBox(height: 10),
            _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildMainContent(String currentPlayer) {
    if (_isSpinning) {
      return SpinTheWheelWidget(
        key: ValueKey('wheel'),
        players: widget.players,
        onSpinEnd: _onWheelStopped,
      );
    }
    if (_playerHasToChoose) {
      return Card(
        key: ValueKey('choice'),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 10),
              Text(
                "Choisis ton destin...",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    if (_currentContent.isNotEmpty) {
      return Card(
        key: ValueKey(_currentContent),
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "C'est au tour de",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 20),
              Text(
                _currentContent,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
            ],
          ),
        ),
      );
    }
    return Text(
      "Appuyez sur 'Lancer la roue' pour commencer !",
      style: Theme.of(
        context,
      ).textTheme.headlineSmall?.copyWith(color: Colors.white70),
      textAlign: TextAlign.center,
    );
  }

  Widget _buildGameControls() {
    if (_isSpinning) return SizedBox(height: 50);

    if (_playerHasToChoose) {
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          ElevatedButton(
            onPressed: () => _generateNewContent('truth'),
            child: Text("Vérité"),
          ),
          ElevatedButton(
            onPressed: () => _generateNewContent('dare'),
            child: Text("Action"),
          ),
        ],
      );
    }

    return ElevatedButton(
      onPressed: () => setState(() => _isSpinning = true),
      child: Text(
        _currentPlayerIndex == -1 ? "Lancer la roue" : "Tour Suivant",
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return Chip(
          label: Text(widget.players[index]),
          backgroundColor: isCurrent ? Colors.deepPurple : Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
        );
      }),
    );
  }
}

class OfflineGameScreen extends StatefulWidget {
  final String gameType;
  final List<String> players;
  OfflineGameScreen({required this.gameType, required this.players});

  @override
  _OfflineGameScreenState createState() => _OfflineGameScreenState();
}

class _OfflineGameScreenState extends State<OfflineGameScreen> {
  String _difficulty = 'soft';
  String _currentContent = "";
  String _title = "";
  bool _showCoinFlipResult = false;
  String _coinFlipChoice = "";
  String _coinFlipResult = "";
  int _currentPlayerIndex = -1;
  bool _isSpinning = false;
  Map<String, String> _dilemmaVotes = {};
  String? _activeDilemmaVoterId;
  String _dilemmaOptionA = "";
  String _dilemmaOptionB = "";

  @override
  void initState() {
    super.initState();
    _setTitle();
  }

  void _setTitle() {
    switch (widget.gameType) {
      case 'coin_flip':
        _title = "Jeu de la Pièce";
        break;
      case 'dilemma':
        _title = "Le Dilemme";
        break;
    }
  }

  void _onWheelStopped(int selectedIndex) {
    setState(() {
      _currentPlayerIndex = selectedIndex;
      _isSpinning = false;
      _generateNewContent();
      if (widget.gameType == 'dilemma' && widget.players.isNotEmpty) {
        _activeDilemmaVoterId = widget.players[selectedIndex];
      }
    });
  }

  String _processContent(String content) {
    if (content.contains('{player}')) {
      List<String> otherPlayers = List.from(widget.players);
      if (_currentPlayerIndex >= 0 &&
          _currentPlayerIndex < otherPlayers.length) {
        otherPlayers.removeAt(_currentPlayerIndex);
      }
      if (otherPlayers.isNotEmpty) {
        String randomPlayer =
            otherPlayers[Random().nextInt(otherPlayers.length)];
        return content.replaceAll('{player}', randomPlayer);
      } else {
        return content.replaceAll('{player}', 'toi-même');
      }
    }
    return content;
  }

  List<String> _splitDilemmaOptions(String content) {
    final normalized = content.trim().replaceFirst(RegExp(r'[؟?]+$'), '');
    final match = RegExp(r'\sou\s').firstMatch(normalized);

    if (match == null) {
      return [normalized, 'Je passe'];
    }

    final first = normalized.substring(0, match.start).trim();
    final second = normalized.substring(match.end).trim();

    if (first.isEmpty || second.isEmpty) {
      return [normalized, 'Je passe'];
    }

    return [first, second];
  }

  String _currentDilemmaWinner() {
    final optionACount =
        _dilemmaVotes.values.where((vote) => vote == 'A').length;
    final optionBCount =
        _dilemmaVotes.values.where((vote) => vote == 'B').length;

    if (optionACount == 0 && optionBCount == 0) {
      return '';
    }

    if (optionACount > optionBCount) {
      return 'A';
    }

    if (optionBCount > optionACount) {
      return 'B';
    }

    return 'TIE';
  }

  void _submitDilemmaVote(String playerId, String option) {
    setState(() {
      _activeDilemmaVoterId = playerId;
      _dilemmaVotes[playerId] = option;
    });
  }

  Widget _buildDilemmaOptionCard({
    required BuildContext context,
    required String optionKey,
    required String optionText,
    required Color color,
  }) {
    final voteCount =
        _dilemmaVotes.values.where((vote) => vote == optionKey).length;
    final totalVotes = widget.players.isEmpty ? 1 : widget.players.length;
    final progress = (voteCount / totalVotes).clamp(0.0, 1.0);
    final winner = _currentDilemmaWinner();
    final isWinning = winner == optionKey;
    final isTied = winner == 'TIE';

    return Expanded(
      child: GestureDetector(
        onTap:
            _activeDilemmaVoterId == null
                ? null
                : () => _submitDilemmaVote(_activeDilemmaVoterId!, optionKey),
        child: AnimatedContainer(
          duration: Duration(milliseconds: 250),
          padding: EdgeInsets.all(16),
          decoration: BoxDecoration(
            color:
                isWinning ? color.withOpacity(0.28) : color.withOpacity(0.16),
            borderRadius: BorderRadius.circular(18),
            border: Border.all(
              color: isWinning ? color : Colors.white12,
              width: isWinning ? 2.5 : 1.0,
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Text(
                optionText,
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.titleLarge?.copyWith(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                ),
              ),
              SizedBox(height: 14),
              ClipRRect(
                borderRadius: BorderRadius.circular(999),
                child: LinearProgressIndicator(
                  minHeight: 10,
                  value: progress,
                  backgroundColor: Colors.white10,
                  valueColor: AlwaysStoppedAnimation<Color>(color),
                ),
              ),
              SizedBox(height: 10),
              Text(
