      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            SegmentedButton<String>(
              segments: const [
                ButtonSegment(value: 'soft', label: Text('Soft')),
                ButtonSegment(value: 'hard', label: Text('Hard')),
                ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
              ],
              selected: {_difficulty},
              onSelectionChanged: (newSelection) {
                setState(() {
                  _difficulty = newSelection.first;
                  if (!_isSpinning && _currentContent.isNotEmpty) {
                    _generateNewContent();
                  }
                });
              },
            ),
            SizedBox(height: 20),
            Expanded(
              child: Center(
                child: AnimatedSwitcher(
                  duration: Duration(milliseconds: 500),
                  transitionBuilder:
                      (child, animation) =>
                          ScaleTransition(scale: animation, child: child),
                  child:
                      widget.gameType == 'dilemma' && _currentContent.isNotEmpty
                          ? _buildDilemmaVoteUI(context)
                          : _isSpinning
                          ? SpinTheWheelWidget(
                            key: ValueKey('wheel_spin'),
                            players: widget.players,
                            onSpinEnd: _onWheelStopped,
                          )
                          : (_currentContent.isEmpty
                              ? Text(
                                "Appuyez sur 'Lancer la roue' pour commencer !",
                                style: Theme.of(context).textTheme.headlineSmall
                                    ?.copyWith(color: Colors.white70),
                                textAlign: TextAlign.center,
                              )
                              : Card(
                                key: ValueKey<String>(_currentContent),
                                elevation: 4,
                                child: Padding(
                                  padding: const EdgeInsets.all(24.0),
                                  child: Column(
                                    mainAxisSize: MainAxisSize.min,
                                    mainAxisAlignment: MainAxisAlignment.center,
                                    children: [
                                      Text(
                                        "C'est au tour de",
                                        style:
                                            Theme.of(
                                              context,
                                            ).textTheme.bodyMedium,
                                      ),
                                      Text(
                                        currentPlayer,
                                        style: Theme.of(
                                          context,
                                        ).textTheme.headlineMedium?.copyWith(
                                          color: Colors.deepPurpleAccent,
                                        ),
                                      ),
                                      SizedBox(height: 20),
                                      Text(
                                        _currentContent,
                                        textAlign: TextAlign.center,
                                        style:
                                            Theme.of(
                                              context,
                                            ).textTheme.headlineSmall,
                                      ),
                                      if (widget.gameType == 'coin_flip' &&
                                          _showCoinFlipResult)
                                        _buildCoinFlipResult(),
                                    ],
                                  ),
                                ),
                              )),
                ),
              ),
            ),
            SizedBox(height: 10),
            _buildGameControls(),
            SizedBox(height: 10),
            if (widget.gameType != 'dilemma') _buildPlayerChips(),
          ],
        ),
      ),
    );
  }

  Widget _buildPlayerChips() {
    return Wrap(
      spacing: 8,
      runSpacing: 4,
      alignment: WrapAlignment.center,
      children: List.generate(widget.players.length, (index) {
        final isCurrent = index == _currentPlayerIndex && !_isSpinning;
        return Chip(
          label: Text(widget.players[index]),
          backgroundColor: isCurrent ? Colors.deepPurple : Color(0xFF333333),
          labelStyle: TextStyle(
            color: Colors.white,
            fontWeight: isCurrent ? FontWeight.bold : FontWeight.normal,
          ),
        );
      }),
    );
  }

  Widget _buildCoinFlipResult() {
    bool lost = _coinFlipChoice != _coinFlipResult;
    return Padding(
      padding: const EdgeInsets.only(top: 20.0),
      child: Column(
        children: [
          Text(
            "Tu as choisi $_coinFlipChoice. La pièce est tombée sur... $_coinFlipResult !",
            style: TextStyle(fontWeight: FontWeight.bold),
          ),
          SizedBox(height: 10),
          Text(
            lost
                ? "PERDU ! Révèle la question et ta réponse !"
                : "GAGNÉ ! Ton secret est en sécurité.",
            style: TextStyle(
              fontSize: 18,
              color: lost ? Colors.redAccent : Colors.greenAccent,
              fontWeight: FontWeight.bold,
            ),
            textAlign: TextAlign.center,
          ),
        ],
      ),
    );
  }

  Widget _buildGameControls() {
    if (_isSpinning) return SizedBox(height: 50);

    if (widget.gameType == 'dilemma' && _currentContent.isNotEmpty) {
      return SizedBox.shrink();
    }

    if (_currentContent.isEmpty) {
      return ElevatedButton(
        onPressed: () => setState(() => _isSpinning = true),
        child: Text("Lancer la roue"),
      );
    }

    if (widget.gameType == 'coin_flip' && _showCoinFlipResult ||
        widget.gameType == 'dilemma') {
      return ElevatedButton(
        onPressed:
            () => setState(() {
              _isSpinning = true;
              _currentContent = "";
            }),
        child: Text("Tour Suivant"),
      );
    }

    if (widget.gameType == 'coin_flip') {
      return Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          ElevatedButton(
            onPressed: () {
              _coinFlipChoice = "Pile";
              _flipCoin();
            },
            child: Text("Je choisis PILE"),
          ),
          ElevatedButton(
            onPressed: () {
              _coinFlipChoice = "Face";
              _flipCoin();
            },
            child: Text("Je choisis FACE"),
          ),
        ],
      );
    }
    return SizedBox.shrink();
  }
}

class SpinTheWheelWidget extends StatefulWidget {
  final List<String> players;
  final Function(int) onSpinEnd;

  const SpinTheWheelWidget({
    Key? key,
    required this.players,
    required this.onSpinEnd,
  }) : super(key: key);

  @override
  _SpinTheWheelWidgetState createState() => _SpinTheWheelWidgetState();
}

class _SpinTheWheelWidgetState extends State<SpinTheWheelWidget>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double> _rotationAnimation;
  double _finalRotationAngle = 0.0;
  final Random _random = Random();

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: Duration(seconds: 4),
    );
    _spinWheel();
  }

  void _spinWheel() {
    double randomRotations = 8 + _random.nextDouble() * 4;
    _finalRotationAngle = randomRotations * 2 * pi;

    _rotationAnimation = Tween<double>(
      begin: 0.0,
      end: _finalRotationAngle,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeOutCubic));

    _controller.forward(from: 0).then((_) {
      _determineWinner();
    });
  }

  void _determineWinner() {
    if (widget.players.isEmpty) return;
    double segmentAngle = (2 * pi) / widget.players.length;
    double normalizedAngle = _finalRotationAngle % (2 * pi);
    int winnerIndex =
        ((2 * pi - normalizedAngle) / segmentAngle).floor() %
        widget.players.length;
    widget.onSpinEnd(winnerIndex);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          "La roue tourne...",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 20),
        SizedBox(
          width: 300,
          height: 300,
          child: Stack(
            alignment: Alignment.center,
            children: [
              AnimatedBuilder(
                animation: _rotationAnimation,
                builder: (context, child) {
                  return Transform.rotate(
                    angle: _rotationAnimation.value,
                    child: SizedBox(
                      width: 280,
                      height: 280,
                      child: CustomPaint(
                        painter: _WheelPainter(widget.players),
                      ),
                    ),
                  );
                },
              ),
              Container(
                width: 30,
                height: 30,
                decoration: BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                  border: Border.all(color: Colors.deepPurple, width: 2),
                ),
              ),
              Positioned(
                top: 5,
                child: Icon(
                  Icons.keyboard_arrow_down,
                  color: Colors.redAccent,
                  size: 40,
                ),
              ),
            ],
          ),
        ),
      ],
    );
  }
}

class _WheelPainter extends CustomPainter {
  final List<String> players;
  static const List<Color> colors = [
    Color(0xFF1976D2),
    Color(0xFF388E3C),
    Color(0xFFF57C00),
    Color(0xFFD32F2F),
    Color(0xFF7B1FA2),
    Color(0xFF689F38),
    Color(0xFF0288D1),
    Color(0xFFE64A19),
    Color(0xFF5D4037),
    Color(0xFF455A64),
  ];

  _WheelPainter(this.players);

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    final radius = size.width / 2;
    if (players.isEmpty) return;
    final segmentAngle = 2 * pi / players.length;

    for (int i = 0; i < players.length; i++) {
      final paint =
          Paint()
            ..color = colors[i % colors.length]
            ..style = PaintingStyle.fill;
      final startAngle = -pi / 2 + i * segmentAngle;
      final path = Path();
      path.moveTo(center.dx, center.dy);
      path.arcTo(
        Rect.fromCircle(center: center, radius: radius),
        startAngle,
        segmentAngle,
        false,
      );
      path.close();
      canvas.drawPath(path, paint);

      final borderPaint =
          Paint()
            ..color = Colors.white
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2;
      canvas.drawPath(path, borderPaint);

      final textAngle = startAngle + segmentAngle / 2;
      final textRadius = radius * 0.65;
      final textCenter = Offset(
        center.dx + textRadius * cos(textAngle),
        center.dy + textRadius * sin(textAngle),
      );
      final textPainter = TextPainter(
        text: TextSpan(
          text: players[i],
          style: TextStyle(
            color: Colors.white,
            fontSize: 14,
            fontWeight: FontWeight.bold,
          ),
        ),
        textAlign: TextAlign.center,
        textDirection: TextDirection.ltr,
      );
      textPainter.layout();
      canvas.save();
      canvas.translate(textCenter.dx, textCenter.dy);
      double rotation = textAngle + pi / 2;
      if (rotation > pi / 2 && rotation < 3 * pi / 2) {
        rotation += pi;
      }
      canvas.rotate(rotation);
      textPainter.paint(
        canvas,
        Offset(-textPainter.width / 2, -textPainter.height / 2),
      );
      canvas.restore();
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

enum UndercoverGameState { setup, revealing, discussing, voting, result }

class UndercoverLocalGameScreen extends StatefulWidget {
  final List<String> players;
  const UndercoverLocalGameScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _UndercoverLocalGameScreenState createState() =>
      _UndercoverLocalGameScreenState();
}

class _UndercoverLocalGameScreenState extends State<UndercoverLocalGameScreen> {
  String _difficulty = 'soft';
  UndercoverGameState _gameState = UndercoverGameState.setup;
  int _currentPlayerRevealIndex = 0;
  Map<String, String> _playerRoles = {};
  String _wordCivil = "";
  String _wordUndercover = "";
  String _resultMessage = "";
  List<String> _activePlayers = [];
  String? _mrWhitePlayer;

  bool _includeMrWhite = true;
  bool _mrWhiteStarts = false;
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiWordPairs = [];

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

  void _startNewRound() {
    final random = Random();
    _activePlayers = List.from(widget.players);

    final minPlayers = _includeMrWhite ? 4 : 3;
    if (_activePlayers.length < minPlayers) {
      setState(() {
        _resultMessage =
            "Pas assez de joueurs ! Il faut au moins $minPlayers joueurs pour cette configuration.";
        _gameState = UndercoverGameState.result;
      });
      return;
    }

    List<String> shuffledPlayers = List.from(_activePlayers)..shuffle();

    String undercover = shuffledPlayers[0];
    _mrWhitePlayer = null;
    if (_includeMrWhite) {
      _mrWhitePlayer = shuffledPlayers[1];
    }

    final wordPairs =
        _aiWordPairs.isNotEmpty
            ? _aiWordPairs
            : GameData.offlineUndercoverData[_difficulty]!['wordPairs']!;
    final pair = wordPairs[random.nextInt(wordPairs.length)].split(':');
    _wordCivil = pair[0];
    _wordUndercover = pair[1];

    _playerRoles.clear();
    for (var player in _activePlayers) {
      if (player == undercover) {
        _playerRoles[player] = "Infiltré";
      } else if (player == _mrWhitePlayer) {
        _playerRoles[player] = "Mr. White";
      } else {
        _playerRoles[player] = "Civil";
      }
    }

    setState(() {
      _gameState = UndercoverGameState.revealing;
      _currentPlayerRevealIndex = 0;
      _resultMessage = "";
    });
  }

  void _nextPlayerReveal() {
    if (_currentPlayerRevealIndex < _activePlayers.length - 1) {
      setState(() => _currentPlayerRevealIndex++);
    } else {
      setState(() => _gameState = UndercoverGameState.discussing);
    }
  }

  void _eliminatePlayer(String player) {
    String role = _playerRoles[player]!;
    bool impostorsWin = role == "Civil";

    setState(() {
      _gameState = UndercoverGameState.result;
      if (impostorsWin) {
        _resultMessage = "$player était un Civil ! Les Imposteurs gagnent !";
      } else {
        _resultMessage = "$player était l'${role} ! Les Civils gagnent !";
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Undercover Local"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Undercover Local'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContentForState(),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case UndercoverGameState.setup:
        return _buildSetupPhase();
      case UndercoverGameState.revealing:
        return _buildRevealPhase();
      case UndercoverGameState.discussing:
        return _buildDiscussionPhase();
      case UndercoverGameState.voting:
        return _buildVotingPhase();
      case UndercoverGameState.result:
        return _buildResultPhase();
    }
  }

  Widget _buildSetupPhase() {
    return Center(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                "Configuration",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              SegmentedButton<String>(
                segments: const [
                  ButtonSegment(value: 'soft', label: Text('Soft')),
                  ButtonSegment(value: 'hard', label: Text('Hard')),
                  ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
                ],
                selected: {_difficulty},
                onSelectionChanged:
                    (newSelection) =>
                        setState(() => _difficulty = newSelection.first),
              ),
              SizedBox(height: 20),
              SwitchListTile.adaptive(
                title: Text("Inclure Mr. White ?"),
                subtitle: Text(
                  _includeMrWhite
                      ? "Requiert 4+ joueurs"
                      : "Requiert 3+ joueurs",
                ),
                value: _includeMrWhite,
                onChanged: (val) => setState(() => _includeMrWhite = val),
                secondary: Icon(Icons.person_off),
              ),
              if (_includeMrWhite)
                SwitchListTile.adaptive(
                  title: Text("Mr. White commence ?"),
                  subtitle: Text("Il devra donner le premier indice"),
                  value: _mrWhiteStarts,
                  onChanged: (val) => setState(() => _mrWhiteStarts = val),
                  secondary: Icon(Icons.play_arrow),
                ),
              Consumer<PlayerState>(
                builder: (ctx, ps, _) {
                  if (!ps.isPremium) return SizedBox.shrink();
                  return Container(
                    margin: EdgeInsets.only(bottom: 12),
                    decoration: BoxDecoration(
                      border: Border.all(color: Colors.amberAccent),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    padding: EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Icon(
                              Icons.auto_awesome,
                              color: Colors.amberAccent,
                              size: 18,
                            ),
                            SizedBox(width: 8),
                            Text(
                              "IA Premium",
                              style: TextStyle(
                                color: Colors.amberAccent,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                        SizedBox(height: 8),
                        TextField(
                          controller: _aiController,
                          decoration: InputDecoration(
                            labelText: "Thème pour les paires de mots",
                            hintText:
                                "ex: animaux:objets, cuisine... (format civil:infiltré)",
                            border: OutlineInputBorder(),
                          ),
                          maxLines: 1,
                        ),
                      ],
                    ),
                  );
                },
              ),
              SizedBox(height: 30),
              ElevatedButton(
                onPressed:
                    _isAiLoading
                        ? null
                        : () async {
                          if (_aiController.text.trim().isNotEmpty) {
                            setState(() => _isAiLoading = true);
                            try {
                              final words =
                                  await FirebaseService.generateAiWords(
                                    instructions: _aiController.text.trim(),
                                    count: 30,
                                    gameType: 'Infiltré & Mr. White',
                                  );
                              _aiWordPairs = words;
                            } catch (e) {
                              print('AI error: $e');
                            } finally {
                              if (mounted) setState(() => _isAiLoading = false);
                            }
                          } else {
                            _aiWordPairs = [];
                          }
                          _startNewRound();
                        },
                child:
                    _isAiLoading
                        ? Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(
                                color: Colors.white,
                                strokeWidth: 2,
                              ),
                            ),
                            SizedBox(width: 8),
                            Text("Génération IA..."),
                          ],
                        )
                        : Text("Commencer la manche"),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildRevealPhase() {
    final currentPlayer = _activePlayers[_currentPlayerRevealIndex];
    return Center(
      key: ValueKey(_currentPlayerRevealIndex),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "Passe le téléphone à",
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              SizedBox(height: 10),
              Text(
                currentPlayer,
                style: Theme.of(context).textTheme.headlineMedium?.copyWith(
                  color: Colors.deepPurpleAccent,
                ),
              ),
              SizedBox(height: 20),
              Text(
                "Regarde ton rôle et ne le montre à personne !",
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 30),
              ElevatedButton(
                onPressed: () => _showRoleDialog(currentPlayer),
                child: Text("Voir mon rôle"),
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _showRoleDialog(String player) {
    String role = _playerRoles[player]!;
    String content = "Tu es: $role\n\n";
    if (role == "Civil") content += "Ton mot est : $_wordCivil";
    if (role == "Infiltré") content += "Ton mot est : $_wordUndercover";
    if (role == "Mr. White") content += "Tu n'as pas de mot. Bluffe !";

    showDialog(
      context: context,
      barrierDismissible: false,
      builder:
          (context) => AlertDialog(
            title: Text("Ton Rôle, $player"),
            content: Text(
              content,
              style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold),
            ),
            actions: [
              TextButton(
                onPressed: () {
                  Navigator.of(context).pop();
                  _nextPlayerReveal();
                },
                child: Text("J'ai compris !"),
              ),
            ],
          ),
    );
  }

  Widget _buildDiscussionPhase() {
    String startingPlayerInstruction = "";
    if (_includeMrWhite && _mrWhiteStarts && _mrWhitePlayer != null) {
      startingPlayerInstruction =
          "\n\n$_mrWhitePlayer, comme convenu, tu commences !";
    }

    return Center(
      key: ValueKey('discuss_phase'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                "À vos discussions !",
                style: Theme.of(context).textTheme.headlineMedium,
              ),
              SizedBox(height: 10),
              Text(
                "Tout le monde connaît son rôle. À tour de rôle, donnez un mot-indice. Quand vous êtes prêts, passez au vote pour éliminer quelqu'un.$startingPlayerInstruction",
                textAlign: TextAlign.center,
                style: Theme.of(context).textTheme.titleLarge,
              ),
              SizedBox(height: 30),
              ElevatedButton(
                onPressed:
                    () =>
                        setState(() => _gameState = UndercoverGameState.voting),
                child: Text("Passer au Vote"),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildVotingPhase() {
    return Column(
      key: ValueKey('vote_phase'),
      children: [
        Text(
          "Qui éliminer ?",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 10),
        Expanded(
          child: ListView.builder(
            itemCount: _activePlayers.length,
            itemBuilder: (context, index) {
              final player = _activePlayers[index];
              return Card(
                child: ListTile(
                  title: Text(player),
                  onTap: () => _eliminatePlayer(player),
                  trailing: Icon(Icons.gavel),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildResultPhase() {
    return Center(
      key: ValueKey('result_phase'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                "Résultat du tour",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              Text(
                _resultMessage,
                textAlign: TextAlign.center,
                style: Theme.of(
                  context,
                ).textTheme.titleLarge?.copyWith(color: Colors.amber),
              ),
              if (_resultMessage.contains("gagnent")) ...[
                SizedBox(height: 20),
                Text(
                  "Le mot des civils était : $_wordCivil",
                  style: TextStyle(fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
                Text(
                  "Le mot de l'infiltré était : $_wordUndercover",
                  style: TextStyle(fontStyle: FontStyle.italic),
                  textAlign: TextAlign.center,
                ),
              ],
              SizedBox(height: 30),
              ElevatedButton(
                onPressed:
                    () =>
                        setState(() => _gameState = UndercoverGameState.setup),
                child: Text("Nouvelle Manche"),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

enum HotPotatoState { setup, playing, exploded }

class HotPotatoLocalScreen extends StatefulWidget {
  final List<String> players;
  const HotPotatoLocalScreen({Key? key, required this.players})
    : super(key: key);

  @override
  _HotPotatoLocalScreenState createState() => _HotPotatoLocalScreenState();
}

class _HotPotatoLocalScreenState extends State<HotPotatoLocalScreen>
    with TickerProviderStateMixin {
  HotPotatoState _gameState = HotPotatoState.setup;
  Timer? _turnTimer;
  int _secondsLeft = 0;
  final Random _random = Random();
  final _answerController = TextEditingController();

  int _currentPlayerIndex = 0;
  List<String> _usedAnswers = [];

  String _selectedCategory = GameData.localHotPotatoCategories.keys.first;
  int _turnDuration = 10;
  bool _useGlobalTimer = false;
  int _globalDuration = 30;

  @override
  void dispose() {
    _turnTimer?.cancel();
    _answerController.dispose();
    super.dispose();
  }

  void _startGame() {
    _turnTimer?.cancel(); // Annule tout timer précédent par sécurité
    _usedAnswers.clear();
    _currentPlayerIndex = _random.nextInt(widget.players.length);

    if (_useGlobalTimer) {
      _secondsLeft = _globalDuration;
    } else {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        // Mode aléatoire
        duration = 5 + _random.nextInt(11); // 5 à 15 secondes
      }
      _secondsLeft = duration;
    }

    _turnTimer = Timer.periodic(Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (_secondsLeft > 1) {
        setState(() => _secondsLeft--);
      } else {
        _explode();
      }
    });

    setState(() {
      _gameState = HotPotatoState.playing;
    });
  }

  void _explode() {
    _turnTimer?.cancel();
    HapticFeedback.vibrate();
    setState(() {
      _gameState = HotPotatoState.exploded;
    });
  }

  void _passPotato() {
    final answer = _answerController.text.trim().toLowerCase();
    if (answer.isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text("Tu dois écrire une réponse !")));
      return;
    }
    if (_usedAnswers.contains(answer)) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Cette réponse a déjà été donnée !")),
      );
      return;
    }

    _answerController.clear();
    FocusScope.of(context).unfocus();

    if (!_useGlobalTimer) {
      int duration = _turnDuration;
      if (_turnDuration == 0) {
        duration = 5 + _random.nextInt(11);
      }
      _secondsLeft = duration;
    }

    setState(() {
      _usedAnswers.add(answer);
      _currentPlayerIndex = (_currentPlayerIndex + 1) % widget.players.length;
    });
  }

  void _resetGame() {
    _turnTimer?.cancel();
    setState(() {
      _gameState = HotPotatoState.setup;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("La Patate Chaude"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'La Patate Chaude'),
          ),
        ],
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: AnimatedSwitcher(
            duration: Duration(milliseconds: 300),
            child: _buildContentForState(),
          ),
        ),
      ),
    );
  }

  Widget _buildContentForState() {
    switch (_gameState) {
      case HotPotatoState.setup:
        return _buildSetupScreen();
      case HotPotatoState.playing:
        return _buildPlayingScreen();
      case HotPotatoState.exploded:
        return _buildExplodedScreen();
    }
  }

  Widget _buildSetupScreen() {
    return SingleChildScrollView(
      key: ValueKey('setup'),
      child: Card(
        child: Padding(
          padding: const EdgeInsets.all(24.0),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Icon(Icons.whatshot, size: 80, color: Colors.orangeAccent),
              SizedBox(height: 10),
              Text(
                "La Patate Chaude",
                style: Theme.of(context).textTheme.headlineMedium,
                textAlign: TextAlign.center,
              ),
              SizedBox(height: 20),
              DropdownButtonFormField<String>(
                value: _selectedCategory,
                items:
                    GameData.localHotPotatoCategories.keys
                        .map(
                          (cat) =>
                              DropdownMenuItem(value: cat, child: Text(cat)),
                        )
                        .toList(),
                onChanged: (val) => setState(() => _selectedCategory = val!),
                decoration: InputDecoration(labelText: "Catégorie"),
              ),
              SizedBox(height: 20),

              Text(
                "Durée du tour (par joueur)",
                style: Theme.of(context).textTheme.bodyMedium,
              ),
              SizedBox(height: 8),
              SegmentedButton<int>(
                // Remplacer Wrap par SegmentedButton pour la cohérence
                segments: const [
                  ButtonSegment(value: 10, label: Text('10s')),
                  ButtonSegment(value: 15, label: Text('15s')),
                  ButtonSegment(value: 0, label: Text('Aléatoire')),
                ],
                selected: {_turnDuration},
                onSelectionChanged:
                    (s) => setState(() => _turnDuration = s.first),
                style: ButtonStyle(
                  foregroundColor: MaterialStateProperty.resolveWith<Color?>((
                    states,
                  ) {
                    return _useGlobalTimer ? Colors.grey : null;
                  }),
                ),
              ),

              Divider(height: 30),

              SwitchListTile.adaptive(
                title: Text("Compte à rebours global"),
                subtitle: Text("Le chrono ne se réinitialise pas."),
                value: _useGlobalTimer,
                onChanged: (val) => setState(() => _useGlobalTimer = val),
                secondary: Icon(Icons.hourglass_bottom),
              ),
              if (_useGlobalTimer) ...[
                SizedBox(height: 10),
                Text(
                  "Durée du chrono global",
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
                SizedBox(height: 8),
                SegmentedButton<int>(
                  segments: const [
                    ButtonSegment(value: 30, label: Text('30s')),
                    ButtonSegment(value: 45, label: Text('45s')),
                    ButtonSegment(value: 60, label: Text('60s')),
                  ],
                  selected: {_globalDuration},
                  onSelectionChanged:
                      (s) => setState(() => _globalDuration = s.first),
                ),
              ],

              SizedBox(height: 20),
              ElevatedButton(onPressed: _startGame, child: Text("Commencer !")),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildPlayingScreen() {
    return Column(
      key: ValueKey('playing'),
      children: [
        Text(
          "$_secondsLeft s",
          style: Theme.of(context).textTheme.headlineMedium?.copyWith(
            color: _secondsLeft < 5 ? Colors.redAccent : Colors.white,
          ),
        ),
        SizedBox(height: 10),
        Text(
          "C'est à ${widget.players[_currentPlayerIndex]} !",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 20),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                Text(
                  "Catégorie:",
                  style: Theme.of(context).textTheme.bodyMedium,
                ),
                Text(
                  _selectedCategory,
                  style: Theme.of(context).textTheme.headlineSmall,
                  textAlign: TextAlign.center,
                ),
              ],
            ),
          ),
        ),
        SizedBox(height: 20),
        TextField(
          controller: _answerController,
          decoration: InputDecoration(labelText: "Ta réponse rapide !"),
          onSubmitted: (_) => _passPotato(),
        ),
        SizedBox(height: 20),
        ElevatedButton(
          onPressed: _passPotato,
          child: Text("Fait ! Je passe !"),
        ),
        SizedBox(height: 20),
        Expanded(
          child: SingleChildScrollView(
            child: Column(
              children: [
                if (_usedAnswers.isNotEmpty)
                  Text(
                    "Mots déjà utilisés :",
                    style: Theme.of(context).textTheme.bodyMedium,
                  ),
                Wrap(
                  spacing: 8.0,
                  runSpacing: 4.0,
                  children:
                      _usedAnswers
                          .map((answer) => Chip(label: Text(answer)))
                          .toList(),
                ),
              ],
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildExplodedScreen() {
    final loser = widget.players[_currentPlayerIndex];
    final gage =
        GameData.localHotPotatoGages[_random.nextInt(
          GameData.localHotPotatoGages.length,
        )];
    return Column(
      key: ValueKey('exploded'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Icon(Icons.local_fire_department, size: 100, color: Colors.redAccent),
        SizedBox(height: 20),
        Text(
          "BOOM !",
          style: Theme.of(context).textTheme.headlineMedium?.copyWith(
            fontSize: 48,
            color: Colors.redAccent,
          ),
        ),
        SizedBox(height: 20),
        Text(
          "$loser a perdu !",
          style: Theme.of(context).textTheme.headlineSmall,
        ),
        SizedBox(height: 10),
        Text("Son gage :", style: Theme.of(context).textTheme.bodyMedium),
        SizedBox(height: 10),
        Card(
          child: Padding(
            padding: const EdgeInsets.all(16.0),
            child: Text(
              gage.replaceAll('{player}', 'un autre joueur'),
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.titleLarge,
            ),
          ),
        ),
        SizedBox(height: 40),
        ElevatedButton(onPressed: _resetGame, child: Text("Rejouer")),
      ],
    );
  }
}

enum GamePhase { setup, input, voting, result }

class SynonymOrBannedLocalScreen extends StatefulWidget {
  final List<String> players;
  const SynonymOrBannedLocalScreen({Key? key, required this.players})
    : super(key: key);
  @override
  _SynonymOrBannedLocalScreenState createState() =>
      _SynonymOrBannedLocalScreenState();
}

class _SynonymOrBannedLocalScreenState
    extends State<SynonymOrBannedLocalScreen> {
  GamePhase _phase = GamePhase.setup;
  String _difficulty = 'soft';
  String _currentWord = "";
  int _currentPlayerIndex = 0;
  final Map<String, String> _answers = {};
  final _answerController = TextEditingController();
  String _bannedPlayer = "";
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiWordPool = [];

  void _startRound() {
    final words =
        _aiWordPool.isNotEmpty
            ? _aiWordPool
            : GameData.localSynonymOrBanned[_difficulty]!['words']!;
    setState(() {
      _currentWord = words[Random().nextInt(words.length)];
      _currentPlayerIndex = 0;
      _answers.clear();
      _bannedPlayer = "";
      _phase = GamePhase.input;
    });
  }

  void _submitAnswer() {
    final answer = _answerController.text.trim();
    if (answer.isNotEmpty) {
      setState(() {
        _answers[widget.players[_currentPlayerIndex]] = answer;
        _answerController.clear();
        if (_currentPlayerIndex < widget.players.length - 1) {
          _currentPlayerIndex++;
        } else {
          _phase = GamePhase.voting;
        }
      });
    }
  }

  void _banAnswer(String answer) {
    String bannedPlayer = "";
    _answers.forEach((player, ans) {
      if (ans == answer) {
        bannedPlayer = player;
      }
    });
    setState(() {
      _bannedPlayer = bannedPlayer;
      _phase = GamePhase.result;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Synonyme ou Banni"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Synonyme ou Banni'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContent(),
        ),
      ),
    );
  }

  Widget _buildContent() {
    switch (_phase) {
      case GamePhase.setup:
        return _buildSetupPhase();
      case GamePhase.input:
        return _buildInputPhase();
      case GamePhase.voting:
        return _buildVotingPhase();
      case GamePhase.result:
        return _buildResultPhase();
    }
  }

  Widget _buildSetupPhase() {
    return Column(
      key: ValueKey('setup'),
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Text(
          "Configuration",
          style: Theme.of(context).textTheme.headlineMedium,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        SegmentedButton<String>(
          segments: const [
            ButtonSegment(value: 'soft', label: Text('Soft')),
            ButtonSegment(value: 'hard', label: Text('Hard')),
            ButtonSegment(value: 'hardcore', label: Text('Hardcore')),
          ],
          selected: {_difficulty},
          onSelectionChanged: (s) => setState(() => _difficulty = s.first),
        ),
        SizedBox(height: 40),
        Consumer<PlayerState>(
          builder: (ctx, ps, _) {
            if (!ps.isPremium) return SizedBox.shrink();
            return Container(
              margin: EdgeInsets.only(bottom: 12),
              decoration: BoxDecoration(
                border: Border.all(color: Colors.amberAccent),
                borderRadius: BorderRadius.circular(12),
              ),
              padding: EdgeInsets.all(12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Icon(
                        Icons.auto_awesome,
                        color: Colors.amberAccent,
                        size: 18,
                      ),
                      SizedBox(width: 8),
                      Text(
                        "IA Premium",
                        style: TextStyle(
                          color: Colors.amberAccent,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ),
                  SizedBox(height: 8),
                  TextField(
                    controller: _aiController,
                    decoration: InputDecoration(
                      labelText: "Thème pour les mots",
                      hintText: "ex: animaux, cuisine, film...",
                      border: OutlineInputBorder(),
                    ),
                    maxLines: 1,
                  ),
                ],
              ),
            );
          },
        ),
        ElevatedButton(
          onPressed:
              _isAiLoading
                  ? null
                  : () async {
                    if (_aiController.text.trim().isNotEmpty) {
                      setState(() => _isAiLoading = true);
                      try {
                        _aiWordPool = await FirebaseService.generateAiWords(
                          instructions: _aiController.text.trim(),
                          count: 40,
                          gameType: 'Synonyme ou Banni',
                        );
                      } catch (e) {
                        print('AI error: $e');
                      } finally {
                        if (mounted) setState(() => _isAiLoading = false);
                      }
                    } else {
                      _aiWordPool = [];
                    }
                    _startRound();
                  },
          child:
              _isAiLoading
                  ? Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      SizedBox(
                        width: 16,
                        height: 16,
                        child: CircularProgressIndicator(
                          color: Colors.white,
                          strokeWidth: 2,
                        ),
                      ),
                      SizedBox(width: 8),
                      Text("Génération IA..."),
                    ],
                  )
                  : Text("Commencer la manche"),
        ),
      ],
    );
  }

  Widget _buildInputPhase() {
    final currentPlayer = widget.players[_currentPlayerIndex];
    return Column(
      key: ValueKey('input_$_currentPlayerIndex'),
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Text(
          "Passe le téléphone à $currentPlayer",
          style: Theme.of(context).textTheme.titleLarge,
        ),
        SizedBox(height: 20),
        Text("Le mot est :", style: Theme.of(context).textTheme.bodyMedium),
        Text(
          "$_currentWord",
          style: Theme.of(context).textTheme.headlineMedium,
        ),
        SizedBox(height: 30),
        TextField(
          controller: _answerController,
          decoration: InputDecoration(labelText: "Ton synonyme..."),
          onSubmitted: (_) => _submitAnswer(),
        ),
        SizedBox(height: 20),
        ElevatedButton(
          onPressed: _submitAnswer,
          child: Text("Valider et passer"),
        ),
      ],
    );
  }

  Widget _buildVotingPhase() {
    final shuffledAnswers = _answers.values.toList()..shuffle();
    return Column(
      key: ValueKey('voting'),
      children: [
        Text(
          "Votez pour bannir la pire proposition !",
          style: Theme.of(context).textTheme.headlineSmall,
          textAlign: TextAlign.center,
        ),
        Text(
          "Le mot était : $_currentWord",
          style: Theme.of(context).textTheme.bodyMedium,
        ),
        SizedBox(height: 20),
        Expanded(
          child: ListView.builder(
            itemCount: shuffledAnswers.length,
            itemBuilder: (context, index) {
              final answer = shuffledAnswers[index];
              return Card(
                child: ListTile(
                  title: Text(answer),
                  onTap: () => _banAnswer(answer),
                  trailing: Icon(Icons.gavel),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildResultPhase() {
    return Column(
      key: ValueKey('result'),
      mainAxisAlignment: MainAxisAlignment.center,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Icon(Icons.block, color: Colors.redAccent, size: 80),
        SizedBox(height: 20),
        Text(
          "La proposition de $_bannedPlayer a été bannie !",
          style: Theme.of(context).textTheme.headlineMedium,
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 20),
        Text(
          "$_bannedPlayer a perdu cette manche !",
          style: Theme.of(
            context,
          ).textTheme.titleLarge?.copyWith(color: Colors.amber),
          textAlign: TextAlign.center,
        ),
        SizedBox(height: 40),
        ElevatedButton(
          onPressed: () => setState(() => _phase = GamePhase.setup),
          child: Text("Nouvelle manche"),
        ),
      ],
    );
  }
}

class WhoIsMostLikelyLocalScreen extends StatefulWidget {
  final List<String> players;
  const WhoIsMostLikelyLocalScreen({Key? key, required this.players})
    : super(key: key);
  @override
  _WhoIsMostLikelyLocalScreenState createState() =>
      _WhoIsMostLikelyLocalScreenState();
}

class _WhoIsMostLikelyLocalScreenState
    extends State<WhoIsMostLikelyLocalScreen> {
  String _difficulty = 'soft';
  String _currentQuestion = "";
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiQuestions = [];

  void _getNewQuestion() {
    if (_aiQuestions.isNotEmpty) {
      setState(
        () =>
            _currentQuestion =
                _aiQuestions[Random().nextInt(_aiQuestions.length)],
      );
      return;
    }
    final questions = GameData.localWhoIsMostLikely[_difficulty]!;
    setState(() {
      _currentQuestion = questions[Random().nextInt(questions.length)];
    });
  }

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

