enum CodenamesLocalGameState {
  setup,
  passPhoneToMasterSpy,
  masterSpyTurn,
  passPhoneToAgents,
  agentTurn,
  gameOver,
}

class CodenamesLocalGameScreen extends StatefulWidget {
  final List<String> players;
  final List<String>? redTeam; // Équipes optionnelles
  final List<String>? blueTeam;

  const CodenamesLocalGameScreen({
    Key? key,
    required this.players,
    this.redTeam,
    this.blueTeam,
  }) : super(key: key);

  @override
  _CodenamesLocalGameScreenState createState() =>
      _CodenamesLocalGameScreenState();
}

class _CodenamesLocalGameScreenState extends State<CodenamesLocalGameScreen> {
  CodenamesLocalGameState _gameState = CodenamesLocalGameState.setup;
  bool _masterSpyReady = false; // Cache la carte-clé jusqu’à confirmation
  List<String> _redTeam = [];
  List<String> _blueTeam = [];
  String? _masterSpyRed;
  String? _masterSpyBlue;
  String _activeTeam = 'red';
  Map<String, String> _wordKeyMap = {};
  Map<String, bool> _revealedWords = {};
  List<String> _boardWords = [];

  int _redScore = 0;
  int _blueScore = 0;
  String? _currentClue;
  int _clueCount = 0;
  int _guessesLeft = 0;
  String _gameResult = "";
  final TextEditingController _aiController = TextEditingController();
  bool _isAiLoading = false;
  List<String> _aiCustomWords = [];

  @override
  void initState() {
    super.initState();
    if (widget.redTeam != null && widget.blueTeam != null) {
      _redTeam = widget.redTeam!;
      _blueTeam = widget.blueTeam!;
    } else if (widget.players.length < 4) {
      _gameResult =
          "Il faut au moins 4 joueurs pour Codenames (2 par équipe) !";
      _gameState = CodenamesLocalGameState.gameOver;
    }
  }

  @override
  void dispose() {
    _aiController.dispose();
    super.dispose();
  }

  void _startGame() {
    List<String> allWords =
        _aiCustomWords.isNotEmpty
            ? (List.from(_aiCustomWords)..shuffle())
            : (List.from(GameData.codenamesWords)..shuffle());
    _boardWords = allWords.take(25).toList();

    _wordKeyMap.clear();
    _revealedWords.clear();

    List<String> tempWords = List.from(_boardWords)..shuffle();
    int redCount = 9;
    int blueCount = 8;
    String assassinWord = tempWords.removeAt(0);

    for (int i = 0; i < redCount; i++)
      _wordKeyMap[tempWords.removeAt(0)] = 'red';
    for (int i = 0; i < blueCount; i++)
      _wordKeyMap[tempWords.removeAt(0)] = 'blue';
    _wordKeyMap[assassinWord] = 'assassin';
    tempWords.forEach((word) => _wordKeyMap[word] = 'neutral');

    _boardWords.forEach((word) => _revealedWords[word] = false);

    List<String> shuffledPlayers = List.from(widget.players)..shuffle();
    int mid = shuffledPlayers.length ~/ 2;
    _redTeam = shuffledPlayers.sublist(0, mid);
    _blueTeam = shuffledPlayers.sublist(mid);

    _masterSpyRed =
        _redTeam.isNotEmpty
            ? _redTeam[Random().nextInt(_redTeam.length)]
            : null;
    _masterSpyBlue =
        _blueTeam.isNotEmpty
            ? _blueTeam[Random().nextInt(_blueTeam.length)]
            : null;

    if (_redTeam.isEmpty ||
        _blueTeam.isEmpty ||
        _masterSpyRed == null ||
        _masterSpyBlue == null) {
      setState(() {
        _gameResult =
            "Impossible de former les équipes (taille minimale non atteinte). Redémarrer avec au moins 4 joueurs.";
        _gameState = CodenamesLocalGameState.gameOver;
      });
      return;
    }

    _redScore = redCount;
    _blueScore = blueCount;
    _activeTeam = 'red';
    _masterSpyReady = false;

    setState(() {
      _gameState = CodenamesLocalGameState.passPhoneToMasterSpy;
      _currentClue = null;
      _clueCount = 0;
      _guessesLeft = 0;
    });
  }

  void _submitClue(String clue, int count) {
    setState(() {
      _currentClue = clue;
      _clueCount = count;
      _guessesLeft = count + 1;
      _gameState = CodenamesLocalGameState.passPhoneToAgents;
    });
  }

  void _selectWord(String word) {
    if (_revealedWords[word] == true) return;

    String actualColor = _wordKeyMap[word]!;
    String opponentTeam = (_activeTeam == 'red') ? 'blue' : 'red';
    bool turnEnded = false;

    setState(() {
      _revealedWords[word] = true;

      if (actualColor == 'assassin') {
        _gameResult =
            "L'équipe ${_activeTeam == 'red' ? 'Rouge' : 'Bleue'} a révélé l'Assassin ! L'équipe ${opponentTeam == 'red' ? 'Rouge' : 'Bleue'} gagne !";
        _gameState = CodenamesLocalGameState.gameOver;
        return;
      }

      if (actualColor == _activeTeam) {
        if (_activeTeam == 'red') {
          _redScore--;
        } else {
          _blueScore--;
        }
        _guessesLeft--;
        if (_redScore == 0 || _blueScore == 0) {
          _gameResult =
              "L'équipe ${_activeTeam == 'red' ? 'Rouge' : 'Bleue'} a trouvé tous ses mots et gagne !";
          _gameState = CodenamesLocalGameState.gameOver;
          return;
        }
      } else {
        if (actualColor != 'neutral') {
          if (actualColor == 'red')
            _redScore--;
          else
            _blueScore--;

          if (_redScore == 0 || _blueScore == 0) {
            _gameResult =
                "L'équipe ${actualColor == 'red' ? 'Rouge' : 'Bleue'} a trouvé tous ses mots et gagne !";
            _gameState = CodenamesLocalGameState.gameOver;
            return;
          }
        }
        turnEnded = true;
      }

      if (_guessesLeft == 0 || turnEnded) {
        _changeTurn();
      }
    });
  }

  void _changeTurn() {
    setState(() {
      _activeTeam = (_activeTeam == 'red') ? 'blue' : 'red';
      _currentClue = null;
      _clueCount = 0;
      _guessesLeft = 0;
      _masterSpyReady = false;
      _gameState = CodenamesLocalGameState.passPhoneToMasterSpy;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text("Codenames"),
        actions: [
          IconButton(
            icon: Icon(Icons.info_outline),
            onPressed: () => showGameRules(context, 'Codenames'),
          ),
        ],
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: AnimatedSwitcher(
          duration: Duration(milliseconds: 300),
          child: _buildContent(),
        ),
      ),
    );
  }

  Widget _buildContent() {
    switch (_gameState) {
      case CodenamesLocalGameState.setup:
        return _buildSetupPhase();
      case CodenamesLocalGameState.passPhoneToMasterSpy:
        return _buildPassPhoneToMasterSpy();
      case CodenamesLocalGameState.masterSpyTurn:
        return _buildMasterSpyTurn();
      case CodenamesLocalGameState.passPhoneToAgents:
        return _buildPassPhoneToAgents();
      case CodenamesLocalGameState.agentTurn:
        return _buildAgentTurn();
      case CodenamesLocalGameState.gameOver:
        return _buildGameOverScreen();
    }
  }

